def _workflow_display_name(workflow_kind: str | None = None) -> str:
    return str(workflow_kind or _workflow_kind() or "")


def _native_interactive_enabled() -> bool:
    raw = _read_native_env("INTERACTIVE", "1").strip().lower()
    return raw not in {"0", "false", "no", "off"}


def _stdin_is_interactive() -> bool:
    try:
        return bool(sys.stdin.isatty())
    except Exception:
        return False


def _stay_interactive_after_verified() -> bool:
    """Opt-in escape hatch to keep the chat prompt open after a verified completion.

    By default a fully verified workflow (all goals closed, no sorries) exits cleanly so
    the shell is returned to the user — running ``leanflow workflow prove file.lean`` and
    succeeding should hand the terminal back, not drop into a chat loop. Set
    ``LEANFLOW_NATIVE_STAY_AFTER_VERIFIED=1`` to restore the old behavior of entering the
    interactive prompt after completion.
    """
    raw = _read_native_env("STAY_AFTER_VERIFIED", "0").strip().lower()
    return raw in {"1", "true", "yes", "on"}


def _verified_workflow_should_exit_without_prompt(live_state: Mapping[str, Any]) -> bool:
    """Whether a verified workflow should exit cleanly instead of prompting.

    A verified proof exits without the interactive chat loop in BOTH headless and TTY
    runs: there is nothing left to do once every goal is closed, so blocking on a chat
    prompt only strands the terminal. The single exception is the opt-in
    ``LEANFLOW_NATIVE_STAY_AFTER_VERIFIED`` flag combined with a real TTY, which preserves
    the legacy post-completion chat.
    """
    if not _live_state_is_verified(live_state):
        return False
    if _stdin_is_interactive() and _stay_interactive_after_verified():
        return False
    return True


def _workflow_completion_exit_code(
    live_state: Mapping[str, Any] | None,
    autonomy_state: Mapping[str, Any] | None = None,
) -> int:
    """Return a truthful process code for the current mathematical state."""
    if str((autonomy_state or {}).get("operational_pause", "") or ""):
        # Cross-artifact or infrastructure ambiguity outranks cached
        # mathematical conclusions.  Normal exit paths already apply this
        # ordering; keep the finally-block fallback equally fail closed.
        return EXIT_PAUSED
    if str((autonomy_state or {}).get("terminal_outcome", "") or "") == "disproved":
        return EXIT_DISPROVED
    if _live_state_is_verified(live_state):
        return 0
    return EXIT_PAUSED


def _reconcile_stale_workflow_file_locks() -> int:
    """Release file leases owned by workflow sessions known to be terminal."""
    terminal_statuses = {"completed", "exited", "stopped", "interrupted", "dead", "failed"}
    dead_owners = [
        str(summary.get("agent_id", "") or "")
        for summary in summarize_workflow_agents(activity_limit=1)
        if str(summary.get("status", "") or "") in terminal_statuses
    ]
    result = release_stale_file_locks(dead_owner_ids=dead_owners)
    released = list(result.get("released") or [])
    if released:
        _record_activity(
            "stale-file-locks-released",
            f"Released {len(released)} file lock(s) held by terminal workflow sessions",
            released=released,
            dead_owner_ids=dead_owners,
        )
    return len(released)


def _record_campaign_exit(
    exit_code: int,
    autonomy_state: dict[str, Any],
    live_state: Mapping[str, Any] | None,
    *,
    reason: str = "",
) -> int:
    """Persist a prove campaign's truthful process result and return it."""
    recorded = autonomy_state.get("_native_process_exit_recorded")
    if isinstance(recorded, Mapping):
        return int(recorded.get("exit_code", exit_code) or 0)
    if _workflow_kind() == "prove":
        _shutdown_campaign_research(
            autonomy_state,
            reason=reason or f"process exit {exit_code}",
        )
        campaign_epoch.record_process_exit(
            autonomy_state,
            exit_code,
            verified=exit_code == 0 or _live_state_is_verified(live_state),
            reason=reason,
        )
    # Cache only after every required durable action succeeds.  A failed
    # process-exit write must remain retryable by the finalizer's corrective
    # pause transaction.
    autonomy_state["_native_process_exit_recorded"] = {
        "exit_code": int(exit_code),
        "reason": reason,
    }
    return exit_code


def _shutdown_campaign_research(
    autonomy_state: dict[str, Any],
    *,
    reason: str,
) -> dict[str, Any]:
    """Stop and prove closure of a campaign's process-isolated research portfolio."""
    if autonomy_state.get("_native_research_portfolio_stopped"):
        return {"success": True, "already_stopped": True, "residual": []}
    if _workflow_kind() != "prove" or not research_mode.research_mode_enabled():
        autonomy_state["_native_research_portfolio_stopped"] = True
        return {"success": True, "residual": []}
    campaign = campaign_epoch.ensure_campaign(autonomy_state)
    campaign_id = str(campaign.get("campaign_id", "") or "campaign")
    service = research_portfolio.DispatchService(root_job_id=campaign_id)
    killed = research_portfolio.shutdown_portfolio(
        campaign_id=campaign_id,
        reason=reason,
    )
    live_processes: list[str] = []
    for entry in service.shutdown_audit_entries():
        # Legacy runners could persist a terminal verdict before proving that
        # SIGTERM succeeded. Audit those rows alongside the post-shutdown open
        # set; ledger state alone is not an exact PID/session exit proof. The
        # filtered snapshot deliberately avoids cold terminal result payloads.
        if entry.is_terminal() and entry.state != "killed":
            continue
        if entry.state == "killed":
            # Reuse the portfolio's durable legacy-release authority here.
            # A PID can be reused long after a killed worker's exact exit was
            # recorded; probing that unrelated process as the old worker would
            # otherwise make an interrupt checkpoint fail forever.
            if not research_portfolio.terminal_killed_process_released(
                entry,
                service=service,
            ):
                live_processes.append(entry.spec.job_id)
            continue
        if entry.process_id <= 0 or dispatch_runtime._dispatch_process_identity_has_exited(entry):
            continue
        retired = dispatch_runtime._terminate_dispatch_process_and_wait(entry)
        if retired and not entry.is_terminal():
            # The portfolio's first kill attempt may have left the row open
            # because exit was not yet provable. Persist the terminal verdict
            # now that this final quiescence pass established the boundary.
            with contextlib.suppress(Exception):
                service.kill(entry.spec.job_id, requester_job_id=campaign_id)
        if not dispatch_runtime._dispatch_process_identity_has_exited(entry):
            live_processes.append(entry.spec.job_id)
    residual = [entry.spec.job_id for entry in service.open_jobs()]
    if live_processes or residual:
        raise RuntimeError(
            "research portfolio did not quiesce; "
            f"live processes={live_processes}, open jobs={residual}"
        )
    autonomy_state["_native_research_portfolio_stopped"] = True
    return {
        "success": True,
        "killed": list(killed),
        "residual": [],
    }


def _native_writer_join_timeout_s() -> float:
    """Return the bounded wait used to prove native writer threads stopped."""
    raw = str(os.getenv("LEANFLOW_NATIVE_WRITER_JOIN_TIMEOUT_S", "2") or "2")
    try:
        return max(0.1, min(30.0, float(raw)))
    except ValueError:
        return 2.0


class _NativeWriterKind(Enum):
    """Identify writer classes with distinct finalization policy."""

    FOREGROUND = "foreground"
    PARENT_MAINTAINED = "parent-maintained"


class _NativeStopSubsystem(Enum):
    """Identify owned-work stop steps without parsing rendered errors."""

    LOCAL_LEAN_COMMANDS = "local Lean commands"
    FOREGROUND_WRITERS = "foreground writers"
    DESCENDANT_AGENTS = "descendant agents"
    PROJECT_AGENTS = "project agents"
    RESEARCH_PORTFOLIO = "research portfolio"
    VERIFICATION_BATCH_ADMISSION = "post-edit verification admission"
    HELPER_INTEGRATION_ADMISSION = "helper integration admission"
    RUNTIME_SERVICES = "runtime services"


@dataclass(frozen=True)
class _NativeWriterFailure:
    """Describe one typed writer-quiescence failure."""

    writer_kind: _NativeWriterKind
    detail: str


class _NativeWriterQuiescenceError(RuntimeError):
    """Report the exact writer classes that remained unsafe."""

    def __init__(self, failures: Sequence[_NativeWriterFailure]):
        self.failures = tuple(failures)
        super().__init__("; ".join(failure.detail for failure in self.failures))

    @property
    def exclusively_foreground(self) -> bool:
        """Return whether every failure belongs to the managed foreground writer."""
        return bool(self.failures) and all(
            failure.writer_kind is _NativeWriterKind.FOREGROUND for failure in self.failures
        )


@dataclass(frozen=True)
class _NativeStopFailure:
    """Preserve one owned-work subsystem failure for finalization policy."""

    subsystem: _NativeStopSubsystem
    error: BaseException


class _NativeOwnedWorkStopError(RuntimeError):
    """Aggregate typed failures after attempting every owned-work stop step."""

    def __init__(self, failures: Sequence[_NativeStopFailure]):
        self.failures = tuple(failures)
        super().__init__(
            "; ".join(
                f"{failure.subsystem.value}: {type(failure.error).__name__}: "
                f"{str(failure.error)[:160]}"
                for failure in self.failures
            )
        )

    @property
    def exclusively_foreground_writer_quiescence(self) -> bool:
        """Return whether bounded foreground drainage is the sole failed step."""
        if len(self.failures) != 1:
            return False
        failure = self.failures[0]
        return (
            failure.subsystem is _NativeStopSubsystem.FOREGROUND_WRITERS
            and isinstance(failure.error, _NativeWriterQuiescenceError)
            and failure.error.exclusively_foreground
        )

    @property
    def exclusively_writer_quiescence(self) -> bool:
        """Return whether the sole failed subsystem is an owned writer set."""
        if len(self.failures) != 1:
            return False
        failure = self.failures[0]
        return failure.subsystem is _NativeStopSubsystem.FOREGROUND_WRITERS and isinstance(
            failure.error,
            _NativeWriterQuiescenceError,
        )

    @property
    def writer_kinds(self) -> frozenset[_NativeWriterKind]:
        """Return typed writer classes retained by one quiescence-only failure."""
        if not self.exclusively_writer_quiescence:
            return frozenset()
        error = self.failures[0].error
        assert isinstance(error, _NativeWriterQuiescenceError)
        return frozenset(failure.writer_kind for failure in error.failures)

    @property
    def signal_checkpoint_safe_runtime_cleanup(self) -> bool:
        """Return whether only read-only Lean runtime services failed to close."""
        return bool(self.runtime_cleanup_labels) and set(self.runtime_cleanup_labels) <= {
            "incremental Lean sessions",
            "MCP servers",
        }

    @property
    def runtime_cleanup_labels(self) -> tuple[str, ...]:
        """Return controlled runtime labels from a runtime-only shutdown failure."""
        if len(self.failures) != 1:
            return ()
        failure = self.failures[0]
        if failure.subsystem is not _NativeStopSubsystem.RUNTIME_SERVICES:
            return ()
        prefix = "runtime shutdown failed for: "
        message = str(failure.error)
        if not message.startswith(prefix):
            return ()
        return tuple(label.strip() for label in message[len(prefix) :].split(",") if label.strip())


def _quiesce_native_writer_threads(agent: Any) -> None:
    """Interrupt and boundedly join foreground conversation/planner writers."""
    failures: list[_NativeWriterFailure] = []
    termination: BaseException | None = None
    interrupt = getattr(agent, "interrupt", None) if agent is not None else None
    if agent is not None:
        if callable(interrupt):
            with contextlib.suppress(Exception):
                interrupt("native runner finalization")
        worker = getattr(agent, "_managed_foreground_worker", None)
        if isinstance(worker, threading.Thread):
            if worker is threading.current_thread():
                failures.append(
                    _NativeWriterFailure(
                        _NativeWriterKind.FOREGROUND,
                        "foreground worker is the current finalizer thread",
                    )
                )
            else:
                try:
                    worker.join(timeout=_native_writer_join_timeout_s())
                except Exception as exc:
                    failures.append(
                        _NativeWriterFailure(
                            _NativeWriterKind.FOREGROUND,
                            "foreground worker join failed: "
                            f"{type(exc).__name__}: {str(exc)[:160]}",
                        )
                    )
                else:
                    if worker.is_alive():
                        failures.append(
                            _NativeWriterFailure(
                                _NativeWriterKind.FOREGROUND,
                                f"foreground worker {worker.name!r} is still live",
                            )
                        )
                    elif getattr(agent, "_managed_foreground_worker", None) is worker:
                        delattr(agent, "_managed_foreground_worker")

    try:
        residual = quiesce_parent_maintained_actions(
            cancel=(
                (lambda: interrupt("native runner planner finalization"))
                if callable(interrupt)
                else None
            ),
            timeout_s=_native_writer_join_timeout_s(),
        )
    except (NativeTerminationSignal, KeyboardInterrupt) as exc:
        termination = exc
    except BaseException as exc:
        failures.append(
            _NativeWriterFailure(
                _NativeWriterKind.PARENT_MAINTAINED,
                f"planner worker cleanup failed: {type(exc).__name__}: {str(exc)[:160]}",
            )
        )
    else:
        if residual:
            failures.append(
                _NativeWriterFailure(
                    _NativeWriterKind.PARENT_MAINTAINED,
                    "parent-maintained writer(s) remain live: " + ", ".join(residual),
                )
            )
    if termination is not None:
        raise termination
    if failures:
        raise _NativeWriterQuiescenceError(failures)


def _prove_terminated_workflow_agents_gone(result: Mapping[str, Any]) -> None:
    """Escalate exact signaled workflow identities and prove they disappeared."""
    failed = list(result.get("failed") or [])
    if result.get("success") is False or failed:
        raise RuntimeError(f"workflow-agent termination failed: {failed or result}")
    terminated = [str(item or "").strip() for item in (result.get("terminated") or [])]
    failures: list[str] = []
    for agent_id in terminated:
        detail = workflow_agent_detail(agent_id, activity_limit=1)
        identity = process_identity_from_mapping(detail)
        if not identity.verifiable:
            failures.append(f"{agent_id}: persisted process identity unavailable")
            continue
        if identity.pid == os.getpid():
            failures.append(f"{agent_id}: termination resolved to the current process")
            continue
        if process_identity_matches(identity):
            terminate_process_tree(
                identity.pid,
                expected_session_id=(
                    identity.session_id if identity.session_id == identity.pid else None
                ),
                include_root=True,
                term_grace_s=min(1.0, _native_writer_join_timeout_s()),
            )
        deadline = time.monotonic() + _native_writer_join_timeout_s()
        while process_identity_matches(identity) and time.monotonic() < deadline:
            time.sleep(0.05)
        if process_identity_matches(identity):
            failures.append(f"{agent_id}: exact process identity remains live")
    if failures:
        raise RuntimeError("; ".join(failures))


def _stop_native_owned_work(
    agent: Any,
    autonomy_state: dict[str, Any],
    *,
    reason: str,
) -> None:
    """Reconcile agents, research jobs, and process-owned runtime services."""
    steps: list[tuple[_NativeStopSubsystem, Callable[[], Any]]] = [
        (
            _NativeStopSubsystem.LOCAL_LEAN_COMMANDS,
            terminate_active_lean_commands,
        ),
        (
            _NativeStopSubsystem.FOREGROUND_WRITERS,
            lambda: _quiesce_native_writer_threads(agent),
        ),
    ]
    if agent is not None:
        steps.extend(
            [
                (
                    _NativeStopSubsystem.DESCENDANT_AGENTS,
                    lambda: _terminate_descendant_agents(agent),
                ),
                (
                    _NativeStopSubsystem.PROJECT_AGENTS,
                    lambda: _terminate_other_agents(agent),
                ),
            ]
        )
    steps.extend(
        [
            (
                _NativeStopSubsystem.RESEARCH_PORTFOLIO,
                lambda: _shutdown_campaign_research(autonomy_state, reason=reason),
            ),
            (
                _NativeStopSubsystem.VERIFICATION_BATCH_ADMISSION,
                lambda: verification_batch_admission.release(
                    agent,
                    reason="native runner owned-work shutdown",
                ),
            ),
            (
                _NativeStopSubsystem.HELPER_INTEGRATION_ADMISSION,
                lambda: helper_integration_admission.release(
                    agent,
                    reason="native runner owned-work shutdown",
                ),
            ),
            (
                _NativeStopSubsystem.RUNTIME_SERVICES,
                lambda: shutdown_native_runtime_services(agent),
            ),
        ]
    )
    failures: list[_NativeStopFailure] = []
    termination: BaseException | None = None
    for label, stop in steps:
        try:
            result = stop()
            if label in {
                _NativeStopSubsystem.DESCENDANT_AGENTS,
                _NativeStopSubsystem.PROJECT_AGENTS,
            } and isinstance(result, Mapping):
                _prove_terminated_workflow_agents_gone(result)
            if label is _NativeStopSubsystem.LOCAL_LEAN_COMMANDS and result:
                raise RuntimeError(
                    "local Lean command processes remain live: " + ", ".join(map(str, result))
                )
            if label is _NativeStopSubsystem.RUNTIME_SERVICES and result:
                raise RuntimeError("runtime shutdown failed for: " + ", ".join(map(str, result)))
        except (NativeTerminationSignal, KeyboardInterrupt) as exc:
            logger.warning(
                "Termination requested while stopping native runner %s: %s",
                label.value,
                exc,
            )
            if termination is None:
                termination = exc
        except BaseException as exc:
            logger.warning("Failed to stop native runner %s: %s", label.value, exc)
            failures.append(_NativeStopFailure(label, exc))
    if termination is not None:
        raise termination
    if failures:
        raise _NativeOwnedWorkStopError(failures)


def _release_native_runner_locks(agent: Any) -> None:
    """Release every lock and process artifact associated with one runner."""
    owner_ids = {
        str(_runner_owner_id() or "").strip(),
        str(getattr(agent, "session_id", "") or "").strip(),
    }
    failures: list[str] = []
    termination: BaseException | None = None
    for owner_id in sorted(owner_ids - {""}):
        try:
            result = release_all_file_locks(owner_id=owner_id, strict=True)
        except (NativeTerminationSignal, KeyboardInterrupt) as exc:
            logger.warning(
                "Termination requested while releasing native runner locks for %s: %s",
                owner_id,
                exc,
            )
            if termination is None:
                termination = exc
            continue
        except BaseException as exc:
            logger.warning("Failed to release native runner locks for %s: %s", owner_id, exc)
            failures.append(f"{owner_id}: {type(exc).__name__}: {str(exc)[:160]}")
            continue
        if result.get("success") is not True:
            detail = str(result.get("error", "lock release failed") or "")
            logger.warning("Failed to release native runner locks for %s: %s", owner_id, detail)
            failures.append(f"{owner_id}: {detail[:180]}")
    try:
        process_artifact_cleanup.release_native_process_artifacts(_project_root())
    except (NativeTerminationSignal, KeyboardInterrupt) as exc:
        logger.warning("Termination requested while releasing native process artifacts: %s", exc)
        if termination is None:
            termination = exc
    except BaseException as exc:
        logger.warning("Failed to release native process artifacts: %s", exc)
        failures.append(f"process artifacts: {type(exc).__name__}: {str(exc)[:160]}")
    if termination is not None:
        raise termination
    if failures:
        raise RuntimeError("; ".join(failures))


def _native_runner_exit_message(exit_code: int, reason: str) -> str:
    """Return a stable activity message for a truthful process outcome."""
    if exit_code == 0:
        return "Managed workflow runner exited after verified completion"
    if exit_code == EXIT_INTERRUPTED:
        return "Managed workflow runner interrupted by signal"
    if exit_code == EXIT_DISPROVED:
        return "Managed workflow runner exited after authoritative disproof"
    if exit_code == EXIT_PAUSED:
        return f"Managed workflow runner exited with resumable pause: {reason or 'unresolved'}"
    return f"Managed workflow runner exited after runtime failure: {reason or 'unknown'}"


def _mark_finalization_pause(
    autonomy_state: dict[str, Any],
    reason: str,
    *,
    infrastructure: bool,
) -> None:
    """Persist a fail-closed pause selected by post-quiescence truth checks."""
    promotion_state = dict(autonomy_state.get("negation_promotion") or {})
    evidence = dict(promotion_state.get("evidence") or {})
    theorem = str(evidence.get("theorem", "") or "").strip()
    source_file = str(
        evidence.get("operation_path", "")
        or evidence.get("file", "")
        or evidence.get("scope_root_file", "")
        or ""
    ).strip()

    def stale_disproof_outcome(raw: Any) -> bool:
        if not isinstance(raw, Mapping):
            return False
        if str(raw.get("status", "") or "").strip().lower() != "disproved":
            return False
        if theorem and str(raw.get("target_symbol", "") or "").strip() != theorem:
            return False
        candidate_file = str(raw.get("active_file", "") or "").strip()
        return (
            not source_file or not candidate_file or _same_active_file(candidate_file, source_file)
        )

    outcomes = dict(autonomy_state.get("theorem_outcomes") or {})
    retained_outcomes = {
        key: raw for key, raw in outcomes.items() if not stale_disproof_outcome(raw)
    }
    if retained_outcomes != outcomes:
        if retained_outcomes:
            autonomy_state["theorem_outcomes"] = retained_outcomes
        else:
            autonomy_state.pop("theorem_outcomes", None)
        invalidate_live_queue_manager(autonomy_state)
    last_outcome = autonomy_state.get("last_theorem_outcome")
    if stale_disproof_outcome(last_outcome):
        autonomy_state.pop("last_theorem_outcome", None)
    autonomy_state.pop("terminal_outcome", None)
    autonomy_state.pop("negation_promotion", None)
    autonomy_state.pop("final_report_written", None)
    autonomy_state.pop("learnings_written", None)
    autonomy_state.pop("_native_process_exit_recorded", None)

    def retire_stale_disproof(summary: dict[str, Any]) -> None:
        report = summary.get("final_report")
        if isinstance(report, Mapping) and str(report.get("status", "") or "") == "disproved":
            summary.pop("final_report", None)
        queue_state = summary.get("queue_manager_state")
        if isinstance(queue_state, Mapping):
            updated_queue_state = dict(queue_state)
            durable_outcomes = dict(updated_queue_state.get("theorem_outcomes") or {})
            retained = {
                key: raw for key, raw in durable_outcomes.items() if not stale_disproof_outcome(raw)
            }
            if retained:
                updated_queue_state["theorem_outcomes"] = retained
            else:
                updated_queue_state.pop("theorem_outcomes", None)
            summary["queue_manager_state"] = updated_queue_state

    with contextlib.suppress(Exception):
        negation_promotion.update_json_file(
            plan_state.plan_state_paths().summary_json,
            retire_stale_disproof,
        )
    if infrastructure:
        autonomy_state.update(
            {
                "operational_pause": "paused_infrastructure",
                "infrastructure_pause_reason": reason,
            }
        )
    else:
        autonomy_state.update(
            {
                "operational_pause": "paused_source_quarantine",
                "source_quarantine_reason": reason,
                "source_quarantine_origin": "final-mathematical-verification",
            }
        )
    with contextlib.suppress(Exception):
        campaign_epoch.record_status(autonomy_state, "paused", reason=reason)


def _revalidate_verified_scope_after_quiescence(
    history: list[dict[str, Any]],
    checkpoint_state: Mapping[str, Any] | None,
    autonomy_state: dict[str, Any],
    *,
    expected_live_state: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Kernel-verify the exact requested Lean scope after writers stop."""
    expected = dict(expected_live_state or {})
    if str(
        expected.get("proof_state_authority", "") or ""
    ) == "authenticated_target_gate" and _live_state_is_verified(expected):
        revision = source_only_startup.SourceRevision.from_mapping(
            dict(expected.get("source_revision") or {})
        )
        if revision is not None and source_only_startup.source_revision_is_current(revision):
            _record_activity(
                "terminal-authenticated-gate-reused",
                "Reused the authenticated source revision after workflow writers quiesced",
                active_file=revision.path,
                source_revision_sha256=revision.sha256,
                queue_total=int(expected.get("declaration_queue_total", 0) or 0),
            )
            return expected
    exact = _provider_free_exact_scope_state(
        history,
        checkpoint_state,
        autonomy_state,
        expected_live_state=expected,
    )
    if exact:
        return exact
    fresh = _build_live_proof_state_compat(history, checkpoint_state, autonomy_state)
    return _promote_live_state_to_verified_compat(fresh, autonomy_state)


def _revalidate_disproof_after_quiescence(
    autonomy_state: dict[str, Any],
) -> negation_promotion.PromotionReconciliation:
    """Rerun exact requested-root disproof reconciliation after writers stop."""
    reconciliation = _reconcile_negation_promotions_on_startup(autonomy_state)
    _pause_for_negation_reconciliation(reconciliation, autonomy_state)
    return reconciliation


def _terminal_authority_source_paths(
    exit_code: int,
    live_state: Mapping[str, Any] | None,
    autonomy_state: Mapping[str, Any],
) -> tuple[Path, ...]:
    """Return every requested source that must stay leased through terminal commit."""
    root = Path(_project_root()).expanduser().resolve()
    raw_paths: list[str | Path] = []
    if exit_code == EXIT_DISPROVED:
        promotion = dict(autonomy_state.get("negation_promotion") or {})
        evidence = dict(promotion.get("evidence") or {})
        exact_file = str(evidence.get("operation_path", "") or evidence.get("file", "") or "")
        if exact_file:
            raw_paths.append(exact_file)
        campaign = plan_state.load_summary().get("campaign")
        root_audit = negation_promotion._validate_campaign_root_registry(campaign)
        if not root_audit.ok:
            raise RuntimeError(root_audit.reason)
        raw_paths.extend(str(item["operation_path"]) for item in root_audit.roots)
    else:
        current = dict(live_state or {})
        scope = str(current.get("declaration_scope", "") or _declaration_queue_scope())
        active_file = str(current.get("active_file", "") or "").strip()
        if scope == "file" and active_file:
            raw_paths.append(active_file)
        else:
            raw_paths.extend(_project_lean_files(str(root)))
            if active_file:
                raw_paths.append(active_file)

    canonical: set[Path] = set()
    for raw in raw_paths:
        path = Path(raw).expanduser()
        if not path.is_absolute():
            path = root / path
        canonical.add(path.resolve(strict=True))
    return tuple(sorted(canonical, key=str))


def _terminal_authority_namespace_paths(
    exit_code: int,
    live_state: Mapping[str, Any] | None,
) -> tuple[Path, ...]:
    """Return project namespaces that must reject late Lean-file creation."""
    if exit_code != 0:
        return ()
    current = dict(live_state or {})
    scope = str(current.get("declaration_scope", "") or _declaration_queue_scope())
    if scope == "file":
        return ()
    return (Path(_project_root()).expanduser().resolve(strict=True),)


def _terminal_authority_snapshot_is_current(
    snapshot: terminal_authority.TerminalAuthoritySnapshot,
    *,
    blueprint_revision: int,
) -> bool:
    """Recheck leased source bytes and graph revision before terminal selection."""
    try:
        if plan_state.load_blueprint().revision != int(blueprint_revision):
            return False
        return all(
            decomposition_provenance.read_source_bytes(operation)
            == snapshot.source_bytes[str(operation.path)]
            for operation in snapshot.operations
        )
    except (OSError, KeyError, TypeError, ValueError):
        return False


def _refresh_interrupted_live_state_after_quiescence(
    live_state: Mapping[str, Any] | None,
    autonomy_state: Mapping[str, Any],
) -> dict[str, Any]:
    """Refresh signal-exit status from the durable queue and source bytes.

    This deliberately avoids Lean, MCP, and provider startup during signal
    cleanup. The linked filesystem snapshot remains the resume authority; the
    refresh only prevents an outer-loop state cached before a followup from
    misreporting its current assignment and deterministic sorry counts.
    """
    current = dict(live_state or {})

    # A signal exit never reuses assignment-specific model or kernel prose.
    # Resume will rebuild authoritative Lean state; this bounded source scan
    # exists only to publish a truthful checkpoint identity in the meantime.
    for stale_key in (
        "blocker_summary",
        "current_blocker",
        "diagnostics",
        "goals",
        "build_status",
        "declaration_queue_summary",
        "message",
        "current_queue_item_prefix",
        "current_queue_item_slice",
        "route_decision",
    ):
        current.pop(stale_key, None)
    current["proof_solved"] = False
    current["verification_ok"] = False
    current["last_verification"] = {}

    def mark_reconciliation_pending(reason: str, *, clear_counts: bool) -> dict[str, Any]:
        """Fail closed when source identity cannot be refreshed deterministically."""
        current["source_reconciliation_pending"] = True
        current["source_reconciled_after_quiescence"] = False
        current["proof_solved"] = False
        current["verification_ok"] = False
        current["last_verification"] = {}
        current["current_queue_item"] = {}
        current["current_queue_item_slice"] = ""
        current["current_blocker"] = reason
        current["blocker_summary"] = reason
        if clear_counts:
            current.pop("sorry_count", None)
            current.pop("project_sorry_count", None)
            current.pop("project_sorry_files", None)
        return current

    assignment = dict(autonomy_state.get("current_queue_assignment") or {})
    target_symbol = str(
        assignment.get("target_symbol", "") or current.get("target_symbol", "") or ""
    ).strip()
    active_file = str(
        assignment.get("active_file", "")
        or current.get("active_file", "")
        or current.get("active_file_label", "")
        or ""
    ).strip()
    if target_symbol:
        current["target_symbol"] = target_symbol
    if not active_file:
        return mark_reconciliation_pending(
            "signal checkpoint could not resolve the active source file",
            clear_counts=True,
        )

    path = Path(active_file).expanduser()
    if not path.is_absolute():
        path = Path(_project_root()).expanduser() / path
    try:
        path = path.resolve(strict=True)
    except OSError:
        current["active_file"] = str(path)
        return mark_reconciliation_pending(
            f"signal checkpoint could not read active source file `{path}`",
            clear_counts=True,
        )

    current["active_file"] = str(path)
    try:
        current["active_file_label"] = str(
            path.relative_to(Path(_project_root()).expanduser().resolve())
        )
    except ValueError:
        current["active_file_label"] = str(path)

    sorry_count = _count_sorries(str(path))
    if isinstance(sorry_count, int):
        current["sorry_count"] = sorry_count
    project_sorry_count, project_sorry_files = _count_project_sorries(_project_root())
    if isinstance(project_sorry_count, int):
        current["project_sorry_count"] = project_sorry_count
        current["project_sorry_files"] = project_sorry_files

    declaration = _find_declaration_entry(str(path), target_symbol) if target_symbol else None
    if target_symbol and declaration is None:
        return mark_reconciliation_pending(
            f"durable queue target `{target_symbol}` was not found in `{path}`",
            clear_counts=False,
        )
    if declaration:
        reasons = ["contains sorry"] if declaration.get("has_sorry") else ["unresolved"]
        current_item = {
            "label": target_symbol,
            "kind": str(declaration.get("kind", "") or ""),
            "file": str(path),
            "line": int(declaration.get("line", 0) or 0),
            "end_line": int(declaration.get("end_line", 0) or 0),
            "reasons": reasons,
        }
        current["current_queue_item"] = current_item
        current["current_queue_item_slice"] = _declaration_slice_text(str(path), target_symbol)
        source_queue = _declaration_work_queue(
            str(path),
            "",
            project_root=_project_root(),
            scope="file",
        )
        normalized_queue: list[dict[str, Any]] = []
        target_present = False
        for raw_item in source_queue:
            item = dict(raw_item)
            if str(item.get("label", "") or "") == target_symbol:
                item.update(current_item)
                target_present = True
            normalized_queue.append(item)
        if not target_present:
            normalized_queue.insert(0, current_item)
        current["declaration_queue_total"] = len(normalized_queue)
        current["declaration_queue_preview"] = normalized_queue[:8]
        current["declaration_queue_summary"] = _format_declaration_queue(normalized_queue)
    current["diagnostics"] = (
        f"Deterministic signal checkpoint scan found {sorry_count} `sorry` placeholder(s) "
        f"in `{path.name}`."
        if isinstance(sorry_count, int)
        else "Deterministic signal checkpoint source scan completed."
    )
    current["goals"] = "Lean goals require revalidation after resume."
    current["build_status"] = "signal checkpoint requires Lean revalidation on resume"
    current["current_blocker"] = (
        f"`{target_symbol}` remains unresolved at the signal checkpoint."
        if target_symbol
        else "The active target requires reconciliation after resume."
    )
    current["blocker_summary"] = current["current_blocker"]
    current.pop("source_reconciliation_pending", None)
    current["source_reconciled_after_quiescence"] = True
    return current


def _finalize_native_run(
    finalizer: NativeRunFinalizer,
    exit_code: int,
    *,
    agent: Any,
    history: list[dict[str, Any]],
    compaction_state: Mapping[str, Any] | None,
    checkpoint_state: Mapping[str, Any] | None,
    autonomy_state: dict[str, Any],
    live_state: Mapping[str, Any] | None,
    reason: str,
    message: str = "",
) -> int:
    """Finalize one native process through the shared ordered exit gate."""
    outcome: dict[str, Any] = {
        "exit_code": int(exit_code),
        "reason": str(reason or ""),
        "message": str(message or ""),
        "live_state": dict(live_state or {}),
    }
    quiescence_errors: list[str] = []
    runtime_cleanup_warnings: list[str] = []
    pre_authority_errors: list[str] = []
    authority_errors: list[str] = []
    authority_box: dict[str, terminal_authority.TerminalAuthoritySnapshot] = {}
    disproof_box: dict[str, Any] = {}

    def stop_owned_work() -> None:
        try:
            _stop_native_owned_work(
                agent,
                autonomy_state,
                reason=str(outcome["reason"]),
            )
        except BaseException as exc:
            if isinstance(exc, (NativeTerminationSignal, KeyboardInterrupt)):
                raise
            if (
                int(outcome["exit_code"]) == EXIT_INTERRUPTED
                and isinstance(exc, _NativeOwnedWorkStopError)
                and exc.signal_checkpoint_safe_runtime_cleanup
            ):
                warning = f"{type(exc).__name__}: {str(exc)[:240]}"
                runtime_cleanup_warnings.append(warning)
                _record_agent_activity(
                    agent,
                    "signal-checkpoint-cleanup-warning",
                    "Signal checkpoint continued after read-only runtime cleanup warning",
                    trigger="signal-interrupt",
                    checkpoint_authoritative=True,
                    runtime_services=list(exc.runtime_cleanup_labels),
                    warning=warning,
                )
                return
            quiescence_errors.append(f"{type(exc).__name__}: {str(exc)[:240]}")
            if not (
                isinstance(exc, _NativeOwnedWorkStopError) and exc.exclusively_writer_quiescence
            ):
                raise
            # The complete stop pass has already attempted descendants,
            # research, and runtime services. Those service closures are the
            # cancellation mechanism for a planner blocked in an auxiliary
            # provider or Lean validation call. Give a captured foreground
            # conversation its dedicated drain when present, then re-prove the
            # whole typed writer set quiet without repeating subsystem shutdown.
            try:
                if _NativeWriterKind.FOREGROUND in exc.writer_kinds:
                    drain_managed_foreground_worker(
                        agent,
                        reason="native runner post-shutdown foreground drain",
                    )
                _quiesce_native_writer_threads(agent)
            except BaseException as retry_exc:
                quiescence_errors.append(f"{type(retry_exc).__name__}: {str(retry_exc)[:240]}")
                raise
            quiescence_errors.clear()

    @contextlib.contextmanager
    def outcome_authority() -> Iterator[None]:
        if _workflow_kind() != "prove" or int(outcome["exit_code"]) not in {
            0,
            EXIT_DISPROVED,
        }:
            yield
            return
        if quiescence_errors:
            # Never wait on cooperative source/graph authority while a writer
            # is known to remain live; that writer may itself hold one of the
            # leases. The selector below records a fail-closed pause directly.
            yield
            return
        # Startup reconciliation may recover or quarantine helper transactions,
        # which acquires helper-source leases before mutating the graph. Run that
        # complete mutation phase before the terminal graph guard; the guarded
        # phase below is deliberately read-only apart from durable outcome files.
        if not quiescence_errors:
            try:
                if int(outcome["exit_code"]) == EXIT_DISPROVED:
                    reconciliation = _revalidate_disproof_after_quiescence(autonomy_state)
                    disproof_box["reconciliation"] = reconciliation
                    disproof_box["promotion"] = (
                        negation_promotion.authoritative_runtime_main_promotion(
                            autonomy_state,
                            cwd=_project_root(),
                        )
                    )
                else:
                    disproof_box["verification_barrier"] = _negation_reconciliation_barrier(
                        autonomy_state
                    )
            except (NativeTerminationSignal, KeyboardInterrupt):
                raise
            except BaseException as exc:
                pre_authority_errors.append(f"{type(exc).__name__}: {str(exc)[:240]}")
        if (
            pre_authority_errors
            or autonomy_state.get("operational_pause")
            or bool(disproof_box.get("verification_barrier"))
            or (
                int(outcome["exit_code"]) == EXIT_DISPROVED
                and (
                    not isinstance(
                        disproof_box.get("reconciliation"),
                        negation_promotion.PromotionReconciliation,
                    )
                    or not disproof_box["reconciliation"].terminal_disproof
                    or not isinstance(disproof_box.get("promotion"), Mapping)
                )
            )
        ):
            # A rejected provisional outcome needs no terminal lease. The
            # selector below persists the resumable pause without widening the
            # critical section or waiting on unrelated source locks.
            yield
            return
        stack = contextlib.ExitStack()
        try:
            runtime_owner_id = str(
                _runner_owner_id() or getattr(agent, "session_id", "") or ""
            ).strip()
            namespaces = _terminal_authority_namespace_paths(
                int(outcome["exit_code"]),
                outcome.get("live_state"),
            )
            if namespaces:
                stack.enter_context(
                    terminal_authority.terminal_namespace_guard(
                        namespaces,
                        runtime_owner_id=runtime_owner_id,
                    )
                )
            # Enumerate project Lean sources only after the namespace lease is
            # held, so a cooperative writer cannot create an unverified file
            # between inventory selection and per-source acquisition.
            paths = _terminal_authority_source_paths(
                int(outcome["exit_code"]),
                outcome.get("live_state"),
                autonomy_state,
            )
            snapshot = stack.enter_context(
                terminal_authority.terminal_authority_guard(
                    paths,
                    runtime_owner_id=runtime_owner_id,
                )
            )
            authority_box["snapshot"] = snapshot
        except (NativeTerminationSignal, KeyboardInterrupt):
            # Best-effort release must not translate the original termination
            # request into an ordinary authority-cleanup failure.
            with contextlib.suppress(Exception):
                stack.close()
            raise
        except BaseException as exc:
            stack.close()
            authority_errors.append(f"{type(exc).__name__}: {str(exc)[:240]}")
            yield
            return
        try:
            yield
        finally:
            authority_box.clear()
            stack.close()

    def pause_reason(default: str) -> str:
        return str(
            autonomy_state.get("source_quarantine_reason", "")
            or autonomy_state.get("infrastructure_pause_reason", "")
            or autonomy_state.get("operational_pause", "")
            or default
        )

    def downgrade(reason_text: str, *, infrastructure: bool) -> int:
        _mark_finalization_pause(
            autonomy_state,
            reason_text,
            infrastructure=infrastructure,
        )
        outcome.update(
            {
                "exit_code": EXIT_PAUSED,
                "reason": reason_text,
                "message": "",
            }
        )
        return EXIT_PAUSED

    def mark_signal_interruption() -> int:
        """Replace provisional math metadata with an explicit signal exit."""
        outcome.update(
            {
                "exit_code": EXIT_INTERRUPTED,
                "reason": "signal interrupt",
                "message": "",
            }
        )
        if not quiescence_errors:
            outcome["live_state"] = _refresh_interrupted_live_state_after_quiescence(
                outcome.get("live_state"),
                autonomy_state,
            )
        try:
            # Retire any cached math artifacts, but do not turn explicit user
            # cancellation into a sticky infrastructure pause on resume.
            _mark_finalization_pause(
                autonomy_state,
                "signal interrupt",
                infrastructure=True,
            )
        finally:
            autonomy_state.pop("operational_pause", None)
            autonomy_state.pop("infrastructure_pause_reason", None)
        return EXIT_INTERRUPTED

    def select_outcome_after_quiescence_unchecked(selected_code: int) -> int:
        """Derive mathematical exit truth only after every owned writer stops."""
        outcome["exit_code"] = int(selected_code)
        if selected_code == EXIT_INTERRUPTED:
            return mark_signal_interruption()
        if _workflow_kind() != "prove" or selected_code not in {0, EXIT_DISPROVED}:
            return selected_code
        if quiescence_errors:
            return downgrade(
                "owned workflow writers did not quiesce before final verification: "
                + quiescence_errors[0],
                infrastructure=True,
            )
        if pre_authority_errors:
            return downgrade(
                "final mathematical reconciliation failed before terminal authority: "
                + pre_authority_errors[0],
                infrastructure=True,
            )
        if autonomy_state.get("operational_pause"):
            return downgrade(
                pause_reason("durable negation reconciliation pause"),
                infrastructure=(
                    str(autonomy_state.get("operational_pause", "") or "")
                    == "paused_infrastructure"
                ),
            )
        if selected_code == 0 and bool(disproof_box.get("verification_barrier")):
            return downgrade(
                pause_reason("durable negation reconciliation pause"),
                infrastructure=False,
            )
        if selected_code == EXIT_DISPROVED and (
            not isinstance(
                disproof_box.get("reconciliation"),
                negation_promotion.PromotionReconciliation,
            )
            or not disproof_box["reconciliation"].terminal_disproof
            or not isinstance(disproof_box.get("promotion"), Mapping)
        ):
            return downgrade(
                "cached disproof did not survive post-quiescence durable reconciliation",
                infrastructure=False,
            )
        if authority_errors or "snapshot" not in authority_box:
            detail = authority_errors[0] if authority_errors else "authority lease unavailable"
            return downgrade(
                "terminal source/graph authority could not be acquired: " + detail,
                infrastructure=True,
            )
        if selected_code == EXIT_DISPROVED:
            reconciliation = disproof_box.get("reconciliation")
            authoritative = disproof_box.get("promotion")
            exact_validation = (
                negation_promotion.revalidate_promotion(authoritative, cwd=_project_root())
                if isinstance(authoritative, Mapping)
                else negation_promotion.PromotionResult(
                    False, "runtime promotion is not durably authenticated"
                )
            )
            snapshot = authority_box["snapshot"]
            if (
                not isinstance(reconciliation, negation_promotion.PromotionReconciliation)
                or not reconciliation.terminal_disproof
                or not isinstance(authoritative, Mapping)
                or not exact_validation.ok
                or not exact_validation.is_main_goal
                or autonomy_state.get("operational_pause")
                or not _terminal_authority_snapshot_is_current(
                    snapshot,
                    blueprint_revision=snapshot.blueprint_revision,
                )
            ):
                return downgrade(
                    pause_reason(
                        "cached disproof did not survive post-quiescence source and graph revalidation"
                    ),
                    infrastructure=False,
                )
            return EXIT_DISPROVED

        try:
            fresh_live_state = _revalidate_verified_scope_after_quiescence(
                history,
                checkpoint_state,
                autonomy_state,
                expected_live_state=outcome.get("live_state"),
            )
        except (NativeTerminationSignal, KeyboardInterrupt):
            raise
        except BaseException as exc:
            return downgrade(
                "final Lean scope verification failed: " f"{type(exc).__name__}: {str(exc)[:200]}",
                infrastructure=True,
            )
        outcome["live_state"] = dict(fresh_live_state)
        snapshot = authority_box["snapshot"]
        if not _live_state_is_verified(
            fresh_live_state
        ) or not _terminal_authority_snapshot_is_current(
            snapshot,
            blueprint_revision=snapshot.blueprint_revision,
        ):
            return downgrade(
                "requested Lean scope no longer verifies after owned writers quiesced",
                infrastructure=False,
            )
        return 0

    def select_outcome_after_quiescence(selected_code: int) -> int:
        """Fail closed if the post-quiescence outcome selector itself breaks."""
        try:
            return select_outcome_after_quiescence_unchecked(selected_code)
        except (NativeTerminationSignal, KeyboardInterrupt):
            raise
        except BaseException as exc:
            if _workflow_kind() == "prove" and selected_code in {0, EXIT_DISPROVED}:
                return downgrade(
                    "final mathematical outcome selection failed: "
                    f"{type(exc).__name__}: {str(exc)[:200]}",
                    infrastructure=True,
                )
            raise

    def exit_live_state() -> dict[str, Any]:
        current = dict(outcome.get("live_state") or {})
        current.update(
            native_exit_status_fields(
                int(outcome["exit_code"]),
                str(outcome["reason"]),
            )
        )
        if int(outcome["exit_code"]) == EXIT_INTERRUPTED:
            current["interrupt_source"] = "signal"
        if runtime_cleanup_warnings:
            current["runtime_cleanup_warnings"] = list(runtime_cleanup_warnings)
        return current

    exit_checkpoint_state = checkpoint_state

    def record_checkpoint_failure(
        failure_reason: str,
        *,
        errors: Sequence[str] = (),
    ) -> None:
        """Publish why a signal exit could not produce a fresh checkpoint."""
        detail = {
            "trigger": "signal-interrupt",
            "checkpoint_written": False,
            "failure_reason": str(failure_reason or "unknown checkpoint failure"),
            "quiescence_errors": [str(item) for item in errors],
        }
        current = dict(outcome.get("live_state") or {})
        current["checkpoint_failure"] = dict(detail)
        outcome["live_state"] = current
        _record_agent_activity(
            agent,
            "checkpoint-failure",
            "Signal interruption checkpoint was not written",
            **detail,
        )

    def persist_checkpoint() -> None:
        nonlocal exit_checkpoint_state
        current_code = int(outcome["exit_code"])
        if quiescence_errors:
            # A live writer makes any filesystem snapshot non-authoritative.
            # Persist an explicit failure record and require resume-time
            # reconciliation instead of labeling racing bytes a checkpoint.
            if current_code == EXIT_INTERRUPTED:
                record_checkpoint_failure(
                    "owned workflow writers did not quiesce after the bounded retry",
                    errors=quiescence_errors,
                )
            return
        current_reason = str(outcome["reason"])
        current_live_state = exit_live_state()
        if current_code == EXIT_INTERRUPTED:
            try:
                entry = _write_signal_interruption_checkpoint(
                    history,
                    agent,
                    current_live_state,
                )
            except BaseException as exc:
                with contextlib.suppress(BaseException):
                    record_checkpoint_failure(
                        "signal checkpoint writer failed",
                        errors=(f"{type(exc).__name__}: {str(exc)[:240]}",),
                    )
                raise
            if entry is not None:
                exit_checkpoint_state = _journal_status()
            elif agent is not None and _is_autonomous_workflow():
                record_checkpoint_failure("signal checkpoint writer returned no entry")
        elif _infrastructure_pause_checkpoint_required(
            current_code,
            reason=current_reason,
            autonomy_state=autonomy_state,
            agent=agent,
        ):
            entry = _write_infrastructure_pause_checkpoint(
                history,
                agent,
                current_live_state,
                autonomy_state,
            )
            if entry is not None:
                exit_checkpoint_state = _journal_status()

    def record_final_outcome() -> None:
        current_code = int(outcome["exit_code"])
        current_live_state = exit_live_state()
        _record_campaign_exit(
            current_code,
            autonomy_state,
            current_live_state,
            reason=str(outcome["reason"]),
        )

    def handle_authority_failure(fallback_code: int, detail: str) -> int:
        failure_reason = "terminal finalization failed during outcome commit: " + detail
        if fallback_code == EXIT_INTERRUPTED:
            return mark_signal_interruption()
        return downgrade(failure_reason, infrastructure=True)

    def persist_authority_failure() -> None:
        _persist_live_status(
            history,
            compaction_state,
            exit_checkpoint_state,
            exit_live_state(),
            phase="exited",
            release_exit_locks=False,
        )
        _record_agent_activity(
            agent,
            "runner-exit",
            _native_runner_exit_message(
                int(outcome["exit_code"]),
                str(outcome["reason"]),
            ),
            exit_code=int(outcome["exit_code"]),
            reason=str(outcome["reason"]),
            corrective=True,
            corrects_premature_terminal_outcome=True,
        )
        record_final_outcome()

    already_finalized = finalizer.finalized
    final_code = finalizer.finalize(
        exit_code,
        stop_owned_work=stop_owned_work,
        outcome_authority=outcome_authority,
        select_outcome=select_outcome_after_quiescence,
        failure_exit_code=EXIT_PAUSED,
        handle_finalization_failure=handle_authority_failure,
        persist_finalization_failure=persist_authority_failure,
        persist_checkpoint=persist_checkpoint,
        release_locks=lambda: _release_native_runner_locks(agent),
        persist_exited=lambda: _persist_live_status(
            history,
            compaction_state,
            exit_checkpoint_state,
            exit_live_state(),
            phase="exited",
            release_exit_locks=False,
        ),
        emit_runner_exit=lambda: _record_agent_activity(
            agent,
            "runner-exit",
            str(outcome["message"])
            or _native_runner_exit_message(
                int(outcome["exit_code"]),
                str(outcome["reason"]),
            ),
            exit_code=int(outcome["exit_code"]),
            reason=str(outcome["reason"]),
        ),
        record_outcome=record_final_outcome,
    )
    # Reports and cross-run priors are non-authoritative derivatives. Defer
    # them until every authority context and runtime reservation released
    # cleanly; a late release failure must leave no verified/disproved artifact.
    # A signal during this best-effort phase propagates to ``main``; its second
    # finalizer call returns the already committed math code without retrying
    # the derivative or rewriting terminal truth.
    if already_finalized:
        return final_code
    try:
        if final_code == EXIT_DISPROVED:
            _maybe_generate_final_report(
                "disproved",
                autonomy_state,
                exit_live_state(),
                post_quiescence=True,
            )
        elif final_code == 0:
            _maybe_record_learnings(
                "verified",
                autonomy_state,
                post_quiescence=True,
            )
    except Exception as exc:
        logger.warning(
            "Failed to generate non-authoritative terminal derivative: %s",
            exc,
        )
    return final_code


def _write_signal_interruption_checkpoint(
    history: list[dict[str, Any]],
    agent: Any,
    live_state: Mapping[str, Any] | None,
) -> dict[str, Any] | None:
    """Force a deterministic resumable checkpoint after a process signal.

    Signal cleanup must not depend on another provider request.  The finalizer
    invokes this after owned subprocesses stop and before file locks or exited
    status are released, so the linked filesystem snapshot reflects the last
    quiescent source state.
    """
    if agent is None or not _is_autonomous_workflow():
        return None
    return _write_workflow_checkpoint(
        history,
        agent,
        label="signal-interrupt checkpoint",
        trigger="signal-interrupt",
        note=(
            "Resume this unresolved campaign from the exact linked filesystem "
            "snapshot and reconcile Lean truth before the next prover turn."
        ),
        force_filesystem_checkpoint=True,
        deterministic_summary=True,
        live_state=live_state,
    )


def _infrastructure_pause_checkpoint_required(
    exit_code: int,
    *,
    reason: str,
    autonomy_state: Mapping[str, Any],
    agent: Any,
) -> bool:
    """Return whether a valid campaign is exiting for an operational pause."""
    if exit_code != EXIT_PAUSED or not _is_autonomous_workflow():
        return False
    if not str(autonomy_state.get("campaign_id", "") or "").strip():
        return False
    normalized_reason = " ".join(str(reason or "").split()).casefold()
    return bool(
        str(autonomy_state.get("operational_pause", "") or "")
        or "provider/api" in normalized_reason
        or "infrastructure" in normalized_reason
    )


def _write_infrastructure_pause_checkpoint(
    history: list[dict[str, Any]],
    agent: Any,
    live_state: Mapping[str, Any] | None,
    autonomy_state: dict[str, Any],
) -> dict[str, Any] | None:
    """Force one provider-free checkpoint for an operationally paused source state."""
    pause_kind = str(autonomy_state.get("operational_pause", "") or "paused_infrastructure")
    checkpoint_key = "_native_operational_pause_checkpoint"
    previous = autonomy_state.get(checkpoint_key) or autonomy_state.get(
        "_native_infrastructure_pause_checkpoint"
    )
    if isinstance(previous, Mapping):
        return None
    source_pause = pause_kind == "paused_source_quarantine"
    entry = _write_workflow_checkpoint(
        history,
        agent,
        label=(
            "source-quarantine checkpoint" if source_pause else "infrastructure-pause checkpoint"
        ),
        trigger="source-quarantine" if source_pause else "infrastructure-pause",
        note=(
            "Resume this unresolved campaign from the exact linked filesystem "
            + (
                "snapshot after the quarantined helper source is reconciled."
                if source_pause
                else "snapshot after provider or runtime infrastructure recovers."
            )
        ),
        force_filesystem_checkpoint=True,
        deterministic_summary=True,
        live_state=live_state,
    )
    autonomy_state[checkpoint_key] = dict(entry)
    if not source_pause:
        # Preserve the legacy key for status consumers while new pauses share
        # one generalized checkpoint gate.
        autonomy_state["_native_infrastructure_pause_checkpoint"] = dict(entry)
    return entry


def _write_pre_exit_checkpoint_and_refresh(
    history: list[dict[str, Any]],
    agent: Any,
    checkpoint_state: dict[str, Any],
    *,
    live_state: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Write a resumable pre-exit checkpoint and return its current journal state.

    Terminal live-status persistence consumes ``checkpoint_state`` after this
    call. Refresh it here so every interactive and headless exit names the
    checkpoint that was just written instead of the previously loaded one.
    """
    if not _is_autonomous_workflow() or not history:
        return checkpoint_state
    _write_workflow_checkpoint(
        history,
        agent,
        label="pre-exit checkpoint",
        trigger="pre-exit",
        force_filesystem_checkpoint=True,
        live_state=live_state,
    )
    return _journal_status()


def _interactive_prompt_loop_allowed() -> bool:
    """Whether main() may enter the blocking ``input()`` prompt loop.

    Only when stdin is a real TTY. A headless run (no TTY — e.g. ``leanflow workflow prove``
    launched from a script, pipe, or background process) has no human to answer the prompt, so
    blocking on ``input()`` would hang the process forever. Such runs must exit cleanly instead.
    """
    return _stdin_is_interactive()


def _is_autonomous_workflow() -> bool:
    return _workflow_kind() in AUTONOMOUS_WORKFLOW_KINDS


def _parallel_agents() -> int:
    raw = _read_native_env("PARALLEL_AGENTS", "1")
    try:
        return max(1, int(raw))
    except ValueError:
        return 1


def _configured_agent_capacity() -> dict[str, int]:
    """Return foreground and shared research-background capacity.

    In research mode, ``planner`` is a lane-wave limit, not an additional
    reservation: planner delegates, auxiliary control turns, and dispatch
    workers share ``shared_background`` provider-request slots.
    """
    foreground = _parallel_agents()
    configured_planner = (
        planner_phase.planner_max_subagents() if planner_phase.planner_enabled() else 0
    )
    background = (
        research_mode.research_worker_count() if research_mode.research_mode_enabled() else 0
    )
    planner = (
        research_mode.planner_lane_parallelism(configured_planner)
        if configured_planner and research_mode.research_mode_enabled()
        else configured_planner
    )
    shared_background = max(1, background) if research_mode.research_mode_enabled() else 0
    return {
        "foreground": foreground,
        "planner": planner,
        "background": background,
        "shared_background": shared_background,
        # Zero-worker sequential routes run while the foreground is paused,
        # so their single gate slot is not additive concurrency.
        "total": (
            foreground + background
            if research_mode.research_mode_enabled()
            else foreground + planner
        ),
    }


def _single_queue_item_turn_enabled() -> bool:
    return _is_autonomous_workflow() and bool(_read_native_env("ACTIVE_FILE", "").strip())


def _base_active_skill() -> str:
    return _read_native_env("ACTIVE_SKILL", "").strip()


def _additional_skill_names() -> list[str]:
    raw = _read_native_env("ADDITIONAL_SKILLS", "")
    values: list[str] = []
    for part in re.split(rf"[{re.escape(os.pathsep)}\n]+", str(raw or "")):
        normalized = part.strip()
        if normalized and normalized not in values:
            values.append(normalized)
    return values


def _effective_skill_name(live_state: Mapping[str, Any] | None = None) -> str:
    configured = _base_active_skill()
    state = dict(live_state or {})
    route = dict(state.get("route_decision") or {})
    if route.get("skill_name"):
        return str(route.get("skill_name") or "")
    if not _single_queue_item_turn_enabled():
        return configured
    if configured and configured not in {"lean-proof-loop", "lean-theorem-queue-worker"}:
        return configured
    if state and not state.get("current_queue_item"):
        return "lean-proof-loop"
    return "lean-theorem-queue-worker"


def _set_runtime_active_skill(skill_name: str) -> None:
    normalized = str(skill_name or "").strip()
    if normalized:
        os.environ["LEANFLOW_NATIVE_ACTIVE_SKILL"] = normalized


def _is_step_boundary_interrupt(result: Mapping[str, Any] | None) -> bool:
    if not result:
        return False
    return (
        str(result.get("interrupt_message", "") or "").strip() == WORKFLOW_STEP_BOUNDARY_INTERRUPT
    )


def _interrupt_source_label(result: Mapping[str, Any] | None) -> str:
    """Best-effort label for WHY a managed conversation reported ``interrupted``.

    A non-user interrupt (e.g. an external ``kill -INT``, or — if it ever slipped
    past the terminal guard — a model-issued signal) is indistinguishable from a
    deliberate Ctrl+C at the OS level, but tagging the runner's own handler with
    ``RUNNER_KEYBOARD_INTERRUPT`` at least separates a real signal interrupt from a
    programmatic step-boundary stop, and records it for post-hoc analysis.
    """
    if not result:
        return "unknown"
    explicit = str(result.get("interrupt_source", "") or "").strip()
    if explicit:
        return explicit
    message = str(result.get("interrupt_message", "") or "").strip()
    if message == RUNNER_KEYBOARD_INTERRUPT:
        return "runner-keyboard-interrupt"
    if message == WORKFLOW_STEP_BOUNDARY_INTERRUPT:
        return "step-boundary"
    if message:
        return f"message:{message[:40]}"
    return "signal"


def _swarm_enabled() -> bool:
    return _parallel_agents() > 1 and _read_native_env("USER_APPROVED_SWARM", "0") == "1"


def _runner_lean_prompt_enabled() -> bool:
    raw = _read_text_env("LEANFLOW_RUNNER_LEAN_PROMPT", "0").strip().lower()
    return raw in {"1", "true", "yes", "on"}


def _research_event_preemption_enabled() -> bool:
    """Return whether completed research may interrupt an active prover turn."""
    raw = _read_text_env("LEANFLOW_RESEARCH_EVENT_PREEMPTION", "0").strip().lower()
    return raw in {"1", "true", "yes", "on"}


def _rcp_prefix_cache_enabled() -> bool:
    """Whether to optimize the per-cycle prompt for server-side prefix caching (default off).

    On the self-hosted vLLM/RCP route there is no client cache_control knob; the only lever is to
    keep the byte prefix stable and stop re-sending static content inside the volatile per-cycle
    user message. When enabled, continuation cycles stop re-appending the (static) supplemental
    skill contract — it stays available via the system-prompt skills catalog and `skill_view`.
    """
    raw = _read_text_env("LEANFLOW_RCP_PREFIX_CACHE", "0").strip().lower()
    return raw in {"1", "true", "yes", "on"}


def _runner_owner_id() -> str:
    return _read_native_env("RUNNER_OWNER", "")


def _autonomous_blocked_limit() -> int:
    raw = _read_native_env("AUTONOMOUS_BLOCKED_LIMIT", "3")
    try:
        return max(2, int(raw))
    except ValueError:
        return 3


def _autonomous_stalled_limit() -> int:
    raw = _read_native_env("AUTONOMOUS_STALLED_LIMIT", "4")
    try:
        return max(2, int(raw))
    except ValueError:
        return 4


def _autonomous_max_cycles() -> int:
    """Return the bounded cycle count for one fresh campaign epoch."""
    raw = _read_native_env("AUTONOMOUS_MAX_CYCLES", "120")
    try:
        base = max(8, int(raw))
    except ValueError:
        base = 120
    return research_mode.scaled_max_cycles(base)


def _active_skill() -> str:
    return _effective_skill_name()


def _journal_status() -> dict[str, Any]:
    entries = _load_workflow_index()
    current = _load_current_checkpoint()
    return {
        "count": len(entries),
        "current": current,
        "latest_label": str((current or {}).get("label", "") or ""),
        "latest_filesystem_checkpoint": str(
            (current or {}).get("linked_filesystem_checkpoint", "") or ""
        ),
    }


def _workflow_phase(
    live_state: Mapping[str, Any] | None = None,
    *,
    explicit: str = "",
    compaction_state: Mapping[str, Any] | None = None,
) -> str:
    """Return the shell-visible runner phase without treating proof difficulty as a pause."""
    if explicit:
        return explicit
    if compaction_state and compaction_state.get("compacted"):
        return "compacted"
    if _live_state_is_verified(live_state):
        return "verified"
    # In a proving campaign, diagnostics and blocker prose are work-queue
    # evidence.  The no-surrender loop turns them into a route change or epoch
    # rollover while the process remains active.  Reporting ``blocked`` here
    # makes the shell advertise an active prover as awaiting external input,
    # especially during a long orchestrator or background-research call.  Real
    # operational pauses and terminal decisions always pass an explicit phase.
    if _workflow_kind() == "prove":
        return "in-progress"
    blocker_summary = str((live_state or {}).get("blocker_summary", "") or "")
    diagnostics = str((live_state or {}).get("diagnostics", "") or "")
    if blocker_summary or _diagnostics_indicate_failure(diagnostics):
        return "blocked"
    return "in-progress"


def _persist_live_status(
    history: list[dict[str, Any]],
    compaction_state: Mapping[str, Any] | None = None,
    checkpoint_state: Mapping[str, Any] | None = None,
    live_state: Mapping[str, Any] | None = None,
    *,
    phase: str = "",
    release_exit_locks: bool = True,
) -> None:
    """Build and write the shell-visible live workflow status snapshot.

    Terminal snapshots clear process and lock ownership. Standalone callers
    release exit locks here by default; the shared finalizer disables that
    duplicate release after completing its dedicated lock step.
    """
    checkpoint_state = dict(_journal_status() if checkpoint_state is None else checkpoint_state)
    # An explicit empty mapping is authoritative during early signal cleanup:
    # no Lean state exists yet, and rebuilding it here can turn a bounded 130
    # exit into the same expensive startup work the signal interrupted.
    live_state = dict(
        _build_live_proof_state(history, checkpoint_state) if live_state is None else live_state
    )
    current_checkpoint = dict(checkpoint_state.get("current") or {})
    resolved_phase = _workflow_phase(live_state, explicit=phase, compaction_state=compaction_state)
    runner_exited = resolved_phase == "exited"
    if runner_exited and release_exit_locks:
        owner_id = _runner_owner_id()
        if owner_id:
            release_all_file_locks(owner_id=owner_id)
    updated_at = _utc_now_isoformat()
    agent_capacity = _configured_agent_capacity()
    payload = {
        "version": 1,
        "updated_at": updated_at,
        "runtime_heartbeat_at": updated_at,
        "phase": resolved_phase,
        "workflow_kind": _workflow_kind(),
        "workflow_command": _read_native_env("WORKFLOW_COMMAND", "[unset]"),
        "effective_prompt": _read_native_env(
            "EFFECTIVE_PROMPT",
            _read_native_env("USER_PROMPT", _read_native_env("EXPLICIT_GOAL", "")),
        ),
        "project_root": _project_root(),
        "provider": _read_native_env("PROVIDER"),
        "model": _read_native_env("MODEL"),
        "base_url": _read_native_env("BASE_URL"),
        # A terminal snapshot must never advertise this still-unwinding
        # process as live. Preserve process identity in runner-exit activity;
        # the live pointer itself is explicitly cleared before os._exit.
        "process_id": 0 if runner_exited else os.getpid(),
        "interrupt_source": str(live_state.get("interrupt_source", "") or ""),
        "active_skill": _effective_skill_name(live_state),
        # Backward-compatible foreground-swarm field. Research workers and
        # planner lanes were never represented by this legacy count.
        "parallel_agents": agent_capacity["foreground"],
        "agent_capacity": agent_capacity,
        "active_file": str(live_state.get("active_file", "") or ""),
        "active_file_label": str(live_state.get("active_file_label", "") or "[unknown]"),
        "target_symbol": str(live_state.get("target_symbol", "") or "[unknown]"),
        "declaration_scope": str(
            live_state.get("declaration_scope", "") or _declaration_queue_scope()
        ),
        "declaration_queue_total": int(live_state.get("declaration_queue_total", 0) or 0),
        "declaration_queue_preview": list(live_state.get("declaration_queue_preview", []) or []),
        "declaration_queue_summary": str(
            live_state.get("declaration_queue_summary", "") or "[none]"
        ),
        "current_queue_item": dict(live_state.get("current_queue_item", {}) or {}),
        "current_queue_item_prefix": str(live_state.get("current_queue_item_prefix", "") or ""),
        "current_queue_item_slice": str(live_state.get("current_queue_item_slice", "") or ""),
        "current_blocker": str(live_state.get("current_blocker", "") or ""),
        "queue_frontier_exhausted": bool(live_state.get("queue_frontier_exhausted")),
        "proof_state_authority": str(live_state.get("proof_state_authority", "") or ""),
        "used_source_only_snapshot": bool(live_state.get("used_source_only_snapshot")),
        "source_revision_sha256": str(live_state.get("source_revision_sha256", "") or ""),
        "diagnostics": str(live_state.get("diagnostics", "") or "unavailable"),
        "goals": str(live_state.get("goals", "") or "unavailable"),
        "build_status": str(live_state.get("build_status", "") or ""),
        "last_verification": dict(live_state.get("last_verification", {}) or {}),
        "proof_solved": bool(live_state.get("proof_solved", False)),
        "warning_cleanup_status": str(live_state.get("warning_cleanup_status", "") or ""),
        "warning_cleanup_attempted": bool(live_state.get("warning_cleanup_attempted", False)),
        "warning_cleanup_verified": bool(live_state.get("warning_cleanup_verified", False)),
        "warning_cleanup_skipped": bool(live_state.get("warning_cleanup_skipped", False)),
        "warning_cleanup_blocked": bool(live_state.get("warning_cleanup_blocked", False)),
        "warning_cleanup_warning_count": int(
            live_state.get("warning_cleanup_warning_count", 0) or 0
        ),
        "warning_cleanup_warning_summary": str(
            live_state.get("warning_cleanup_warning_summary", "") or ""
        ),
        "warning_cleanup_diagnostics": str(live_state.get("warning_cleanup_diagnostics", "") or ""),
        "warning_cleanup": dict(live_state.get("warning_cleanup", {}) or {}),
        "proof_state_message": str(live_state.get("message", "") or ""),
        "sorry_count": live_state.get("sorry_count"),
        "project_sorry_count": live_state.get("project_sorry_count"),
        "project_prove_manager": bool(live_state.get("project_prove_manager", False)),
        "project_prove_file_queue": list(live_state.get("project_prove_file_queue", []) or []),
        "project_prove_completed_files": list(
            live_state.get("project_prove_completed_files", []) or []
        ),
        "project_prove_plan_source": str(live_state.get("project_prove_plan_source", "") or ""),
        "project_prove_plan_reason": str(live_state.get("project_prove_plan_reason", "") or ""),
        "document_formalization_handoff": dict(
            live_state.get("document_formalization_handoff", {}) or {}
        ),
        "document_formalization_proof_sorry_count": int(
            live_state.get("document_formalization_proof_sorry_count", 0) or 0
        ),
        "document_formalization_construction_sorry_count": int(
            live_state.get("document_formalization_construction_sorry_count", 0) or 0
        ),
        "formalization_document": _read_text_env("LEANFLOW_FORMALIZATION_DOCUMENT_RELATIVE", ""),
        "formalization_document_kind": _read_text_env("LEANFLOW_FORMALIZATION_DOCUMENT_KIND", ""),
        "formalization_request_kind": _read_text_env("LEANFLOW_FORMALIZATION_REQUEST_KIND", ""),
        "formalization_request": _read_text_env("LEANFLOW_FORMALIZATION_REQUEST_RELATIVE", ""),
        "formalization_selected_source_document": _read_text_env(
            "LEANFLOW_FORMALIZATION_SELECTED_SOURCE", ""
        ),
        "formalization_context": _read_text_env("LEANFLOW_FORMALIZATION_CONTEXT", ""),
        "formalization_blueprint": _read_text_env("LEANFLOW_FORMALIZATION_BLUEPRINT", ""),
        "formalization_extracted_blueprint_path": _read_text_env(
            "LEANFLOW_FORMALIZATION_BLUEPRINT", ""
        ),
        "formalization_target_file": _read_text_env("LEANFLOW_FORMALIZATION_TARGET_FILE", ""),
        "capability_report": dict(live_state.get("capability_report", {}) or {}),
        "route_decision": dict(live_state.get("route_decision", {}) or {}),
        "checkpoint_count": int(checkpoint_state.get("count", 0) or 0),
        "latest_checkpoint_label": str(current_checkpoint.get("label", "") or "[none]"),
        "latest_filesystem_checkpoint": str(
            current_checkpoint.get("linked_filesystem_checkpoint", "") or "[none]"
        ),
        "last_compaction_reason": str((compaction_state or {}).get("reason", "[none]") or "[none]"),
        "snapshot_present": bool((compaction_state or {}).get("snapshot_text")),
        "held_locks": 0 if runner_exited else _held_lock_count(_runner_owner_id()),
    }
    if runner_exited and "exit_code" in live_state:
        payload.update(
            native_exit_status_fields(
                int(live_state["exit_code"]),
                str(live_state.get("reason", "") or ""),
            )
        )
    save_workflow_live_status(payload)


def _persist_startup_live_status(
    phase: str,
    live_state: Mapping[str, Any] | None = None,
) -> None:
    """Publish current process ownership and any restored queue identity."""
    restored = dict(live_state or {})
    metadata = {
        "workflow_kind": _workflow_kind(),
        "workflow_command": _read_native_env("WORKFLOW_COMMAND", "[unset]"),
        "effective_prompt": _read_native_env(
            "EFFECTIVE_PROMPT",
            _read_native_env("USER_PROMPT", _read_native_env("EXPLICIT_GOAL", "")),
        ),
        "project_root": _project_root(),
        "provider": _read_native_env("PROVIDER"),
        "model": _read_native_env("MODEL"),
        "base_url": _read_native_env("BASE_URL"),
        "active_skill": _base_active_skill(),
        "run_id": _read_text_env("LEANFLOW_WORKFLOW_RUN_ID", ""),
    }
    for key in (
        "active_file",
        "active_file_label",
        "target_symbol",
        "declaration_scope",
        "declaration_queue_total",
        "declaration_queue_preview",
        "declaration_queue_summary",
        "current_queue_item",
        "current_queue_item_slice",
        "route_decision",
        "sorry_count",
        "proof_state_authority",
        "used_source_only_snapshot",
        "source_revision_sha256",
        "verification_ok",
        "proof_solved",
        "last_verification",
        "build_status",
    ):
        if key in restored:
            metadata[key] = restored[key]
    mark_workflow_live_status_startup(
        phase=phase,
        metadata=metadata,
    )


def _compact_closed_activity_on_startup() -> None:
    """Run best-effort historical retention after claiming live ownership."""
    try:
        result = compact_closed_workflow_activity()
    except Exception as exc:
        logger.warning("Failed to compact closed workflow activity: %s", exc)
        return
    if result.archived_runs or result.archived_agent_streams:
        logger.info(
            "Archived %d workflow run(s) and %d mirrored agent stream(s); "
            "reclaimed %d hot bytes",
            len(result.archived_runs),
            len(result.archived_agent_streams),
            result.reclaimed_bytes,
        )


def _record_activity(event_type: str, message: str, **details: Any) -> None:
    active_skill = str(details.pop("active_skill", "") or _active_skill())
    append_workflow_activity(
        event_type,
        message,
        workflow_kind=_workflow_kind(),
        workflow_command=_read_native_env("WORKFLOW_COMMAND", "[unset]"),
        effective_prompt=_read_native_env(
            "EFFECTIVE_PROMPT",
            _read_native_env("USER_PROMPT", _read_native_env("EXPLICIT_GOAL", "")),
        ),
        active_skill=active_skill,
        **details,
    )


def _agent_activity_details(agent: Any) -> dict[str, Any]:
    return {
        "agent_session_id": str(getattr(agent, "session_id", "") or ""),
        "parent_agent_session_id": str(getattr(agent, "_parent_session_id", "") or ""),
        "delegate_depth": int(getattr(agent, "_delegate_depth", 0) or 0),
        "project_root": _project_root(),
        "model": _read_native_env("MODEL"),
        "provider": _read_native_env("PROVIDER"),
        "base_url": _read_native_env("BASE_URL"),
        "api_mode": _read_native_env("API_MODE"),
        "process_id": os.getpid(),
    }


def _record_agent_activity(agent: Any, event_type: str, message: str, **details: Any) -> None:
    payload = _agent_activity_details(agent)
    payload.update(details)
    _record_activity(event_type, message, **payload)


def _record_queue_assignment(
    live_state: Mapping[str, Any],
    *,
    cycle: int | None = None,
    phase: str = "",
) -> None:
    if _document_formalization_handoff_blocked_state(live_state):
        return
    item = dict(live_state.get("current_queue_item") or {})
    if not item:
        return
    label = str(item.get("label", "") or live_state.get("target_symbol", "") or "[unknown]")
    payload: dict[str, Any] = {
        "queue_item": item,
        "target_symbol": label,
        "active_file": str(
            live_state.get("active_file_label", "") or live_state.get("active_file", "") or ""
        ),
        "reasons": list(item.get("reasons", []) or []),
        "blocker_signature": str(item.get("blocker_signature", "") or ""),
        "search_hints": list(item.get("search_hints", []) or []),
        "verification_gate": str(item.get("verification_gate", "") or ""),
        "recommended_worker": str(
            item.get("recommended_worker", "")
            or dict(live_state.get("route_decision", {}) or {}).get("recommended_worker", "")
            or ""
        ),
    }
    if cycle is not None:
        payload["cycle"] = cycle
    if phase:
        payload["phase"] = phase
    payload["active_skill"] = _effective_skill_name(live_state)
    _record_activity("queue-item-assigned", f"Queue assigned theorem {label}", **payload)


_CURRENT_AGENT_ACTIVITY_DETAILS: dict[str, Any] = {}


def _agent_config() -> Mapping[str, Any]:
    try:
        config = load_config()
    except Exception:
        return {}
    agent_cfg = config.get("agent", {})
    return agent_cfg if isinstance(agent_cfg, dict) else {}


def _parse_managed_reasoning_config(effort: str) -> dict[str, Any] | None:
    normalized = str(effort or "").strip().lower()
    if not normalized:
        return None
    if normalized == "auto":
        return {"mode": "auto"}
    if normalized == "none":
        return {"enabled": False}
    if normalized in {"low", "minimal", "medium", "high", "xhigh"}:
        return {"enabled": True, "effort": normalized}
    return None


def _active_file_candidates(active_file: str) -> set[str]:
    normalized = str(active_file or "").strip()
    if not normalized:
        return set()
    candidates = {normalized}
    try:
        path = Path(normalized)
        if path.is_absolute():
            candidates.add(str(path.resolve()))
            with contextlib.suppress(Exception):
                candidates.add(str(path.resolve().relative_to(Path(_project_root()).resolve())))
    except Exception:
        pass
    return {value for value in candidates if value}


def _same_active_file(left: str, right: str) -> bool:
    left_value = str(left or "").strip()
    right_value = str(right or "").strip()
    if not left_value or not right_value:
        return False
    left_candidates = _active_file_candidates(left_value)
    right_candidates = _active_file_candidates(right_value)
    if not left_candidates.isdisjoint(right_candidates):
        return True

    try:
        left_parts = Path(left_value).parts
        right_parts = Path(right_value).parts
    except Exception:
        return False
    if left_parts and right_parts:
        if len(left_parts) >= len(right_parts) and left_parts[-len(right_parts) :] == right_parts:
            return True
        if len(right_parts) >= len(left_parts) and right_parts[-len(left_parts) :] == left_parts:
            return True
    return False


def _queue_item_mappings_from_live_state(
    live_state: Mapping[str, Any] | None,
) -> list[dict[str, Any]]:
    current = dict(live_state or {})
    raw_queue = current.get("declaration_queue")
    if not isinstance(raw_queue, list):
        raw_queue = current.get("declaration_queue_preview")
    return [dict(item) for item in list(raw_queue or []) if isinstance(item, Mapping)]


def _queue_manager_from_state(
    autonomy_state: Mapping[str, Any] | None,
    live_state: Mapping[str, Any] | None = None,
) -> TheoremQueueManager:
    # Live-authority bridge (Phase 0): one cached instance per autonomy_state
    # dict instead of a fresh reconstruction per helper call. The legacy dict
    # stays the compat serialization via _flush_queue_manager.
    return live_queue_manager(autonomy_state, live_state)


def _flush_queue_manager(
    autonomy_state: Mapping[str, Any] | None, mgr: TheoremQueueManager
) -> None:
    flush_live_queue_manager(autonomy_state, mgr)
    with contextlib.suppress(Exception):
        plan_state.save_queue_manager_state(mgr.to_checkpoint_state())


def _reopen_blocked_theorem_outcomes(
    autonomy_state: dict[str, Any], *, trigger: str
) -> tuple[TheoremKey, ...]:
    """Reopen temporary theorem blockers after a real strategy refresh."""
    mgr = _queue_manager_from_state(autonomy_state)
    reopened = mgr.reopen_blocked_outcomes(trigger=trigger)
    if not reopened:
        return ()
    _flush_queue_manager(autonomy_state, mgr)
    targets = [outcome.key.target_symbol for outcome in reopened]
    _record_activity(
        "queue-blocked-outcomes-reopened",
        f"Reopened {len(reopened)} temporarily blocked theorem(s) after {trigger}",
        trigger=trigger,
        target_symbols=targets,
    )
    return tuple(outcome.key for outcome in reopened)


def _migrate_negation_promotions_on_startup() -> dict[str, int]:
    """Repair legacy promotion identity before resume consumers read summary metrics."""
    result = negation_promotion.migrate_promotion_summary(cwd=_project_root())
    if result.get("records_canonicalized", 0) or result.get("duplicates_removed", 0):
        _record_activity(
            "negation-promotion-summary-migrated",
            "Canonicalized authoritative negation promotion history",
            **result,
        )
    return result


def _campaign_root_pause_reason(autonomy_state: Mapping[str, Any]) -> str:
    """Return the stable reason for an incomplete requested-root handshake."""
    return str(
        autonomy_state.get("infrastructure_pause_reason", "")
        or autonomy_state.get("source_quarantine_reason", "")
        or "immutable campaign-root registration is incomplete"
    )


def _pause_for_campaign_root_gate(
    autonomy_state: dict[str, Any],
    reason: str,
    *,
    event: str,
) -> None:
    """Persist a resumable operational pause before any provider can run."""
    detail = str(reason or "immutable campaign-root registration is incomplete")
    autonomy_state.update(
        {
            "operational_pause": "paused_infrastructure",
            "infrastructure_pause_reason": detail,
            "campaign_root_provider_blocked": True,
        }
    )
    campaign_epoch.record_status(autonomy_state, "paused", reason=detail)
    _record_activity(
        event,
        "Paused campaign before provider work because requested-root authority is incomplete",
        reason=detail,
    )


def _initialize_campaign_root_authority(autonomy_state: dict[str, Any]) -> bool:
    """Seal a fresh deterministic file/project scope before startup providers."""
    provider_allowed, _gate_reason = negation_promotion.campaign_root_provider_gate()
    if provider_allowed:
        return True
    project_root = _project_root()
    explicit_file = _read_native_env("ACTIVE_FILE", "").strip()
    project_files: Sequence[str | Path] = ()
    if not explicit_file:
        raw_file_scope = _read_text_env("LEANFLOW_PROVE_FILE_SCOPE", "").strip()
        scanned_project_files = _project_lean_files(project_root)
        if raw_file_scope:
            scanned_identities = {path.resolve() for path in scanned_project_files}
            project_files = [
                path
                for path in _prove_file_scope_ordered_paths(project_root)
                if path.resolve() in scanned_identities
            ]
        else:
            project_files = scanned_project_files
    source_files = campaign_roots.source_files_for_scope(
        project_root=project_root,
        explicit_file=explicit_file,
        project_files=project_files,
    )
    try:
        setup = campaign_roots.initialize_campaign_roots(
            campaign_id=str(autonomy_state.get("campaign_id", "") or ""),
            project_root=project_root,
            source_files=source_files,
        )
    except Exception as exc:
        _pause_for_campaign_root_gate(
            autonomy_state,
            f"campaign-root initialization failed: {type(exc).__name__}: {exc}",
            event="campaign-root-registration-failed",
        )
        return False
    if not setup.ok:
        _pause_for_campaign_root_gate(
            autonomy_state,
            setup.reason,
            event="campaign-root-registration-failed",
        )
        return False
    autonomy_state.pop("campaign_root_provider_blocked", None)
    _record_activity(
        "campaign-roots-registered",
        "Sealed immutable requested roots before native provider startup",
        campaign_id=str(autonomy_state.get("campaign_id", "") or ""),
        root_count=len(setup.roots),
        roots=list(setup.roots),
    )
    return True


def _reconcile_negation_promotions_on_startup(
    autonomy_state: dict[str, Any],
) -> negation_promotion.PromotionReconciliation:
    """Recover promotion transactions and rehydrate only current main disproof."""
    assignment = dict(autonomy_state.get("current_queue_assignment") or {})
    target_symbol = str(assignment.get("target_symbol", "") or "").strip()
    active_file = str(
        assignment.get("active_file", "") or _read_text_env("LEANFLOW_NATIVE_ACTIVE_FILE", "") or ""
    ).strip()
    result = negation_promotion.reconcile_promotions_on_startup(
        cwd=_project_root(),
        target_symbol=target_symbol,
        active_file=active_file,
    )
    _reconcile_false_decomposition_queue_state(autonomy_state)
    if result.terminal_disproof:
        promotion = dict(result.promotion or {})
        autonomy_state["terminal_outcome"] = "disproved"
        autonomy_state["negation_promotion"] = {
            "ok": True,
            "reason": "authoritative negation revalidated during startup",
            "node_id": str(promotion.get("node_id", "") or ""),
            "is_main_goal": True,
            "evidence": promotion,
            "already_promoted": True,
        }
        campaign_epoch.record_status(
            autonomy_state,
            "disproved",
            reason=(
                "revalidated promoted negation of "
                f"{str(promotion.get('theorem', target_symbol) or target_symbol)}"
            ),
        )
    else:
        autonomy_state.pop("terminal_outcome", None)
        autonomy_state.pop("negation_promotion", None)
        if str(autonomy_state.get("campaign_status", "") or "") == "disproved":
            campaign_epoch.record_status(
                autonomy_state,
                "running",
                reason="persisted disproof was absent or stale after startup revalidation",
            )
    if (
        result.committed
        or result.quarantined
        or result.promotion_pending
        or result.decompositions_cleaned
        or result.cleanup_pending
        or result.cleanup_quarantined
        or result.terminal_disproof
    ):
        _record_activity(
            "negation-promotion-startup-reconciled",
            "Reconciled authoritative negation evidence before provider startup",
            terminal_disproof=result.terminal_disproof,
            committed=result.committed,
            quarantined=result.quarantined,
            promotion_pending=result.promotion_pending,
            promotion_reasons=list(result.promotion_reasons),
            decompositions_cleaned=result.decompositions_cleaned,
            cleanup_pending=result.cleanup_pending,
            cleanup_quarantined=result.cleanup_quarantined,
            cleanup_reasons=list(result.cleanup_reasons),
            target_symbol=target_symbol,
            active_file=active_file,
            promotion=dict(result.promotion or {}),
        )
    return result


def _reconcile_source_transaction_state(autonomy_state: dict[str, Any]) -> dict[str, Any]:
    """Recover helper insertions and pause on unresolved source ambiguity."""
    recovered = decomposition_provenance.recover_pending_decompositions(cwd=_project_root())
    quarantines = decomposition_provenance.reconcile_quarantined_decompositions(cwd=_project_root())
    active = int(quarantines.get("active", 0) or 0)
    reasons = [str(item) for item in (quarantines.get("reasons") or []) if str(item)]
    if active:
        # Source bytes are the highest-priority pause authority. Replace all
        # ownership fields together so stale false-cleanup metadata cannot
        # clear this newly observed quarantine later in startup.
        autonomy_state.update(
            {
                "operational_pause": "paused_source_quarantine",
                "source_quarantine_origin": SOURCE_QUARANTINE_ORIGIN_TRANSACTION,
                "source_quarantine_reason": (
                    reasons[0]
                    if reasons
                    else "a helper source transaction requires explicit reconciliation"
                ),
            }
        )
        campaign_epoch.record_status(
            autonomy_state,
            "paused",
            reason=str(autonomy_state["source_quarantine_reason"]),
        )
    elif autonomy_state.get("operational_pause") == "paused_source_quarantine" and str(
        autonomy_state.get("source_quarantine_origin", "") or ""
    ) in {"", SOURCE_QUARANTINE_ORIGIN_TRANSACTION}:
        # Legacy source pauses had no origin. Never clear a pause owned by the
        # false-cleanup reconciler merely because insertion transactions are
        # currently clean.
        autonomy_state.pop("operational_pause", None)
        autonomy_state.pop("source_quarantine_reason", None)
        autonomy_state.pop("source_quarantine_origin", None)
        campaign_epoch.record_status(
            autonomy_state,
            "running",
            reason="source quarantine reconciled against current declaration truth",
        )
    if (
        any(int(value or 0) for value in recovered.values())
        or active
        or int(quarantines.get("resolved", 0) or 0)
    ):
        _record_activity(
            "decomposition-source-transactions-reconciled",
            (
                "Paused for ambiguous helper source state"
                if active
                else "Reconciled helper source transactions"
            ),
            recovered=dict(recovered),
            active_quarantines=active,
            resolved_quarantines=int(quarantines.get("resolved", 0) or 0),
            reasons=reasons,
        )
    return {**dict(recovered), **dict(quarantines)}


def _pause_for_false_cleanup_reconciliation(
    reconciliation: Any,
    autonomy_state: dict[str, Any],
) -> bool:
    """Pause while a false-helper source/graph transaction remains ambiguous."""
    pending = int(getattr(reconciliation, "cleanup_pending", 0) or 0)
    quarantined = int(getattr(reconciliation, "cleanup_quarantined", 0) or 0)
    reasons = tuple(
        str(item) for item in (getattr(reconciliation, "cleanup_reasons", ()) or ()) if str(item)
    )
    if not pending and not quarantined:
        if autonomy_state.get("source_quarantine_origin") == SOURCE_QUARANTINE_ORIGIN_FALSE_CLEANUP:
            autonomy_state.pop("operational_pause", None)
            autonomy_state.pop("source_quarantine_reason", None)
            autonomy_state.pop("source_quarantine_origin", None)
            autonomy_state.pop("false_cleanup_pending", None)
            autonomy_state.pop("false_cleanup_quarantined", None)
            campaign_epoch.record_status(
                autonomy_state,
                "running",
                reason="false-helper cleanup ambiguity was explicitly reconciled",
            )
        return False

    detail = reasons[0] if reasons else "false-helper source/graph ownership is ambiguous"
    reason = (
        f"false-helper cleanup requires reconciliation "
        f"({pending} pending, {quarantined} quarantined): {detail}"
    )
    if (
        autonomy_state.get("operational_pause") == "paused_source_quarantine"
        and autonomy_state.get("source_quarantine_origin") == SOURCE_QUARANTINE_ORIGIN_TRANSACTION
    ):
        # Preserve the stronger source-byte pause atomically. Cleanup counts
        # remain visible and will become the owning pause on the next startup
        # if source reconciliation succeeds while graph ambiguity remains.
        autonomy_state["false_cleanup_pending"] = pending
        autonomy_state["false_cleanup_quarantined"] = quarantined
        _record_activity(
            "false-decomposition-cleanup-paused",
            "Recorded false-helper ambiguity behind the active source transaction pause",
            pending=pending,
            quarantined=quarantined,
            reasons=list(reasons),
            deferred_by_origin=SOURCE_QUARANTINE_ORIGIN_TRANSACTION,
        )
        return True
    autonomy_state.update(
        {
            "operational_pause": "paused_source_quarantine",
            "source_quarantine_origin": SOURCE_QUARANTINE_ORIGIN_FALSE_CLEANUP,
            "source_quarantine_reason": reason,
            "false_cleanup_pending": pending,
            "false_cleanup_quarantined": quarantined,
        }
    )
    campaign_epoch.record_status(autonomy_state, "paused", reason=reason)
    _record_activity(
        "false-decomposition-cleanup-paused",
        "Paused campaign before another provider turn for false-helper reconciliation",
        pending=pending,
        quarantined=quarantined,
        reasons=list(reasons),
    )
    return True


def _pause_for_promotion_reconciliation(
    reconciliation: Any,
    autonomy_state: dict[str, Any],
) -> bool:
    """Pause while a negation promotion cannot restore authoritative graph truth."""
    pending = int(getattr(reconciliation, "promotion_pending", 0) or 0)
    reasons = tuple(
        str(item) for item in (getattr(reconciliation, "promotion_reasons", ()) or ()) if str(item)
    )
    if not pending:
        if (
            autonomy_state.get("source_quarantine_origin")
            == SOURCE_QUARANTINE_ORIGIN_NEGATION_PROMOTION
        ):
            autonomy_state.pop("operational_pause", None)
            autonomy_state.pop("source_quarantine_reason", None)
            autonomy_state.pop("source_quarantine_origin", None)
            autonomy_state.pop("negation_promotion_pending", None)
            campaign_epoch.record_status(
                autonomy_state,
                "running",
                reason="negation-promotion ambiguity was explicitly reconciled",
            )
        return False

    detail = reasons[0] if reasons else "negation-promotion graph authority is ambiguous"
    reason = f"negation promotion requires reconciliation ({pending} pending): {detail}"
    if (
        autonomy_state.get("operational_pause") == "paused_source_quarantine"
        and autonomy_state.get("source_quarantine_origin") == SOURCE_QUARANTINE_ORIGIN_TRANSACTION
    ):
        autonomy_state["negation_promotion_pending"] = pending
        _record_activity(
            "negation-promotion-reconciliation-paused",
            "Recorded negation-promotion ambiguity behind the active source transaction pause",
            pending=pending,
            reasons=list(reasons),
            deferred_by_origin=SOURCE_QUARANTINE_ORIGIN_TRANSACTION,
        )
        return True
    autonomy_state.update(
        {
            "operational_pause": "paused_source_quarantine",
            "source_quarantine_origin": SOURCE_QUARANTINE_ORIGIN_NEGATION_PROMOTION,
            "source_quarantine_reason": reason,
            "negation_promotion_pending": pending,
        }
    )
    campaign_epoch.record_status(autonomy_state, "paused", reason=reason)
    _record_activity(
        "negation-promotion-reconciliation-paused",
        "Paused campaign before another provider turn for negation-promotion reconciliation",
        pending=pending,
        reasons=list(reasons),
    )
    return True


def _pause_for_negation_reconciliation(
    reconciliation: Any,
    autonomy_state: dict[str, Any],
) -> bool:
    """Apply promotion and false-helper cleanup pause authority as one barrier."""
    if _pause_for_promotion_reconciliation(reconciliation, autonomy_state):
        pending = int(getattr(reconciliation, "cleanup_pending", 0) or 0)
        quarantined = int(getattr(reconciliation, "cleanup_quarantined", 0) or 0)
        if pending:
            autonomy_state["false_cleanup_pending"] = pending
        if quarantined:
            autonomy_state["false_cleanup_quarantined"] = quarantined
        return True
    return _pause_for_false_cleanup_reconciliation(reconciliation, autonomy_state)


def _refresh_false_cleanup_pause(autonomy_state: dict[str, Any]) -> bool:
    """Refresh the route-time pause from durable false-helper cleanup state."""
    cleanup = false_decomposition_cleanup.cleanup_reconciliation_state()
    reconciliation = negation_promotion.PromotionReconciliation(
        cleanup_pending=cleanup.pending,
        cleanup_quarantined=cleanup.quarantined,
        cleanup_reasons=cleanup.reasons,
    )
    return _pause_for_false_cleanup_reconciliation(reconciliation, autonomy_state)


def _refresh_negation_reconciliation_pause(autonomy_state: dict[str, Any]) -> bool:
    """Refresh the combined durable promotion and false-helper pause barrier."""
    promotion_pending, promotion_reasons = negation_promotion._promotion_pending_state()
    cleanup = false_decomposition_cleanup.cleanup_reconciliation_state()
    reconciliation = negation_promotion.PromotionReconciliation(
        promotion_pending=promotion_pending,
        promotion_reasons=promotion_reasons,
        cleanup_pending=cleanup.pending,
        cleanup_quarantined=cleanup.quarantined,
        cleanup_reasons=cleanup.reasons,
    )
    return _pause_for_negation_reconciliation(reconciliation, autonomy_state)


def _negation_reconciliation_barrier(autonomy_state: dict[str, Any]) -> bool:
    """Stop before provider work when durable negation authority is ambiguous."""
    try:
        return _refresh_negation_reconciliation_pause(autonomy_state)
    except Exception as exc:
        _pause_for_route_runtime_exception(
            "durable negation reconciliation barrier",
            exc,
            autonomy_state,
        )
        return True


def _reconcile_promotion_runtime_exception(
    autonomy_state: dict[str, Any],
    *,
    component: str,
    original_exception: Exception,
) -> negation_promotion.PromotionReconciliation | None:
    """Recover a crashed promotion and stop before another provider turn."""
    try:
        reconciliation = _reconcile_negation_promotions_on_startup(autonomy_state)
        reconciliation_paused = _pause_for_negation_reconciliation(
            reconciliation,
            autonomy_state,
        )
    except Exception as reconciliation_exception:
        # Reconciliation may have populated a provisional in-memory disproof
        # before a later durable status/activity write failed.  Preserve the
        # ledger for the next clean replay, but never let that partial runtime
        # state become a mathematical terminal outcome in this process.
        autonomy_state.pop("terminal_outcome", None)
        autonomy_state.pop("negation_promotion", None)
        combined = RuntimeError(
            f"{type(original_exception).__name__}: {str(original_exception)[:160]}; "
            "promotion reconciliation failed: "
            f"{type(reconciliation_exception).__name__}: {str(reconciliation_exception)[:160]}"
        )
        _pause_for_route_runtime_exception(component, combined, autonomy_state)
        return None

    if reconciliation.terminal_disproof:
        promotion = dict(reconciliation.promotion or {})
        if autonomy_state.get("terminal_outcome") != "disproved":
            autonomy_state["terminal_outcome"] = "disproved"
            autonomy_state["negation_promotion"] = {
                "ok": True,
                "reason": "authoritative negation revalidated after interrupted promotion",
                "node_id": str(promotion.get("node_id", "") or ""),
                "is_main_goal": True,
                "evidence": promotion,
                "already_promoted": True,
            }
            campaign_epoch.record_status(
                autonomy_state,
                "disproved",
                reason=(
                    "revalidated promoted negation of "
                    f"{str(promotion.get('theorem', '') or 'the main goal')}"
                ),
            )
        return reconciliation
    if reconciliation_paused or autonomy_state.get("operational_pause"):
        return reconciliation
    _pause_for_route_runtime_exception(component, original_exception, autonomy_state)
    return reconciliation


def _pause_for_decomposer_outcome(
    outcome: decomposer.DecomposeOutcome,
    autonomy_state: dict[str, Any],
) -> bool:
    """Persist a resumable source pause for an ambiguous decomposer result."""
    if not outcome.requires_pause:
        return False
    autonomy_state.update(
        {
            "operational_pause": "paused_source_quarantine",
            "source_quarantine_origin": SOURCE_QUARANTINE_ORIGIN_TRANSACTION,
            "source_quarantine_reason": outcome.reason,
        }
    )
    campaign_epoch.record_status(
        autonomy_state,
        "paused",
        reason=outcome.reason or "ambiguous helper source transaction",
    )
    _record_activity(
        "decomposer-source-quarantined",
        "Paused campaign because helper source could not be restored or committed safely",
        reason=outcome.reason,
        file=outcome.file,
    )
    return True


def _pause_for_route_runtime_exception(
    component: str,
    exc: Exception,
    autonomy_state: dict[str, Any],
) -> str:
    """Persist an unexpected route crash as a resumable infrastructure pause."""
    reason = f"unexpected {component} runtime exception: " f"{type(exc).__name__}: {str(exc)[:240]}"
    autonomy_state["operational_pause"] = "paused_infrastructure"
    autonomy_state["infrastructure_pause_reason"] = reason
    # The pause itself is the safety authority. Observability sinks must not
    # turn a durable resumable pause into an uncaught runtime failure.
    with contextlib.suppress(Exception):
        campaign_epoch.record_status(
            autonomy_state,
            "paused_infrastructure",
            reason=reason,
        )
    with contextlib.suppress(Exception):
        _record_activity(
            "route-runtime-exception-paused",
            f"Paused before another provider turn after {component} crashed",
            component=component,
            exception_type=type(exc).__name__,
            reason=reason,
            resumable=True,
        )
    return "stop:infrastructure-pause"


def _cleanup_parent_requires_work(transaction: Mapping[str, Any]) -> bool | None:
    """Return current parent sorry truth for one committed cleanup record."""
    path = Path(str(transaction.get("file", "") or "")).expanduser()
    parent = str(transaction.get("parent", "") or "").strip()
    if not path.is_absolute():
        path = Path(_project_root()) / path
    try:
        with decomposition_provenance.source_operation(path, canonical=True) as operation:
            source = decomposition_provenance.read_source_bytes(operation).decode("utf-8")
    except (OSError, RuntimeError, UnicodeDecodeError):
        return None
    declaration = decomposition_provenance.declaration_slice(source, parent)
    if declaration is None:
        return None
    return bool(re.search(r"\b(?:sorry|admit)\b", declaration.text))


def _reconcile_false_decomposition_queue_state(
    autonomy_state: dict[str, Any],
) -> tuple[TheoremKey, ...]:
    """Retire deleted false helpers/dependents and reopen restored parents.

    The source/graph transaction commits before this queue-side replay. The
    operation is deliberately idempotent so a crash before the manager
    checkpoint is saved simply retries it during the next startup.
    """
    try:
        records = false_decomposition_cleanup.committed_cleanup_records()
    except Exception as exc:
        logger.debug("false-decomposition queue reconciliation unavailable", exc_info=True)
        _pause_for_route_runtime_exception(
            "false-decomposition queue replay",
            exc,
            autonomy_state,
        )
        return ()
    if not records:
        return ()
    mgr = _queue_manager_from_state(autonomy_state)
    changed = False
    reconciled: list[TheoremKey] = []
    changed_records: list[dict[str, str]] = []
    for transaction in records:
        active_file = str(transaction.get("file", "") or "").strip()
        helper = str(transaction.get("helper", "") or "").strip()
        parent = str(transaction.get("parent", "") or "").strip()
        transaction_id = str(transaction.get("transaction_id", "") or "").strip()
        helper_key = _queue_key(helper, active_file)
        parent_key = _queue_key(parent, active_file)
        if not helper_key.is_valid() or not parent_key.is_valid():
            continue
        reconciled.append(helper_key)
        record_changed = mgr.retire_theorem_state(helper_key)
        invalidated_dependents: list[str] = []
        raw_dependents = transaction.get("invalidated_dependents")
        if isinstance(raw_dependents, list):
            for raw_dependent in raw_dependents:
                if not isinstance(raw_dependent, Mapping):
                    continue
                dependent = str(raw_dependent.get("name", "") or "").strip()
                dependent_key = _queue_key(dependent, active_file)
                if not dependent_key.is_valid():
                    continue
                invalidated_dependents.append(dependent)
                if mgr.retire_theorem_state(dependent_key):
                    record_changed = True
        parent_requires_work = _cleanup_parent_requires_work(transaction)
        parent_outcome = mgr.outcome_for(parent_key)
        cleanup_note = (
            f"false decomposition cleanup {transaction_id or '[legacy]'}: "
            f"retracted {helper} and reopened {parent}"
        )
        cleanup_already_applied = bool(
            parent_outcome is not None
            and str(parent_outcome.status or "").strip().lower() == "unresolved"
            and str(parent_outcome.note or "").strip() == cleanup_note
        )
        current = mgr.current
        if current is not None and current.key == parent_key and not cleanup_already_applied:
            # The first queue-side replay must invalidate a parent assignment
            # built before source restoration.  Its exact cleanup outcome is
            # the durable completion marker: a later valid reassignment must
            # survive startup replay of the same committed transaction.
            mgr.clear_assignment()
            record_changed = True

        if parent_requires_work is not False:
            if (
                parent_outcome is None
                or str(parent_outcome.status or "").strip().lower() != "unresolved"
                or str(parent_outcome.note or "").strip() != cleanup_note
            ):
                mgr.record_outcome_for(parent_key, status="unresolved", note=cleanup_note)
                record_changed = True
            if parent_requires_work is None:
                _pause_for_route_runtime_exception(
                    "false-decomposition queue source reconciliation",
                    OSError(
                        "committed cleanup parent truth is indeterminate for "
                        f"transaction {transaction_id or '[legacy]'} at {active_file}"
                    ),
                    autonomy_state,
                )
        elif parent_requires_work is False and parent_outcome is not None:
            parent_status = str(parent_outcome.status or "").strip().lower()
            parent_note = str(parent_outcome.note or "")
            if parent_status == "invalidated-by-dependency" or (
                parent_status == "unresolved"
                and parent_note.startswith("false decomposition cleanup ")
            ):
                mgr.discard_outcome_for(parent_key)
                record_changed = True

        if record_changed:
            changed = True
            changed_records.append(
                {
                    "transaction_id": transaction_id,
                    "helper": helper,
                    "parent": parent,
                    "active_file": active_file,
                    "invalidated_dependents": ",".join(dict.fromkeys(invalidated_dependents)),
                }
            )
    if changed:
        _flush_queue_manager(autonomy_state, mgr)
        _record_activity(
            "false-decomposition-queue-reconciled",
            f"Retired {len(changed_records)} false-helper queue state record(s)",
            cleanups=changed_records,
        )
    return tuple(dict.fromkeys(reconciled))


def _reconcile_verified_campaign_status_on_startup(
    autonomy_state: dict[str, Any], live_state: Mapping[str, Any]
) -> None:
    """Retire persisted verified status when the exact startup gate regresses."""
    if str(autonomy_state.get("campaign_status", "") or "") != "verified":
        return
    if _live_state_is_verified(live_state):
        return
    campaign_epoch.record_status(
        autonomy_state,
        "running",
        reason="persisted verification regressed during startup revalidation",
    )


def _cleanup_scratch_artifacts_on_startup(
    autonomy_state: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Remove legacy scratch-job files before resume consumers read shared state."""
    result = scratch_artifact_cleanup.cleanup_legacy_scratch_artifacts(cwd=_project_root())
    if autonomy_state is not None:
        if result.get("status") in {"deferred", "incomplete"}:
            autonomy_state["scratch_artifact_cleanup_deferred"] = True
        else:
            autonomy_state.pop("scratch_artifact_cleanup_deferred", None)
    if (
        result.get("artifacts_removed", 0)
        or result.get("checkpoints_removed", 0)
        or result.get("verified_patch_status_cleared", 0)
    ):
        _record_activity(
            "scratch-artifacts-cleaned",
            "Removed legacy project artifacts written by scratch-only research jobs",
            **result,
        )
    return result


def _retry_deferred_scratch_artifact_cleanup(autonomy_state: dict[str, Any]) -> None:
    """Retry startup cleanup after portfolio polling terminalizes an old worker."""
    if not autonomy_state.get("scratch_artifact_cleanup_deferred"):
        return
    now = time.monotonic()
    try:
        last_retry = float(autonomy_state.get("scratch_artifact_cleanup_last_retry", 0.0) or 0.0)
    except (TypeError, ValueError):
        last_retry = 0.0
    if now - last_retry < 60.0:
        return
    autonomy_state["scratch_artifact_cleanup_last_retry"] = now
    _cleanup_scratch_artifacts_on_startup(autonomy_state)


def _restore_queue_manager_state(autonomy_state: dict[str, Any]) -> bool:
    """Hydrate durable queue knowledge before startup routing and research."""
    payload = plan_state.load_queue_manager_state()
    if not payload:
        return False
    for key in TheoremQueueManager.OWNED_AUTONOMY_KEYS:
        autonomy_state.pop(key, None)
    autonomy_state.update(payload)
    autonomy_state[_QUEUE_MANAGER_STATE_RESTORED_KEY] = True
    invalidate_live_queue_manager(autonomy_state)
    _record_activity(
        "queue-manager-restored",
        "Restored deterministic queue-manager state for campaign resume",
        failed_attempts=len(list(payload.get("failed_attempts") or [])),
        has_assignment=bool(payload.get("current_queue_assignment")),
    )
    return True


def _restored_queue_assignment_live_state(
    autonomy_state: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Build truthful startup status fields from the durable queue assignment."""
    raw_assignment = dict(autonomy_state or {}).get("current_queue_assignment")
    assignment = dict(raw_assignment) if isinstance(raw_assignment, Mapping) else {}
    target_symbol = str(assignment.get("target_symbol", "") or "").strip()
    active_file = str(assignment.get("active_file", "") or "").strip()
    if not target_symbol or not active_file:
        # Explicit empty values are required here. ``live_state.update({})``
        # preserves the last durable assignment, which can advertise a helper
        # that source reconciliation has just deleted until the later full
        # proof-state refresh finishes.
        return {
            "target_symbol": "",
            "declaration_queue_total": 0,
            "declaration_queue": [],
            "declaration_queue_preview": [],
            "declaration_queue_summary": "",
            "current_queue_item": {},
            "current_queue_item_prefix": "",
            "current_queue_item_slice": "",
            "current_blocker": "",
            "route_decision": {},
            "verification_ok": False,
            "proof_solved": False,
            "last_verification": {},
            "build_status": "startup reconciliation pending",
        }
    slice_text = str(assignment.get("slice", "") or "")
    scope = str(assignment.get("declaration_scope", "") or _declaration_queue_scope())
    sorry_count = _count_sorries(active_file)
    reasons = ["restored unresolved assignment; full queue reconciliation pending"]
    if isinstance(sorry_count, int) and sorry_count > 0:
        reasons.insert(0, "contains sorry")
    current_item = {
        "label": target_symbol,
        "file": active_file,
        "reasons": reasons,
    }
    route_decision: dict[str, Any] = {}
    try:
        campaign = dict(plan_state.load_summary().get("campaign") or {})
        raw_route = campaign.get("last_route_decision")
        restored_route = dict(raw_route) if isinstance(raw_route, Mapping) else {}
        route_name = str(restored_route.get("route", "") or "").strip()
        route_target = str(restored_route.get("target_symbol", "") or "").strip()
        route_file = str(restored_route.get("active_file", "") or "").strip()
        if (
            route_name
            and (not route_target or route_target == target_symbol)
            and (not route_file or _same_active_file(route_file, active_file))
        ):
            route_decision = {
                "route": route_name,
                "route_action": route_name,
                "target_symbol": route_target or target_symbol,
                "active_file": route_file or active_file,
                "reason": "restored from the last durable campaign route decision",
                "restored": True,
            }
    except Exception:
        logger.debug("Failed to hydrate the restored campaign route", exc_info=True)
    queue_preview = [current_item]
    return {
        "active_file": active_file,
        "active_file_label": _relative_project_file_label(active_file, _project_root()),
        "target_symbol": target_symbol,
        "declaration_scope": scope,
        "declaration_queue_total": 1,
        "declaration_queue_preview": queue_preview,
        "declaration_queue_summary": _format_declaration_queue(queue_preview),
        "current_queue_item": current_item,
        "current_queue_item_slice": slice_text,
        "route_decision": route_decision,
        "sorry_count": sorry_count,
        # Source-derived startup fields are observability only. Kernel truth is
        # rebuilt by the later Lean preflight and is never restored here.
        "verification_ok": False,
        "proof_solved": False,
        "last_verification": {},
        "build_status": "startup reconciliation pending",
    }


def _queue_key(target_symbol: str, active_file: str) -> TheoremKey:
    return TheoremKey.make(target_symbol, active_file)


def _scoped_failed_attempt_entries(
    autonomy_state: Mapping[str, Any],
    *,
    target_symbol: str,
    active_file: str,
) -> list[dict[str, Any]]:
    key = _queue_key(target_symbol, active_file)
    if not key.is_valid():
        return []
    mgr = _queue_manager_from_state(autonomy_state)
    entries = list(mgr.attempt_entries_for(key))
    if entries:
        return entries
    # Backward-compatible read path for checkpoints that stored relative file
    # labels while callers now pass absolute active-file paths.
    attempts = [
        dict(item)
        for item in dict(autonomy_state or {}).get("failed_attempts", [])
        if isinstance(item, Mapping)
    ]
    return [
        attempt
        for attempt in attempts
        if str(attempt.get("target_symbol", "") or "").strip() == key.target_symbol
        and _same_active_file(str(attempt.get("active_file", "") or ""), active_file)
    ]


def _restored_assignment_verification_timeout_reason(
    autonomy_state: Mapping[str, Any] | None,
    *,
    target_symbol: str,
    active_file: str,
    gate_scope: str = "",
) -> str:
    """Return a same-source timeout that should backpressure resume checks.

    The newest attempt identifies the current declaration revision. A timeout
    from any retained attempt with that exact declaration hash proves that an
    eager replay has already exceeded its verifier budget; startup should hand
    the theorem to the foreground instead of running the same gate again.
    """
    attempts = _scoped_failed_attempt_entries(
        autonomy_state or {},
        target_symbol=target_symbol,
        active_file=active_file,
    )
    if not attempts:
        return ""
    current_hash = str(attempts[-1].get("declaration_hash", "") or "").strip()
    if not current_hash:
        return ""
    live_hash = _failed_attempt_declaration_hash(active_file, target_symbol, None)
    if not live_hash or live_hash != current_hash:
        # A source edit immediately invalidates timeout backpressure. The next
        # exact gate must inspect the new declaration instead of inheriting a
        # timeout from the preceding proof shape.
        return ""
    requested_scope = str(gate_scope or "").strip().lower()
    for attempt in reversed(attempts):
        if str(attempt.get("declaration_hash", "") or "").strip() != current_hash:
            continue
        detail = " ".join(
            str(attempt.get(key, "") or "") for key in ("gate_verdict", "reason")
        ).strip()
        lowered = detail.lower()
        observed_scope = (
            "file"
            if re.search(r"lake.{0,24}env.{0,24}lean", lowered) or "lake build" in lowered
            else (
                "target"
                if any(
                    marker in lowered
                    for marker in (
                        "leanprobe",
                        "lean_probe",
                        "incremental",
                        "check_target",
                    )
                )
                else ""
            )
        )
        if requested_scope and observed_scope and observed_scope != requested_scope:
            continue
        if any(marker in lowered for marker in _VERIFICATION_TIMEOUT_MARKERS):
            return _single_line(detail, 500)
    return ""


_VERIFICATION_TIMEOUT_MARKERS = (
    "timed out",
    "timeout=",
    "wall-clock deadline",
    "maximum number of heartbeats",
    "maxheartbeats",
)


def _same_revision_timeout_backpressure_check(
    autonomy_state: Mapping[str, Any] | None,
    *,
    target_symbol: str,
    active_file: str,
) -> tuple[dict[str, Any], str] | None:
    """Return a synthetic failure that prevents an unchanged timeout replay."""
    reason = _restored_assignment_verification_timeout_reason(
        autonomy_state,
        target_symbol=target_symbol,
        active_file=active_file,
    )
    if not reason:
        return None
    message = (
        "Exact verification already reached its bounded time or compilation limit for this "
        "unchanged declaration. Do not replay the same broad check. Refactor the proof into "
        "cohesive top-level helper theorems, verify those helpers independently with LeanProbe, "
        "then retry the parent only after its body is materially smaller."
    )
    check = {
        "success": False,
        "ok": False,
        "valid_without_sorry": True,
        "has_errors": False,
        "has_sorry": False,
        "timed_out": True,
        "retryable": True,
        "error_code": "same_revision_verification_timeout",
        "mode": "file_exact",
        "target": active_file,
        "command": _canonical_file_verification_command(active_file),
        "output": f"{reason}\n{message}",
        "source_sha256": _source_revision_sha256(active_file),
        "verification_reused": True,
        "verification_reuse_reason": "same assignment and unchanged declaration SHA-256",
    }
    return check, "verification_timeout_backpressure"


def _manager_check_timeout_reason(manager_check: Mapping[str, Any] | None) -> str:
    """Return bounded verifier-timeout evidence from one manager result."""
    checked = dict(manager_check or {})
    incremental = checked.get("incremental")
    payload = dict(incremental) if isinstance(incremental, Mapping) else {}
    detail = " ".join(
        str(value or "")
        for value in (
            checked.get("output"),
            checked.get("error"),
            checked.get("build_status"),
            checked.get("error_code"),
            payload.get("output"),
            payload.get("error"),
            payload.get("build_status"),
            payload.get("error_code"),
        )
    ).strip()
    lowered = detail.lower()
    timed_out = bool(checked.get("timed_out") or payload.get("timed_out"))
    if not timed_out and not any(marker in lowered for marker in _VERIFICATION_TIMEOUT_MARKERS):
        return ""
    return _single_line(detail or "bounded exact verification timed out", 500)


def _remember_same_revision_verification_timeout(
    autonomy_state: Mapping[str, Any] | None,
    *,
    target_symbol: str,
    active_file: str,
    manager_check: Mapping[str, Any] | None,
) -> bool:
    """Persist a timeout attempt even after the local feedback window is spent."""
    if not isinstance(autonomy_state, dict):
        return False
    reason = _manager_check_timeout_reason(manager_check)
    declaration_hash = _failed_attempt_declaration_hash(active_file, target_symbol, None)
    key = _queue_key(target_symbol, active_file)
    if not reason or not declaration_hash or not key.is_valid():
        return False
    mgr = _queue_manager_from_state(autonomy_state)
    recorded = mgr.record_attempt_for(
        key,
        cycle=int(autonomy_state.get("current_cycle", 0) or 0),
        proof_shape=_attempt_proof_shape(None),
        reason=reason,
        declaration_hash=declaration_hash,
        gate_verdict=reason,
        turn_key=_failed_attempt_turn_key(
            autonomy_state,
            int(autonomy_state.get("current_cycle", 0) or 0),
        ),
    )
    _flush_queue_manager(autonomy_state, mgr)
    if recorded is None:
        return False
    _record_activity(
        "verification-timeout-revision-recorded",
        f"Persisted exact timeout revision for {target_symbol}",
        target_symbol=target_symbol,
        active_file=active_file,
        declaration_hash=declaration_hash,
        reason=reason,
        campaign_progress=False,
    )
    return True


def _migrate_same_revision_verification_timeout_from_activity(
    autonomy_state: Mapping[str, Any] | None,
    *,
    target_symbol: str,
    active_file: str,
) -> str:
    """Import a legacy startup timeout when its exact source revision still matches."""
    if not isinstance(autonomy_state, dict) or not target_symbol or not active_file:
        return ""
    existing = _restored_assignment_verification_timeout_reason(
        autonomy_state,
        target_symbol=target_symbol,
        active_file=active_file,
    )
    if existing:
        return existing
    source_sha256 = _source_revision_sha256(active_file)
    if not source_sha256:
        return ""
    try:
        events = read_workflow_activity(
            limit=500,
            event_types={"startup-exact-verification-deferred"},
        )
    except Exception:
        logger.debug("legacy verification-timeout activity read failed", exc_info=True)
        return ""
    for event in reversed(events):
        details = event.get("details")
        if not isinstance(details, Mapping):
            continue
        event_target = str(details.get("target_symbol", "") or "").strip()
        event_file = str(details.get("active_file", "") or "").strip()
        event_source = str(details.get("source_revision_sha256", "") or "").strip()
        if (
            event_target != target_symbol
            or not _same_active_file(event_file, active_file)
            or event_source != source_sha256
        ):
            continue
        timeout_s = details.get("timeout_s")
        reason = (
            f"startup exact verification timed out after {timeout_s} seconds"
            if timeout_s
            else "startup exact verification reached its bounded time limit"
        )
        if not _remember_same_revision_verification_timeout(
            autonomy_state,
            target_symbol=target_symbol,
            active_file=active_file,
            manager_check={"timed_out": True, "output": reason},
        ):
            return ""
        _record_activity(
            "verification-timeout-activity-migrated",
            f"Imported legacy exact-timeout evidence for {target_symbol}",
            target_symbol=target_symbol,
            active_file=active_file,
            source_revision_sha256=source_sha256,
            reason=reason,
            campaign_progress=False,
        )
        return reason
    return ""


def _assignment_verification_timeout_count(
    autonomy_state: Mapping[str, Any] | None,
    *,
    target_symbol: str,
    active_file: str,
) -> int:
    """Count retained verifier timeouts for one exact queue assignment."""
    attempts = _scoped_failed_attempt_entries(
        autonomy_state or {},
        target_symbol=target_symbol,
        active_file=active_file,
    )
    count = 0
    for attempt in attempts:
        detail = " ".join(
            str(attempt.get(key, "") or "") for key in ("gate_verdict", "reason")
        ).lower()
        if any(marker in detail for marker in _VERIFICATION_TIMEOUT_MARKERS):
            count += 1
    return count


def _failed_attempt_count_for_theorem(
    autonomy_state: Mapping[str, Any],
    *,
    target_symbol: str,
    active_file: str,
) -> int:
    key = _queue_key(target_symbol, active_file)
    if not key.is_valid():
        return 0
    scoped = _scoped_failed_attempt_entries(
        autonomy_state,
        target_symbol=target_symbol,
        active_file=active_file,
    )
    if not scoped:
        return 0
    numbered = [
        int(attempt.get("attempt", 0) or 0)
        for attempt in scoped
        if int(attempt.get("attempt", 0) or 0) > 0
    ]
    if numbered:
        return max(numbered)
    return len(scoped)


def _resolve_managed_reasoning_config(
    base_reasoning_config: Mapping[str, Any] | None,
    live_state: Mapping[str, Any] | None,
    autonomy_state: Mapping[str, Any] | None = None,
) -> dict[str, Any] | None:
    base = dict(base_reasoning_config or {})
    if not base:
        return None
    if base.get("enabled") is False:
        return {"enabled": False}
    if base.get("mode") != "auto":
        return base

    current = dict(live_state or {})
    if _queue_needs_final_file_sweep(current):
        return {"enabled": True, "effort": "high"}

    target_symbol, active_file = _queue_assignment_identity(current)
    if target_symbol and active_file:
        return {"enabled": True, "effort": "high"}

    return {"enabled": True, "effort": "high"}


def _apply_managed_reasoning_policy(
    agent: AIAgent,
    live_state: Mapping[str, Any] | None,
    autonomy_state: Mapping[str, Any] | None = None,
) -> dict[str, Any] | None:
    base_reasoning = getattr(agent, "_managed_base_reasoning_config", None)
    effective = _resolve_managed_reasoning_config(base_reasoning, live_state, autonomy_state)
    agent.reasoning_config = effective
    return effective


def _record_managed_reasoning_policy(
    live_state: Mapping[str, Any] | None,
    autonomy_state: Mapping[str, Any] | None,
    effective: Mapping[str, Any] | None,
    *,
    phase: str,
    cycle: int | None = None,
) -> None:
    """Record applied reasoning effort policy and escalate to high-effort if failed-attempt threshold reached. Logs policy phase, target theorem, attempt count relative to threshold; escalates and prints confirmation if high-effort has not been previously attempted."""
    current = dict(live_state or {})
    target_symbol, active_file = _queue_assignment_identity(current)
    failed_attempt_count = 0
    if target_symbol and active_file:
        # Pass the real autonomy_state (not a copy) so the read-only lookup
        # hits the cached live queue manager instead of hydrating a throwaway.
        failed_attempt_count = _failed_attempt_count_for_theorem(
            autonomy_state or {},
            target_symbol=target_symbol,
            active_file=active_file,
        )
    effort = ""
    enabled = True
    if effective:
        enabled = bool(effective.get("enabled", True))
        effort = str(effective.get("effort", "") or "")
    message = "Managed reasoning policy applied"
    if effort:
        message += f": {effort}"
    elif not enabled:
        message += ": disabled"
    details = {
        "phase": phase,
        "target_symbol": target_symbol,
        "active_file": active_file,
        "failed_attempt_count": failed_attempt_count,
        "failed_attempt_reasoning_threshold": _failed_attempt_reasoning_threshold(),
        "effective_reasoning_effort": effort,
        "reasoning_enabled": enabled,
    }
    if cycle is not None:
        details["cycle"] = cycle
    _record_activity("managed-reasoning-policy", message, **details)
    threshold = _failed_attempt_reasoning_threshold()
    if (
        isinstance(autonomy_state, dict)
        and enabled
        and effort == "high"
        and failed_attempt_count >= threshold
    ):
        key = _queue_key(target_symbol, active_file)
        mgr = _queue_manager_from_state(autonomy_state)
        previous = mgr.remembered_reasoning_effort_for(key)
        if previous != "high":
            mgr.remember_reasoning_effort_for(key, "high")
            _flush_queue_manager(autonomy_state, mgr)
            _record_activity(
                "managed-reasoning-escalated",
                f"Reasoning effort escalated for {target_symbol}: {previous} -> high",
                target_symbol=target_symbol,
                active_file=active_file,
                failed_attempt_count=failed_attempt_count,
                threshold=threshold,
            )
            print(f"⬆️ Reasoning effort: {previous} → high (failed-attempt threshold reached).")


def _tool_result_counts_as_theorem_feedback(
    function_name: str,
    args: Mapping[str, Any] | None = None,
    *,
    active_file: str = "",
) -> bool:
    if function_name == "lean_incremental_check":
        action = str(dict(args or {}).get("action", "check_target") or "check_target")
        # ``feedback`` only inspects the declaration already on disk. Its
        # expected result for an unresolved assignment is ``ok=False`` with
        # the existing ``sorry``/goal diagnostics, so treating that response
        # as a queue gate fabricates a new proof attempt without any edit.
        # Exact-target candidate checks remain authoritative boundaries.
        return action.strip().lower().replace("-", "_") == "check_target"
    if function_name == "lean_verify":
        arguments = dict(args or {})
        mode = str(arguments.get("mode", "") or "").strip().lower()
        if mode == "project":
            return True
        target = str(
            arguments.get("target", "")
            or arguments.get("file_path", "")
            or arguments.get("path", "")
            or ""
        ).strip()
        if target and active_file:
            return _same_active_file(target, active_file)
        return True
    if function_name == "lean_extract_have" and _lean_extract_have_is_read_only(args):
        return False
    if function_name in {"apply_verified_patch", "lean_extract_have"}:
        return True
    if function_name != "terminal":
        return False
    arguments = dict(args or {})
    command_text = str(arguments.get("command", "") or arguments.get("cmd", "") or "")
    command = command_text.lower()
    if not command:
        return False
    if "lake build" in command:
        return True
    is_lean_check = any(token in command for token in ("lake env lean", " lean", " typecheck"))
    if not is_lean_check or not active_file:
        return is_lean_check
    lean_paths = [
        quoted or bare
        for quoted, bare in re.findall(
            r"(?:[\"']([^\"']+\.lean)[\"']|([^\s\"';&|]+\.lean))",
            command_text,
            flags=re.IGNORECASE,
        )
    ]
    if not lean_paths:
        return True
    return any(_same_active_file(path, active_file) for path in lean_paths)


def _incremental_result_matches_assignment(
    payload: Mapping[str, Any],
    *,
    target_symbol: str,
    active_file: str,
) -> bool:
    """Return whether an incremental result checks the exact queue assignment.

    Lean tool calls may run concurrently, and agents commonly check a newly
    introduced helper beside the assigned theorem.  A successful helper check
    must never be recorded as verification of the assigned declaration.
    Namespace prefixes may be omitted by callers, so accept only exact names,
    a genuine namespace-prefix relation, or a shared short name when one side
    is itself unqualified.
    """
    checked_target = str(payload.get("target", "") or "").strip().removeprefix("_root_.")
    assigned_target = str(target_symbol or "").strip().removeprefix("_root_.")
    if not assigned_target:
        return False

    checked_targets = [checked_target] if checked_target else []
    if not checked_targets and payload.get("replacement_matches_target") is True:
        # A timeout can occur after the replacement parser has proved the
        # candidate names the exact assignment but before Lean returns its
        # echoed ``target`` field. Preserve that exact-target provenance so
        # the rejection reaches theorem feedback and persistence coaching.
        checked_targets = [
            str(name).strip().removeprefix("_root_.")
            for name in payload.get("replacement_declarations", []) or []
            if str(name).strip()
        ]
    if not checked_targets:
        return False

    names_match = any(
        candidate == assigned_target
        or candidate.endswith(f".{assigned_target}")
        or assigned_target.endswith(f".{candidate}")
        or (
            ("." not in candidate or "." not in assigned_target)
            and candidate.rsplit(".", 1)[-1] == assigned_target.rsplit(".", 1)[-1]
        )
        for candidate in checked_targets
    )
    if not names_match:
        return False
    checked_file = str(payload.get("file", "") or "").strip()
    return not checked_file or not active_file or _same_active_file(checked_file, active_file)


def _promote_source_negation_candidate(
    agent: Any,
    *,
    target_symbol: str,
    active_file: str,
    proof_declaration: str,
) -> bool:
    """Recheck and promote one source declaration as the exact target negation."""
    proof_declaration = str(proof_declaration or "").strip()
    if not proof_declaration:
        return False
    autonomy_state = getattr(agent, "_managed_autonomy_state", None)
    try:
        promotion = negation_promotion.promote_source_negation(
            theorem_id=target_symbol,
            file_label=active_file,
            proof_declaration=proof_declaration,
            cwd=_project_root(),
        )
    except Exception as exc:
        logger.debug("source-negation promotion failed", exc_info=True)
        if not isinstance(autonomy_state, dict):
            raise
        reconciliation = _reconcile_promotion_runtime_exception(
            autonomy_state,
            component="source-negation promotion",
            original_exception=exc,
        )
        if reconciliation is None and not autonomy_state.get("operational_pause"):
            return False
        with contextlib.suppress(Exception):
            agent.set_tool_result_appendix(
                "\n".join(
                    [
                        "[LEANFLOW-NATIVE NEGATION RECONCILIATION]",
                        f"- assigned declaration: {target_symbol}",
                        "- promotion processing was interrupted and durable authority was reconciled",
                        "- result: stop this model turn; the manager will exit or resume from the reconciled state",
                    ]
                )
            )
            agent._managed_pending_theorem_feedback = None
            agent._managed_step_boundary_closed = True
        _request_step_boundary_interrupt(agent)
        return True
    promotion_payload = promotion.to_payload()
    reconciliation_paused = False
    if isinstance(autonomy_state, dict):
        reconciliation_paused = _negation_reconciliation_barrier(autonomy_state)
    if reconciliation_paused:
        with contextlib.suppress(Exception):
            agent.set_tool_result_appendix(
                "\n".join(
                    [
                        "[LEANFLOW-NATIVE NEGATION RECONCILIATION]",
                        f"- assigned declaration: {target_symbol}",
                        "- durable promotion or false-helper cleanup authority is ambiguous",
                        "- result: stop this model turn; the manager will resume from the reconciled state",
                    ]
                )
            )
            agent._managed_pending_theorem_feedback = None
            agent._managed_step_boundary_closed = True
        _request_step_boundary_interrupt(agent)
        return True
    if not promotion.ok:
        return False

    if isinstance(autonomy_state, dict):
        autonomy_state["negation_promotion"] = promotion_payload
        reconciled_helpers = (
            ()
            if promotion.is_main_goal
            else _reconcile_false_decomposition_queue_state(autonomy_state)
        )
        assigned_key = _queue_key(target_symbol, active_file)
        if promotion.is_main_goal or assigned_key not in reconciled_helpers:
            _record_theorem_outcome(
                autonomy_state,
                {
                    "target_symbol": target_symbol,
                    "active_file": active_file,
                    "status": "disproved",
                    "note": f"authoritative source negation proved by {proof_declaration}",
                },
            )
        autonomy_state.pop("orchestrator_scope_entered", None)
        if promotion.is_main_goal:
            autonomy_state["terminal_outcome"] = "disproved"
            campaign_epoch.record_status(
                autonomy_state,
                "disproved",
                reason=f"promoted negation of {target_symbol}",
            )
    if not promotion.already_promoted:
        _record_activity(
            "queue-source-negation-promoted",
            f"Authoritative negation of {target_symbol} proved by {proof_declaration}",
            target_symbol=target_symbol,
            active_file=active_file,
            proof_declaration=proof_declaration,
            is_main_goal=promotion.is_main_goal,
            promotion=promotion_payload,
        )
        print("")
        print(f"⛔ Assigned declaration {target_symbol} is authoritatively disproved.")
        print(f"   proof: {proof_declaration}")
        print(
            "   outcome: main scope disproved"
            if promotion.is_main_goal
            else "   outcome: invalidated this decomposition; selecting a new route"
        )
    with contextlib.suppress(Exception):
        agent.set_tool_result_appendix(
            "\n".join(
                [
                    "[LEANFLOW-NATIVE AUTHORITATIVE NEGATION]",
                    f"- assigned declaration: {target_symbol}",
                    f"- kernel-checked negation proof: {proof_declaration}",
                    "- result: the false helper and its dependent decomposition were invalidated",
                    "- next action: replan from the preserved verified findings; do not attempt this false declaration again",
                ]
            )
        )
        agent._managed_pending_theorem_feedback = None
        agent._managed_step_boundary_closed = True
    _request_step_boundary_interrupt(agent)
    return True


def _maybe_promote_checked_source_negation(
    agent: Any,
    payload: Mapping[str, Any],
    *,
    target_symbol: str,
    active_file: str,
) -> bool:
    """Promote an exact checked helper negation and end the invalid theorem turn."""
    if (
        not bool(payload.get("ok"))
        or str(payload.get("action", "") or "").strip().lower() != "check_target"
    ):
        return False
    proof_declaration = str(payload.get("target", "") or "").strip()
    checked_file = str(payload.get("file", "") or active_file).strip()
    if not proof_declaration or not _same_active_file(checked_file, active_file):
        return False
    return _promote_source_negation_candidate(
        agent,
        target_symbol=target_symbol,
        active_file=active_file,
        proof_declaration=proof_declaration,
    )


def _managed_edit_targets_assignment(
    args: Mapping[str, Any] | None,
    active_file: str,
    *,
    function_name: str = "",
) -> bool:
    """Return whether a file-editing tool touched the assigned Lean file."""
    arguments = dict(args or {})
    edit_paths = _tool_edit_paths(function_name, arguments) if function_name else []
    if edit_paths:
        active_path = _resolve_project_path(active_file)
        return bool(active_path and any(path == active_path for path in edit_paths))
    edited_path = str(arguments.get("path", "") or arguments.get("file_path", "") or "").strip()
    return not edited_path or _same_active_file(edited_path, active_file)


def _prepare_managed_turn_state(agent: Any, autonomy_state: dict[str, Any]) -> None:
    """Bind runner state and reserve one stable failed-attempt turn identity."""
    agent._managed_autonomy_state = autonomy_state
    diagnostic_loop_guard.reset(agent)
    agent._managed_pending_theorem_feedback = None
    agent._managed_step_boundary_recorded_attempt = False
    agent._managed_step_boundary_closed = False
    search_progress = autonomy_state.get("search_progress")
    if isinstance(search_progress, dict):
        search_progress = search_synthesis_admission.prepare_provider_turn(search_progress)
        autonomy_state["search_progress"] = search_progress
        # Search and source debt are assignment-durable, but the small
        # correction allowance belongs to one provider conversation. Without
        # this reset, a fresh route can be terminated by its first mistaken
        # inspection request before the model sees the deterministic fence.
        search_progress["synthesis_rejection_count"] = 0
        search_progress["construction_synthesis_rejection_count"] = 0
    autonomy_state.pop(_FINAL_REPORT_FAILURE_CHECK_KEY, None)
    with contextlib.suppress(Exception):
        delattr(agent, _EXACT_CHECK_SOURCE_SNAPSHOT_ATTR)
    if _workflow_kind() == "prove" and autonomy_state.get("campaign_id"):
        try:
            autonomy_state["_failed_attempt_provider_turn"] = campaign_epoch.reserve_provider_turn(
                autonomy_state
            )
        except campaign_epoch.CampaignRootProviderBlocked:
            # Requested-root sealing is correctness authority, not optional
            # failed-attempt accounting. Let each provider call site convert
            # this dedicated gate result into a truthful resumable exit.
            raise
        except Exception:
            # Failed-attempt accounting must not turn an otherwise available
            # prover call into an infrastructure failure. Epoch/cycle identity
            # remains a collision-safe fallback and the next turn retries the
            # durable reservation.
            logger.debug("provider-turn identity reservation failed", exc_info=True)
            autonomy_state.pop("_failed_attempt_provider_turn", None)
    _sync_construction_only_tool_surface(agent, autonomy_state)


def _prepare_managed_turn_or_pause(agent: Any, autonomy_state: dict[str, Any]) -> bool:
    """Reserve a provider turn or persist an atomic campaign-root gate pause."""
    try:
        _prepare_managed_turn_state(agent, autonomy_state)
        return True
    except campaign_epoch.CampaignRootProviderBlocked as exc:
        _pause_for_campaign_root_gate(
            autonomy_state,
            str(exc),
            event="campaign-root-provider-blocked",
        )
        return False


def _disable_generic_lean_statement_guard_for_native_runner() -> None:
    # Native managed workflows have a contextual queue guard below. The generic
    # file-tool guard is intentionally broader and blocks formalization drafting.
    os.environ["LEANFLOW_ALLOW_LEAN_STATEMENT_EDITS"] = "1"


def _agent_interrupted(agent: Any) -> bool:
    value = getattr(agent, "is_interrupted", False)
    if callable(value):
        try:
            return bool(value())
        except TypeError:
            return False
    return bool(value)


def _request_step_boundary_interrupt(agent: Any) -> None:
    with contextlib.suppress(Exception):
        agent._suppress_next_interrupt_log = True
    agent.interrupt(WORKFLOW_STEP_BOUNDARY_INTERRUPT)


def _print_queue_step_separator(target_symbol: str, *, accepted: bool = True) -> None:
    label = str(target_symbol or "[unknown]").strip()
    status = "verified" if accepted else "intermediate turn incomplete; queue continues"
    line = "=" * 72
    print("")
    print(line)
    print(f"Queue step boundary: {label} {status}")
    print(line)


def _manager_file_verification_preview(
    raw_output: str,
    diagnostics: Sequence[Mapping[str, Any]],
) -> str:
    """Return a bounded file-check preview that surfaces Lean errors first.

    File checks can emit enough earlier linter output to push the actual Lean
    errors past the ordinary activity-preview limit. Keep the payload bounded,
    but build its human/model-facing preview from the already-parsed diagnostics
    so a leading warning cannot hide a later type error or unsolved goal.
    """
    if not diagnostics:
        return _single_line(raw_output, 500)

    def priority(item: Mapping[str, Any]) -> int:
        severity = str(item.get("severity", "") or "").strip().lower()
        message = str(item.get("message", "") or "").strip().lower()
        if severity == "error":
            return 0
        if "sorry" in message:
            return 1
        if severity == "warning":
            return 2
        return 3

    parts: list[str] = []
    for item in sorted(diagnostics, key=priority):
        severity = str(item.get("severity", "") or "diagnostic").strip().lower()
        message = _single_line(str(item.get("message", "") or ""), 180)
        line = item.get("line")
        location = f" near line {line}" if isinstance(line, int) and line > 0 else ""
        parts.append(f"{severity}{location}: {message or '[no message]'}")
    return _single_line(" | ".join(parts), 500)


def _manager_verify_queue_file(active_file: str) -> dict[str, Any]:
    path = str(active_file or "").strip()
    if not path:
        return {}
    try:
        result = lean_verify(target=path, cwd=_project_root(), mode="file_exact")
    except Exception as exc:
        return {"ok": False, "error": str(exc)[:500]}
    raw_output = str(result.output or "")
    messages = diagnostic_items(raw_output)
    errors, warnings, sorry_count = _diagnostic_counts_from_messages(messages=messages)
    return {
        "ok": bool(result.ok),
        "mode": result.mode,
        "command": result.command,
        "target": result.target,
        "output": _manager_file_verification_preview(raw_output, messages),
        "messages": messages,
        "has_errors": errors > 0,
        "has_sorry": sorry_count > 0,
        "errors": errors,
        "warnings": warnings,
        "sorry": sorry_count,
    }


def _manager_incremental_check_queue_item(active_file: str, target_symbol: str) -> dict[str, Any]:
    path = str(active_file or "").strip()
    target = str(target_symbol or "").strip()
    if not path or not target:
        return {"ok": False, "error": "active file and target declaration are required"}
    try:
        result = lean_incremental_check(
            action="check_target",
            file_path=path,
            theorem_id=target,
            cwd=_project_root(),
            include_tactics=False,
            include_axiom_profile=True,
            timeout_s=_manager_incremental_check_timeout_s(),
        )
    except Exception as exc:
        return {
            "ok": False,
            "backend": "lean_interact",
            "error": str(exc)[:500],
            "incremental": {"success": False, "error": str(exc)[:500]},
        }
    output = str(result.get("output", "") or result.get("error", "") or "")
    # Forward the structured `messages` list alongside the flattened text so
    # downstream consumers (notably `_declaration_diagnostic_feedback_reason`)
    # can locate per-line warnings/errors. The flattened `output` field is
    # capped + single-lined and lacks the `<file>:<line>:<col>:` prefix that
    # `diagnostic_items()`'s text parser depends on, so without this the
    # cleanup-feedback helper silently returns "" for `lean_interact`-style
    # warnings and the per-theorem warning-cleanup opportunity never fires.
    structured_messages = list(result.get("messages") or [])
    preview = (
        _manager_file_verification_preview(output, structured_messages)
        if not bool(result.get("ok", False))
        else _single_line(output, 500)
    )
    return {
        "ok": bool(result.get("ok", False)),
        "mode": "incremental_target",
        "backend": str(result.get("backend", "lean_interact") or "lean_interact"),
        "command": str(
            result.get("command", "lean_interact check_target") or "lean_interact check_target"
        ),
        "target": str(result.get("target", target) or target),
        "output": preview,
        "messages": structured_messages,
        "incremental": result,
    }


def _scope_successful_file_check_to_declaration(
    active_file: str,
    target_symbol: str,
    manager_check: Mapping[str, Any],
) -> dict[str, Any]:
    """Scope a clean canonical file fallback to one sorry-free declaration.

    A successful whole-file elaboration proves that every declaration elaborated,
    even when another intentionally open declaration emitted a ``sorry`` warning.
    Preserve the file diagnostics for audit, but do not attribute that unrelated
    placeholder to the requested helper.
    """
    checked = dict(manager_check or {})
    if not bool(checked.get("ok")) or bool(checked.get("has_errors")):
        return checked
    entry = _find_declaration_entry(active_file, target_symbol)
    if not entry or bool(entry.get("has_sorry")):
        return checked
    start = int(entry.get("line", 0) or 0)
    end = int(entry.get("end_line", 0) or 0)
    original_output = str(checked.get("output", "") or "")
    file_messages = list(checked.get("messages") or diagnostic_items(original_output))
    file_errors, file_warnings, file_sorries = _diagnostic_counts_from_messages(
        output=original_output,
        messages=file_messages,
    )
    scoped_messages = [
        dict(message)
        for message in file_messages
        if isinstance(message, Mapping)
        and isinstance(message.get("line"), int)
        and start <= int(message["line"]) <= end
        and "declaration uses 'sorry'" not in str(message.get("message", "") or "").lower()
    ]
    scoped_errors, scoped_warnings, _scoped_sorries = _diagnostic_counts_from_messages(
        messages=scoped_messages,
    )
    checked.update(
        {
            "mode": "target_from_file",
            "verification_scope": "target",
            "target": target_symbol,
            "messages": scoped_messages,
            "has_errors": scoped_errors > 0,
            "has_sorry": False,
            "errors": scoped_errors,
            "warnings": scoped_warnings,
            "sorry": 0,
            "output": _manager_file_verification_preview(
                (
                    original_output
                    or (
                        "canonical file verification succeeded; requested declaration "
                        f"`{target_symbol}` is sorry-free"
                    )
                ),
                scoped_messages,
            ),
            "file_messages": file_messages,
            "file_error_count": max(
                file_errors,
                int(checked.get("errors", 0) or 0),
            ),
            "file_warning_count": max(
                file_warnings,
                int(checked.get("warnings", 0) or 0),
            ),
            "file_sorry_count": max(
                file_sorries,
                int(checked.get("sorry", 0) or 0),
            ),
        }
    )
    return checked


def _manager_prepare_incremental_queue_item(active_file: str, target_symbol: str) -> dict[str, Any]:
    path = str(active_file or "").strip()
    target = str(target_symbol or "").strip()
    if not path or not target:
        return {
            "success": False,
            "ok": False,
            "error": "active file and target declaration are required",
        }
    if low_memory_mode_enabled():
        return {
            "success": False,
            "ok": False,
            "backend": "lean_interact",
            "error": "incremental Lean cache disabled by low-memory mode",
            "error_code": "low_memory_mode",
        }
    try:
        result = lean_incremental_check(
            action="prepare_file",
            file_path=path,
            theorem_id=target,
            cwd=_project_root(),
            include_tactics=False,
            timeout_s=_manager_incremental_prepare_timeout_s(),
        )
    except Exception as exc:
        return {
            "success": False,
            "ok": False,
            "backend": "lean_interact",
            "error": str(exc)[:500],
        }
    output = str(result.get("output", "") or result.get("error", "") or "")
    return {
        "success": bool(result.get("success", False)),
        "ok": bool(result.get("ok", False)),
        "backend": str(result.get("backend", "lean_interact") or "lean_interact"),
        "action": "prepare_file",
        "target": str(result.get("target", target) or target),
        "elapsed_s": result.get("elapsed_s", 0),
        "output": _single_line(output, 500),
        "cache": dict(result.get("cache") or {}),
        "error": str(result.get("error", "") or ""),
    }


def _manager_check_queue_item(active_file: str, target_symbol: str) -> tuple[dict[str, Any], str]:
    """Verify a queue item with LeanProbe, falling back only when it is unavailable."""
    started = time.monotonic()
    phase_seconds: dict[str, float] = {}

    def finish(
        check: dict[str, Any],
        tool: str,
        *,
        route: str,
    ) -> tuple[dict[str, Any], str]:
        """Emit manager-gate wall timing without changing the check payload."""
        incremental = dict(check.get("incremental") or {})
        _record_activity(
            "manager-queue-item-check-timing",
            f"Measured manager queue-item check for {target_symbol}",
            target_symbol=target_symbol,
            active_file=active_file,
            manager_tool=tool,
            route=route,
            elapsed_s=round(max(0.0, time.monotonic() - started), 3),
            phase_seconds={key: round(value, 3) for key, value in phase_seconds.items()},
            incremental_reported_elapsed_s=incremental.get("elapsed_s", 0),
            incremental_timing=dict(incremental.get("leanflow_timing") or {}),
            incremental_resource_admission=dict(incremental.get("resource_admission") or {}),
        )
        return check, tool

    if low_memory_mode_enabled():
        phase_started = time.monotonic()
        check = _manager_verify_queue_file(active_file)
        check = _scope_successful_file_check_to_declaration(
            active_file,
            target_symbol,
            check,
        )
        check = _enforce_manager_axiom_profile(active_file, target_symbol, check)
        phase_seconds["canonical_file_check"] = max(0.0, time.monotonic() - phase_started)
        return finish(check, "lean_verify", route="low-memory-file")
    if target_symbol and active_file:
        phase_started = time.monotonic()
        manager_verification = _manager_incremental_check_queue_item(active_file, target_symbol)
        phase_seconds["incremental_check"] = max(0.0, time.monotonic() - phase_started)
        incremental_payload = dict(manager_verification.get("incremental") or {})
        if incremental_payload.get("success", False):
            timeout_text = " ".join(
                str(value or "")
                for value in (
                    manager_verification.get("output"),
                    manager_verification.get("error"),
                    incremental_payload.get("output"),
                    incremental_payload.get("error"),
                    incremental_payload.get("error_code"),
                )
            ).lower()
            deterministic_timeout = bool(incremental_payload.get("timed_out")) or any(
                marker in timeout_text
                for marker in (
                    "maximum number of heartbeats",
                    "maxheartbeats",
                    "deterministic timeout",
                )
            )
            if not deterministic_timeout:
                phase_started = time.monotonic()
                manager_verification = _enforce_manager_axiom_profile(
                    active_file, target_symbol, manager_verification
                )
                phase_seconds["axiom_profile"] = max(0.0, time.monotonic() - phase_started)
                return finish(
                    manager_verification,
                    "lean_incremental_check",
                    route="incremental",
                )
            _record_activity(
                "manager-incremental-timeout-bounded",
                f"LeanProbe timed out for {target_symbol}; skipped canonical file verification",
                target_symbol=target_symbol,
                active_file=active_file,
                timeout_s=_manager_incremental_check_timeout_s(),
                campaign_progress=False,
            )
            manager_verification["fallback_suppressed"] = True
            manager_verification["fallback_reason"] = (
                "deterministic LeanProbe timeout; keep the inner loop bounded"
            )
            return finish(
                manager_verification,
                "lean_incremental_check",
                route="incremental-timeout",
            )
    phase_started = time.monotonic()
    check = _manager_verify_queue_file(active_file)
    check = _scope_successful_file_check_to_declaration(
        active_file,
        target_symbol,
        check,
    )
    check = _enforce_manager_axiom_profile(active_file, target_symbol, check)
    phase_seconds["canonical_file_fallback"] = max(0.0, time.monotonic() - phase_started)
    return finish(check, "lean_verify", route="canonical-file-fallback")


def _manager_check_queue_item_transaction(
    active_file: str,
    target_symbol: str,
    *,
    purpose: str,
    required_axiom_profile: bool = False,
) -> tuple[dict[str, Any], str]:
    """Run one parent exact-plus-axiom gate under foreground admission."""
    started = time.monotonic()
    admission_details: dict[str, object] = {}
    phase_seconds: dict[str, float] = {}
    manager_tool = ""
    completed = False
    _record_activity(
        "manager-verification-transaction-start",
        f"Parent verification transaction started for {target_symbol}",
        target_symbol=target_symbol,
        active_file=active_file,
        purpose=purpose,
    )
    try:
        with verification_transaction.parent_lean_verification_transaction(
            active_file or _project_root()
        ) as admission:
            admission_details = admission.to_dict()
            phase_started = time.monotonic()
            manager_check, manager_tool = _manager_check_queue_item(active_file, target_symbol)
            phase_seconds["manager_check"] = max(0.0, time.monotonic() - phase_started)
            phase_started = time.monotonic()
            manager_check = _enforce_manager_axiom_profile(
                active_file,
                target_symbol,
                manager_check,
                required=required_axiom_profile,
            )
            phase_seconds["required_axiom_enforcement"] = max(0.0, time.monotonic() - phase_started)
            completed = True
            return manager_check, manager_tool
    finally:
        with contextlib.suppress(Exception):
            elapsed_s = max(0.0, time.monotonic() - started)
            try:
                admission_wait_s = max(0.0, float(admission_details.get("waited_s", 0) or 0))
            except (TypeError, ValueError):
                admission_wait_s = 0.0
            measured_s = admission_wait_s + sum(phase_seconds.values())
            phase_seconds["unattributed"] = max(0.0, elapsed_s - measured_s)
            _record_activity(
                "manager-verification-transaction",
                f"Parent verification transaction finished for {target_symbol}",
                target_symbol=target_symbol,
                active_file=active_file,
                purpose=purpose,
                completed=completed,
                manager_tool=manager_tool,
                elapsed_s=round(elapsed_s, 3),
                phase_seconds={key: round(value, 3) for key, value in phase_seconds.items()},
                resource_admission=admission_details,
            )


def _verification_record_from_check(
    active_file: str,
    target_symbol: str,
    manager_check: Mapping[str, Any],
    manager_tool: str,
    *,
    full_project: bool = False,
) -> dict[str, Any]:
    check = dict(manager_check or {})
    incremental = dict(check.get("incremental") or {})
    output = str(
        check.get("output", "")
        or check.get("error", "")
        or incremental.get("output", "")
        or incremental.get("error", "")
        or ""
    )
    errors, warnings, sorry_count = _diagnostic_counts_from_messages(
        output=output,
        messages=incremental.get("messages") or check.get("messages"),
    )
    for key, current in (
        ("errors", errors),
        ("warnings", warnings),
        ("sorry", sorry_count),
    ):
        explicit = incremental.get(key, check.get(key, check.get(f"{key}_count", 0)))
        try:
            explicit_count = max(0, int(explicit or 0))
        except (TypeError, ValueError):
            explicit_count = 0
        if key == "errors":
            errors = max(current, explicit_count)
        elif key == "warnings":
            warnings = max(current, explicit_count)
        else:
            sorry_count = max(current, explicit_count)
    structured_sorry = incremental.get("sorry", incremental.get("sorry_count"))
    try:
        structured_sorry_count = max(0, int(structured_sorry or 0))
    except (TypeError, ValueError):
        structured_sorry_count = -1
    if (
        incremental.get("success") is True
        and incremental.get("has_sorry") is False
        and structured_sorry_count == 0
    ):
        # The exact Lean payload is stronger than fallback prose parsing. In
        # particular, an axiom-policy diagnostic may mention ``sorryAx`` or
        # say "no sorry" while the checked declaration is structurally clean.
        sorry_count = 0
    if (bool(incremental.get("has_errors")) or bool(check.get("has_errors"))) and errors == 0:
        errors = 1
    if (bool(incremental.get("has_sorry")) or bool(check.get("has_sorry"))) and sorry_count == 0:
        sorry_count = 1
    cache = dict(incremental.get("cache") or check.get("cache") or {})
    if "cache_hit" in cache:
        cache_label = "warm" if bool(cache.get("cache_hit")) else "cold"
    elif cache:
        cache_label = "warm"
    else:
        cache_label = ""
    elapsed = incremental.get("elapsed_s", check.get("elapsed_s", 0))
    try:
        elapsed_s = float(elapsed or 0.0)
    except (TypeError, ValueError):
        elapsed_s = 0.0
    # Direct prover tool results expose telemetry at the top level, while
    # manager-owned checks wrap the same payload under ``incremental``.
    incremental_timing = dict(
        incremental.get("leanflow_timing") or check.get("leanflow_timing") or {}
    )
    resource_admission = dict(
        incremental.get("resource_admission") or check.get("resource_admission") or {}
    )

    def timing_float(value: Any) -> float:
        """Return one non-negative timing value from structured tool telemetry."""
        try:
            return max(0.0, float(value or 0.0))
        except (TypeError, ValueError):
            return 0.0

    probe_wall_elapsed_s = timing_float(incremental_timing.get("total_s"))
    admission_wait_s = timing_float(resource_admission.get("waited_s"))
    if probe_wall_elapsed_s > 0.0:
        # A nested admission happens outside the tool's own timer. A top-level
        # admission is already included in ``leanflow_timing.total_s``.
        tool_wall_elapsed_s = probe_wall_elapsed_s
        if resource_admission.get("nested") is True:
            tool_wall_elapsed_s += admission_wait_s
    else:
        tool_wall_elapsed_s = elapsed_s + admission_wait_s
    if manager_tool == "source_placeholder_gate":
        scope = f"target:{target_symbol or check.get('target', '') or '[unknown]'}"
        tool = manager_tool
    elif (
        str(check.get("verification_scope", "") or "").strip().lower() == "target"
        or manager_tool == "lean_incremental_check"
        or str(check.get("mode", "")) == "incremental_target"
    ):
        scope = f"target:{target_symbol or check.get('target', '') or '[unknown]'}"
        tool = "lean_incremental_check"
    elif full_project:
        scope = "project"
        tool = "lean_verify"
    else:
        scope = "file"
        tool = str(manager_tool or "lean_verify")
    summary = str(check.get("command", "") or "").strip()
    if output:
        summary = (
            f"{summary}: {_single_line(output, 220)}" if summary else _single_line(output, 220)
        )
    record = {
        "scope": scope,
        "ok": bool(check.get("ok", False)),
        "tool": tool,
        "target": str(target_symbol or check.get("target", "") or ""),
        "active_file": str(active_file or check.get("target", "") or ""),
        "cache": cache_label,
        "elapsed_s": round(elapsed_s, 3),
        "lean_command_elapsed_s": round(elapsed_s, 3),
        "probe_wall_elapsed_s": round(probe_wall_elapsed_s, 3),
        "tool_wall_elapsed_s": round(tool_wall_elapsed_s, 3),
        "errors": errors,
        "warnings": warnings,
        "sorry": sorry_count,
        "summary": summary,
        "command": str(check.get("command", "") or ""),
    }
    if "axiom_profile_checked" in check:
        record["axiom_profile_checked"] = check.get("axiom_profile_checked") is True
        record["axiom_profile_axioms"] = [
            str(axiom) for axiom in list(check.get("axiom_profile_axioms") or [])
        ]
        record["axiom_profile_blockers"] = [
            str(blocker) for blocker in list(check.get("axiom_profile_blockers") or [])
        ]
    return record


def _active_file_warning_summary(live_state: Mapping[str, Any] | None) -> tuple[int, str]:
    """Count style/linter warnings on the active file from the latest live state.

    Reads the structured diagnostics already attached to ``live_state`` by the
    most recent ``lean_inspect`` refresh. Returns ``(count, summary)`` where
    ``summary`` is a short multi-line string suitable for prompts and logs.
    The check is intentionally cheap — no extra Lean process is spawned here;
    we trust the live-state refresh that the workflow loop just performed.
    """
    diagnostics_text = str((live_state or {}).get("diagnostics", "") or "")
    if not diagnostics_text:
        return 0, ""
    items = diagnostic_items(diagnostics_text)
    warnings: list[dict[str, Any]] = [
        item for item in items if str(item.get("severity", "") or "").strip().lower() == "warning"
    ]
    # Exact startup verification returns ordinary Lean/lake text rather than
    # the structured diagnostic payload produced by lean_inspect. Parse only
    # canonical warning headers; continuation and "Note:" lines must not
    # inflate the warning count. Prefer the complete plain-text parse when
    # present because diagnostic_items may recognize only one of Lean's two
    # textual warning layouts.
    prefixed_warning = re.compile(
        r"^warning:\s+.+?:(?P<line>\d+):(?P<column>\d+):\s*(?P<message>.*)$"
    )
    suffixed_warning = re.compile(
        r"^.+?:(?P<line>\d+):(?P<column>\d+):\s*warning:\s*(?P<message>.*)$"
    )
    plain_warnings: list[dict[str, Any]] = []
    for line_text in diagnostics_text.splitlines():
        match = prefixed_warning.match(line_text.strip()) or suffixed_warning.match(
            line_text.strip()
        )
        if match is None:
            continue
        plain_warnings.append(
            {
                "severity": "warning",
                "line": int(match.group("line")),
                "message": match.group("message").strip(),
            }
        )
    if plain_warnings:
        warnings = plain_warnings
    if not warnings:
        return 0, ""
    summary_lines = []
    for item in warnings[:6]:
        line = item.get("line") if isinstance(item.get("line"), int) else None
        message = _single_line(str(item.get("message", "") or ""), 160)
        prefix = f"line {line}: " if line else ""
        summary_lines.append(f"- {prefix}{message}".rstrip())
    if len(warnings) > 6:
        summary_lines.append(f"- ...and {len(warnings) - 6} more warning(s)")
    return len(warnings), "\n".join(summary_lines)


def _capture_final_sweep_baseline(
    autonomy_state: Mapping[str, Any] | None,
    active_file: str,
) -> bool:
    """Snapshot the active file's content into autonomy_state for restore-on-fail.

    Returns False if we cannot read the file; in that case the caller should
    skip the cleanup attempt entirely (we cannot promise warning-tolerant
    rollback without a baseline).
    """
    if not isinstance(autonomy_state, dict):
        return False
    try:
        content = Path(active_file).read_text(encoding="utf-8")
    except Exception:
        return False
    autonomy_state["final_sweep_baseline"] = {
        "active_file": str(Path(active_file).resolve()),
        "content": content,
    }
    return True


def _restore_final_sweep_baseline(
    autonomy_state: Mapping[str, Any] | None,
    active_file: str,
) -> bool:
    """Rewrite the active file from the captured baseline. Returns True on success."""
    if not isinstance(autonomy_state, dict):
        return False
    baseline = dict(autonomy_state.get("final_sweep_baseline") or {})
    content = baseline.get("content")
    baseline_file = str(baseline.get("active_file", "") or "")
    if not isinstance(content, str) or not baseline_file:
        return False
    try:
        if Path(baseline_file).resolve() != Path(active_file).resolve():
            return False
        Path(active_file).write_text(content, encoding="utf-8")
    except Exception:
        return False
    return True


def _with_warning_cleanup_state(
    live_state: Mapping[str, Any] | None,
    *,
    status: str,
    proof_solved: bool,
    warning_count: int = 0,
    warning_summary: str = "",
    diagnostics: str = "",
    attempted: bool | None = None,
    verified: bool | None = None,
) -> dict[str, Any]:
    """Attach the shell-visible post-prove warning-cleanup state machine."""
    normalized = dict(live_state or {})
    normalized["proof_solved"] = bool(proof_solved)
    normalized["warning_cleanup_status"] = str(status or "unknown")
    normalized["warning_cleanup_attempted"] = (
        bool(attempted)
        if attempted is not None
        else status
        in {
            "pending",
            "verified",
            "blocked",
        }
    )
    normalized["warning_cleanup_verified"] = (
        bool(verified) if verified is not None else status == "verified"
    )
    normalized["warning_cleanup_skipped"] = status == "skipped"
    normalized["warning_cleanup_blocked"] = status == "blocked"
    normalized["warning_cleanup_warning_count"] = int(warning_count or 0)
    normalized["warning_cleanup_warning_summary"] = str(warning_summary or "")
    normalized["warning_cleanup_diagnostics"] = str(diagnostics or "")
    normalized["warning_cleanup"] = {
        "status": normalized["warning_cleanup_status"],
        "proof_solved": normalized["proof_solved"],
        "attempted": normalized["warning_cleanup_attempted"],
        "verified": normalized["warning_cleanup_verified"],
        "skipped": normalized["warning_cleanup_skipped"],
        "blocked": normalized["warning_cleanup_blocked"],
        "warning_count": normalized["warning_cleanup_warning_count"],
        "warning_summary": normalized["warning_cleanup_warning_summary"],
        "diagnostics": normalized["warning_cleanup_diagnostics"],
    }
    return normalized


def _record_final_sweep_cleanup_outcome_once(
    autonomy_state: Mapping[str, Any] | None,
    *,
    status: str,
    active_file: str,
    warning_count: int = 0,
    diagnostics: str = "",
) -> None:
    if not isinstance(autonomy_state, dict):
        return
    normalized_status = str(status or "").strip().lower()
    if normalized_status not in {"verified", "accepted", "skipped", "blocked"}:
        return
    signature = json.dumps(
        {
            "status": normalized_status,
            "active_file": str(active_file or ""),
            "warning_count": int(warning_count or 0),
            "diagnostics": _single_line(diagnostics, 220),
        },
        sort_keys=True,
    )
    if str(autonomy_state.get("final_sweep_cleanup_outcome_recorded", "") or "") == signature:
        return
    autonomy_state["final_sweep_cleanup_outcome_recorded"] = signature
    messages = {
        "verified": "Final-sweep warning cleanup verified",
        "accepted": "Final-sweep warning cleanup accepted with remaining warnings",
        "skipped": "Final-sweep warning cleanup skipped",
        "blocked": "Final-sweep warning cleanup blocked",
    }
    _record_activity(
        f"final-sweep-warning-cleanup-{normalized_status}",
        messages[normalized_status],
        active_file=active_file,
        warning_count=int(warning_count or 0),
        diagnostics=_single_line(diagnostics, 520),
    )


def _store_last_verification(
    autonomy_state: Mapping[str, Any] | None,
    record: Mapping[str, Any] | None,
) -> None:
    if not isinstance(autonomy_state, dict) or not isinstance(record, Mapping):
        return
    parsed = verification_from_mapping(record)
    if parsed is None:
        return
    mgr = _queue_manager_from_state(autonomy_state)
    mgr.record_verification(parsed)
    _flush_queue_manager(autonomy_state, mgr)


def _verification_status_text(record: Mapping[str, Any] | None) -> str:
    record = dict(record or {})
    if not record:
        return ""
    status = "passed" if bool(record.get("ok")) else "failed"
    scope = str(record.get("scope", "") or "verification")
    tool = str(record.get("tool", "") or "manager")
    detail_parts = [f"{scope} {status}", f"tool: {tool}"]
    if record.get("cache"):
        detail_parts.append(f"cache: {record.get('cache')}")
    tool_wall = record.get("tool_wall_elapsed_s")
    lean_commands = record.get("lean_command_elapsed_s", record.get("elapsed_s"))
    if tool_wall not in (None, "", 0, 0.0):
        detail_parts.append(f"wall: {tool_wall}s")
        if lean_commands not in (None, "", 0, 0.0) and lean_commands != tool_wall:
            detail_parts.append(f"Lean commands: {lean_commands}s")
    elif record.get("elapsed_s") not in (None, "", 0, 0.0):
        detail_parts.append(f"elapsed: {record.get('elapsed_s')}s")
    counts = []
    for key, label in (("errors", "errors"), ("warnings", "warnings"), ("sorry", "sorry")):
        if record.get(key) not in (None, ""):
            counts.append(f"{label}: {int(record.get(key) or 0)}")
    if counts:
        detail_parts.append(", ".join(counts))
    summary = str(record.get("summary", "") or "").strip()
    if summary:
        detail_parts.append(_single_line(summary, 220))
    return " | ".join(detail_parts)


def _recent_verification_status(
    autonomy_state: Mapping[str, Any] | None = None,
    live_state: Mapping[str, Any] | None = None,
) -> str:
    return _verification_status_text(_last_verification_record(autonomy_state, live_state))


def _record_manager_verification(
    autonomy_state: Mapping[str, Any] | None,
    active_file: str,
    target_symbol: str,
    manager_check: Mapping[str, Any],
    manager_tool: str,
    *,
    full_project: bool = False,
    log: bool = True,
) -> dict[str, Any]:
    record = _verification_record_from_check(
        active_file,
        target_symbol,
        manager_check,
        manager_tool,
        full_project=full_project,
    )
    _store_last_verification(autonomy_state, record)
    if log:
        _log_manager_verification(
            active_file,
            full_project=full_project,
            ok=bool(record.get("ok")),
            build_status=_verification_status_text(record),
            scope=str(record.get("scope", "") or ""),
            target_symbol=target_symbol,
            tool=str(record.get("tool", "") or manager_tool),
            cache=str(record.get("cache", "") or ""),
            elapsed_s=record.get("tool_wall_elapsed_s") or record.get("elapsed_s"),
            errors=int(record.get("errors", 0) or 0),
            warnings=int(record.get("warnings", 0) or 0),
            sorry_count=int(record.get("sorry", 0) or 0),
        )
    return record


def _json_tool_result_payload(result: str) -> dict[str, Any]:
    try:
        payload = json.loads(str(result or ""))
    except Exception:
        return {}
    return dict(payload) if isinstance(payload, Mapping) else {}


def _pending_route_for_assignment(
    autonomy_state: Mapping[str, Any],
    *,
    target_symbol: str,
    active_file: str,
) -> str:
    """Return one exact-scope active strategy route, if any.

    Mechanical routes may consume their in-flight marker as soon as durable
    route evidence is recorded, before the provider checks a helper produced
    during that same route. Preserve that exact-scope execution identity until
    another route application replaces it.
    """
    for key in (
        "prover_requested_route",
        "campaign_inflight_route",
        "campaign_epoch_route_selection",
    ):
        raw = autonomy_state.get(key)
        route = dict(raw) if isinstance(raw, Mapping) else {}
        route_name = str(route.get("route", "") or "").strip().lower()
        route_target = str(route.get("target_symbol", "") or "").strip()
        route_file = str(route.get("active_file", "") or "").strip()
        if (
            route_name
            and route_target == target_symbol
            and route_file
            and _same_active_file(route_file, active_file)
        ):
            return route_name
    execution = _current_orchestrator_route_execution(autonomy_state)
    if (
        execution is not None
        and execution.route
        and execution.target_symbol == target_symbol
        and _same_active_file(execution.active_file, active_file)
    ):
        return execution.route
    return ""


def _retain_foreground_checked_helper(
    agent: Any,
    function_name: str,
    arguments: Mapping[str, Any],
    result: str,
) -> research_helper_candidate_priority.PendingResearchHelperCandidate | None:
    """Durably retain one exact foreground-checked helper before handoff."""
    if function_name != "lean_incremental_check":
        return None
    autonomy_state = getattr(agent, "_managed_autonomy_state", None)
    if not isinstance(autonomy_state, dict):
        return None
    assignment = dict(autonomy_state.get("current_queue_assignment") or {})
    target_symbol = str(assignment.get("target_symbol", "") or "").strip()
    active_file = str(assignment.get("active_file", "") or "").strip()
    if not target_symbol or not active_file:
        return None
    payload = _json_tool_result_payload(result)
    if (
        str(arguments.get("action", "") or "").strip() == "check_helper"
        and payload.get("ok") is True
        and _pending_route_for_assignment(
            autonomy_state,
            target_symbol=target_symbol,
            active_file=active_file,
        )
        == "negate"
    ):
        # Negation has a dedicated exact-target authentication path. Generic
        # helper priority must not turn an audit fact or finite obstruction into
        # mandatory production source growth merely because it elaborates.
        _record_agent_activity(
            agent,
            "negate-route-helper-retained-as-evidence",
            f"Kept checked helper evidence for negate route on {target_symbol}",
            target_symbol=target_symbol,
            active_file=active_file,
            replacement_declarations=list(payload.get("replacement_declarations") or ()),
            campaign_progress=False,
        )
        agent.stage_tool_result_appendix(
            "LeanProbe checked this negate-route helper, and LeanFlow preserved the result as "
            "evidence without reserving mandatory source integration. Only an authenticated "
            "exact target negation or a concrete target-advancing construction may preempt the "
            "foreground."
        )
        return None
    prior = research_helper_candidate_priority.load(autonomy_state)
    record = research_helper_candidate_priority.remember_from_foreground_check(
        autonomy_state,
        arguments,
        payload,
        campaign_id=str(autonomy_state.get("campaign_id", "") or "campaign"),
        target_symbol=target_symbol,
        active_file=active_file,
    )
    if record is None:
        record = research_helper_candidate_priority.remember_nonproduction_from_foreground_check(
            autonomy_state,
            arguments,
            payload,
            campaign_id=str(autonomy_state.get("campaign_id", "") or "campaign"),
            target_symbol=target_symbol,
            active_file=active_file,
        )
        if record is not None:
            _record_agent_activity(
                agent,
                "foreground-helper-production-name-required",
                f"Verified scratch helper {record.helper_name} requires a production name",
                target_symbol=target_symbol,
                active_file=active_file,
                helper_name=record.helper_name,
                candidate_id=record.candidate_id,
                declaration_sha256=record.declaration_sha256,
                campaign_progress=False,
            )
            agent.stage_tool_result_appendix(
                f"LeanProbe verified `{record.helper_name}` and LeanFlow durably preserved the "
                "exact substantive declaration. Immediately resubmit the same declaration under "
                "a mathematical production name before unrelated work; change only the declared "
                "name. LeanFlow will retain and prioritize the renamed helper across compression "
                "and later epochs."
            )
        return record
    displaced = (
        prior
        if prior is not None
        and prior.candidate_id != record.candidate_id
        and any(
            candidate.candidate_id == prior.candidate_id
            for candidate in research_helper_candidate_priority.backlog(autonomy_state)
        )
        else None
    )
    _record_agent_activity(
        agent,
        (
            "foreground-helper-candidate-preempted"
            if displaced is not None
            else "foreground-helper-candidate-retained"
        ),
        (
            f"Retained verified helper candidate {record.helper_name}; preserved "
            f"older candidate {displaced.helper_name} in the durable backlog"
            if displaced is not None
            else f"Retained verified helper candidate {record.helper_name} for parent recheck"
        ),
        target_symbol=target_symbol,
        active_file=active_file,
        helper_name=record.helper_name,
        candidate_id=record.candidate_id,
        declaration_sha256=record.declaration_sha256,
        displaced_candidate_id=(displaced.candidate_id if displaced is not None else ""),
        displaced_helper_name=(displaced.helper_name if displaced is not None else ""),
        campaign_progress=False,
    )
    agent.stage_tool_result_appendix(
        "LeanFlow durably retained the exact checked helper "
        f"`{record.helper_name}`. "
        + (
            f"The older checked helper `{displaced.helper_name}` remains queued behind it. "
            if displaced is not None
            else ""
        )
        + "Before unrelated work, the manager will recheck it "
        "against the current parent file and offer authenticated integration."
    )
    return record


def _project_managed_tool_result(
    function_name: str,
    _arguments: Mapping[str, Any],
    result: str,
) -> str:
    """Return bounded provider context while workflow activity keeps full evidence."""
    payload = _json_tool_result_payload(result)
    if not payload:
        return result
    if function_name == "lean_incremental_check":
        projected = compact_check_payload(payload)
    elif function_name == "lean_multi_attempt":
        projected = compact_multi_attempt_payload(payload)
    else:
        return result
    return json.dumps(projected, ensure_ascii=False)


def _disable_agent_tool_schema(agent: Any, tool_name: str) -> None:
    name = str(tool_name or "").strip()
    if not name:
        return
    tools = list(getattr(agent, "tools", []) or [])
    filtered = [
        tool
        for tool in tools
        if str(dict(tool.get("function", {}) or {}).get("name", "") or "") != name
    ]
    if len(filtered) != len(tools):
        agent.tools = filtered
    valid = set(getattr(agent, "valid_tool_names", set()) or set())
    if name in valid:
        valid.remove(name)
        agent.valid_tool_names = valid


_TEMPORARY_TOOL_SCHEMAS_ATTR = "_managed_temporary_tool_schemas"
_AUTHORITATIVE_RESUME_BOOTSTRAP_KEY = "authoritative_resume_bootstrap"
_RESUME_BOOTSTRAP_TOOL_NAMES = frozenset(
    {
        "lean_capabilities",
        "lean_inspect",
        "lean_lemma_suggest",
        "lean_search",
        "lean_sorries",
    }
)


def _restore_temporary_agent_tool_schemas(agent: Any) -> None:
    """Restore tool schemas hidden only for the previous provider turn."""
    stored = dict(getattr(agent, _TEMPORARY_TOOL_SCHEMAS_ATTR, {}) or {})
    if not stored:
        return
    autonomy_state = getattr(agent, "_managed_autonomy_state", None)
    permanently_disabled = {
        str(entry.get("name", "") or "").strip()
        for entry in list(dict(autonomy_state or {}).get("disabled_tools_this_run") or [])
        if isinstance(entry, Mapping)
    }
    tools = list(getattr(agent, "tools", []) or [])
    present = {str(dict(tool.get("function", {}) or {}).get("name", "") or "") for tool in tools}
    restored_names: set[str] = set()
    for name, schema in stored.items():
        if name in permanently_disabled or name in present:
            continue
        tools.append(schema)
        restored_names.add(name)
    agent.tools = tools
    valid = set(getattr(agent, "valid_tool_names", set()) or set())
    valid.update(restored_names)
    agent.valid_tool_names = valid
    setattr(agent, _TEMPORARY_TOOL_SCHEMAS_ATTR, {})


def _temporarily_disable_agent_tool_schemas(agent: Any, tool_names: set[str]) -> None:
    """Hide known-unavailable tools until the next managed provider turn."""
    requested = {str(name or "").strip() for name in tool_names if str(name or "").strip()}
    if not requested:
        return
    tools = list(getattr(agent, "tools", []) or [])
    stored = dict(getattr(agent, _TEMPORARY_TOOL_SCHEMAS_ATTR, {}) or {})
    filtered = []
    for tool in tools:
        name = str(dict(tool.get("function", {}) or {}).get("name", "") or "")
        if name in requested:
            stored.setdefault(name, tool)
        else:
            filtered.append(tool)
    agent.tools = filtered
    valid = set(getattr(agent, "valid_tool_names", set()) or set())
    valid.difference_update(requested)
    agent.valid_tool_names = valid
    setattr(agent, _TEMPORARY_TOOL_SCHEMAS_ATTR, stored)


def _sync_construction_only_tool_surface(agent: Any, autonomy_state: Mapping[str, Any]) -> None:
    """Hide schemas whose deterministic construction or advisor fence is closed."""
    _restore_temporary_agent_tool_schemas(agent)
    if _workflow_kind() != "prove" or not _single_queue_item_turn_enabled():
        return
    assignment = dict(autonomy_state.get("current_queue_assignment") or {})
    resume_bootstrap = dict(autonomy_state.get(_AUTHORITATIVE_RESUME_BOOTSTRAP_KEY) or {})
    if isinstance(autonomy_state, dict):
        autonomy_state.pop(_AUTHORITATIVE_RESUME_BOOTSTRAP_KEY, None)
    if resume_bootstrap:
        target_symbol = str(assignment.get("target_symbol", "") or "").strip()
        active_file = str(assignment.get("active_file", "") or "").strip()
        if (
            target_symbol == str(resume_bootstrap.get("target_symbol", "") or "").strip()
            and _same_active_file(
                active_file,
                str(resume_bootstrap.get("active_file", "") or "").strip(),
            )
            and _source_revision_sha256(active_file)
            == str(resume_bootstrap.get("source_revision_sha256", "") or "").strip()
        ):
            _temporarily_disable_agent_tool_schemas(
                agent,
                set(_RESUME_BOOTSTRAP_TOOL_NAMES),
            )
            with contextlib.suppress(Exception):
                _record_agent_activity(
                    agent,
                    "authoritative-resume-tool-surface",
                    "Suppressed redundant bootstrap tools for the first resumed provider turn",
                    target_symbol=target_symbol,
                    active_file=active_file,
                    hidden_tools=sorted(_RESUME_BOOTSTRAP_TOOL_NAMES),
                    source_revision_sha256=_source_revision_sha256(active_file),
                    campaign_progress=False,
                )
    target_symbol = str(assignment.get("target_symbol", "") or "").strip()
    active_file = str(assignment.get("active_file", "") or "").strip()
    if not target_symbol or not active_file:
        return
    blocked_advisors = {
        name
        for name in advisor_failure_circuit.ADVISOR_TOOL_NAMES
        if _advisor_failure_admission(autonomy_state, name).blocked
    }
    if blocked_advisors:
        _temporarily_disable_agent_tool_schemas(agent, blocked_advisors)
        with contextlib.suppress(Exception):
            _record_agent_activity(
                agent,
                "advisor-circuit-tool-surface",
                f"Hid {len(blocked_advisors)} exhausted advisor tools for this provider turn",
                target_symbol=target_symbol,
                active_file=active_file,
                hidden_tools=sorted(blocked_advisors),
                campaign_progress=False,
            )
    tracker = dict(autonomy_state.get("search_progress") or {})
    if not tracker:
        return
    try:
        current_cycle = int(autonomy_state.get("current_cycle", 0) or 0)
    except (TypeError, ValueError):
        current_cycle = 0
    blocked_names: set[str] = set()
    for name in search_synthesis_admission.DISCOVERY_TOOL_NAMES:
        if (
            name == search_synthesis_admission.LEAN_INCREMENTAL_INSPECTION_TOOL_NAME
            or name in search_synthesis_admission.PATH_SCOPED_DISCOVERY_TOOL_NAMES
        ):
            # Keep path-scoped schemas visible so safe managed-context requests
            # can pass; concrete source requests still face the pre-tool fence.
            continue
        blocked = search_synthesis_admission.blocked_search_result(
            function_name=name,
            tracker=tracker,
            target_symbol=target_symbol,
            active_file=active_file,
            current_cycle=current_cycle,
        )
        if blocked is None and current_cycle:
            blocked = search_synthesis_admission.blocked_construction_source_result(
                function_name=name,
                tracker=tracker,
                target_symbol=target_symbol,
                active_file=active_file,
                current_cycle=current_cycle,
            )
        if blocked is not None:
            blocked_names.add(name)
    if _rollback_refresh_required_for_assignment(autonomy_state):
        blocked_names.discard("read_file")
    if not blocked_names:
        return
    _temporarily_disable_agent_tool_schemas(agent, blocked_names)
    with contextlib.suppress(Exception):
        _record_agent_activity(
            agent,
            "construction-only-tool-surface",
            f"Hid {len(blocked_names)} unavailable discovery tools for this provider turn",
            target_symbol=target_symbol,
            active_file=active_file,
            hidden_tools=sorted(blocked_names),
            campaign_progress=False,
        )


def _record_disabled_tool_this_run(
    autonomy_state: Mapping[str, Any] | None,
    tool_name: str,
    reason: str = "",
) -> None:
    if not isinstance(autonomy_state, dict):
        return
    name = str(tool_name or "").strip()
    if not name:
        return
    mgr = _queue_manager_from_state(autonomy_state)
    mgr.disable_tool(name, _single_line(reason, 240))
    _flush_queue_manager(autonomy_state, mgr)


def _disabled_tools_summary(autonomy_state: Mapping[str, Any] | None) -> list[str]:
    entries = []
    for entry in list(dict(autonomy_state or {}).get("disabled_tools_this_run") or []):
        if not isinstance(entry, Mapping):
            continue
        name = str(entry.get("name", "") or "").strip()
        if not name:
            continue
        reason = str(entry.get("reason", "") or "").strip()
        entries.append(f"{name} ({reason})" if reason else name)
    return entries


def _sync_disabled_tools_from_result(agent: Any, function_name: str, result: str) -> None:
    payload = _json_tool_result_payload(result)
    if not payload:
        return
    reasons = [
        str(reason) for reason in list(payload.get("degraded_reasons") or []) if str(reason).strip()
    ]
    joined = " ".join(reasons).lower()
    tool_to_disable = ""
    if function_name == "lean_auto_try" and "lean automation try disabled for this run" in joined:
        tool_to_disable = "lean_auto_try"
    elif function_name == "lean_auto_search" and (
        str(payload.get("status", "") or "").strip().lower() == "unavailable_no_attempts"
        and int(payload.get("attempts", 0) or 0) == 0
        and int(payload.get("explored_sets", 0) or 0) == 0
    ):
        # This is backend unavailability, not negative proof evidence. Keep it
        # durable for the campaign so compression and fresh theorem turns do
        # not repeatedly spend calls on a search service that explored nothing.
        tool_to_disable = "lean_auto_search"
    if not tool_to_disable:
        return
    autonomy_state = getattr(agent, "_managed_autonomy_state", None)
    reason = next(
        (reason for reason in reasons if "disabled for this run" in reason.lower()),
        (
            reasons[0]
            if reasons
            else str(payload.get("unavailable_reason", "") or payload.get("status", "") or "")
        ),
    )
    _record_disabled_tool_this_run(
        autonomy_state if isinstance(autonomy_state, dict) else None, tool_to_disable, reason
    )
    _disable_agent_tool_schema(agent, tool_to_disable)
    _record_activity(
        "managed-tool-disabled",
        f"Disabled {tool_to_disable} for the rest of this run",
        tool=tool_to_disable,
        reason=reason,
    )


def _latest_assistant_content(messages: list[dict[str, Any]]) -> str:
    for message in reversed(messages):
        if str(message.get("role", "") or "") == "assistant":
            return str(message.get("content", "") or "").strip()
    return ""


def _final_report_claims_queue_success(text: str, target_symbol: str = "") -> bool:
    """Return whether a final report explicitly claims the assigned proof is complete.

    Verified helpers, successful searches, and completed research passes are progress,
    not claims about the queue target. Keep this classifier conservative because it
    controls the manager's user-facing diagnosis when kernel verification rejects a
    turn; the kernel gate remains the actual acceptance authority.
    """
    lowered = str(text or "").strip().lower()
    if not lowered:
        return False
    negative_patterns = (
        r"^\s*(?:blocked|stalled)\b",
        r"\bstatus\s*:\s*(?:blocked|stalled|unresolved|unsolved)\b",
        r"\bstill\s+(?:blocked|failing|fails|has errors?)\b",
        r"\bnot\s+(?:solved|proved|verified|complete|completed|done)\b",
        r"\b(?:cannot|can't|could not|unable to)\s+(?:prove|solve|verify|finish)\b",
        r"\b(?:cannot|can't|could not|unable to)\s+be\s+(?:soundly\s+)?(?:proved|solved|verified|repaired|finished|completed)\b",
        r"\bverification\s+(?:failed|fails)\b",
        r"\brequested\s+route\s*(?::|=|is\b|-)",
        r"\bremains?\s+(?:blocked|stalled|failing|unsolved|open|unresolved|unproved)\b",
        r"\b(?:sorry|open goals?)\s+remains?\b",
        r"\b(?:still|continues?\s+to)\s+(?:contains?|uses?|has)\b[^.\n]{0,80}\b(?:sorry|admit|open goals?)\b",
        r"\b(?:genuine\s+)?open[- ]problem\s+blocker\b",
        r"\bdoes\s+not\s+(?:solve|prove|verify|complete|close)\b",
        r"\b(?:target|assigned\s+(?:declaration|goal|theorem|lemma)|main\s+goal)\s+remains?\s+on\b[^.\n]{0,80}\bblocker\b",
    )
    if any(re.search(pattern, lowered) for pattern in negative_patterns):
        return False

    success_word = r"(?:solved|proved|verified|complete|completed|done|closed)"
    target_subject = (
        r"(?:assigned|requested|current|queue)\s+"
        r"(?:proof\s+)?(?:target|goal|declaration|theorem|lemma|scope)"
        r"|main\s+(?:goal|theorem|lemma|claim)"
    )
    success_patterns = (
        rf"\b(?:{target_subject})\b\s+(?:(?:is|was|has\s+been|is\s+now)\s+)?"
        rf"(?:fully\s+|kernel[- ]verified\s+and\s+)?\b{success_word}\b",
        rf"\b{success_word}\b\s+(?:the\s+)?\b(?:{target_subject})\b",
    )
    if any(re.search(pattern, lowered) for pattern in success_patterns):
        return True

    normalized_target = str(target_symbol or "").strip().lower()
    if not normalized_target:
        return False
    escaped_target = re.escape(normalized_target)
    target = rf"(?<![\w']){escaped_target}(?![\w'])"
    named_target_patterns = (
        rf"{target}`?\s+(?:(?:(?:is|was|has\s+been|is\s+now)\s+)"
        rf"(?:fully\s+|kernel[- ]verified\s+and\s+)?\b{success_word}\b"
        rf"|\b(?:solved|proved|completed|closed)\b)",
        rf"\b{success_word}\b\s+(?:and\s+\b{success_word}\b\s+)?"
        rf"(?:the\s+)?`?{target}`?(?=\s*(?:[.!;,\n]|$))",
    )
    return any(re.search(pattern, lowered) for pattern in named_target_patterns)


def _manager_final_report_feedback(
    target_symbol: str,
    active_file: str,
    manager_check: Mapping[str, Any],
) -> str:
    file_check_ok = bool(manager_check.get("file_check_ok", manager_check.get("ok")))
    status = "passed" if file_check_ok else "failed"
    command = str(manager_check.get("command", "") or "manager file verification")
    output = str(manager_check.get("output", "") or manager_check.get("error", "") or "").strip()
    blocker_kind = str(manager_check.get("feedback_kind", "") or "").strip()
    if manager_check.get("agent_claimed_success"):
        report_summary = (
            "The agent claimed this queue item was solved, so the manager ran "
            "deterministic verification."
        )
    else:
        report_summary = (
            "The agent ended an unresolved queue turn; the manager verified the live "
            "declaration before continuing it."
        )
    lines = [
        "[LEANFLOW-NATIVE MANAGER REVIEW]",
        report_summary,
        f"- declaration: {target_symbol or '[unknown]'}",
        f"- file: {active_file or '[unknown]'}",
        f"- manager file check: {status}",
        f"- check: `{command}`",
    ]
    if blocker_kind:
        lines.append(f"- blocker kind: {blocker_kind}")
    if output and blocker_kind != "warning":
        lines.append(f"- feedback: {_single_line(output, 700)}")
    elif output:
        lines.append(
            "- file check output: "
            + _single_line(output, 700)
            + " [not the blocking reason unless it points at the assigned declaration]"
        )
    if manager_check.get("local_cleanup_reason"):
        lines.append(
            f"- local cleanup: {_single_line(manager_check.get('local_cleanup_reason'), 700)}"
        )
    if blocker_kind == "warning":
        retry_count = int(manager_check.get("feedback_retry_count", 0) or 0)
        retry_limit = int(
            manager_check.get("feedback_retry_limit", MANAGER_WARNING_RETRY_LIMIT)
            or MANAGER_WARNING_RETRY_LIMIT
        )
        lines.append(
            f"- retry policy: warning-only cleanup gets {retry_limit} focused manager cleanup opportunity; "
            f"this is opportunity {retry_count + 1}."
        )
    if manager_check.get("ok"):
        lines.append("- next step: accept this report and refresh the queue.")
    elif blocker_kind == "warning":
        lines.append(
            "- next step: fix the warning(s) in the assigned declaration context; "
            "helper declarations created for this theorem may be adjusted, but do not solve unrelated future "
            "queue items just because their `sorry` warnings appear in file output."
        )
    elif blocker_kind == "sorry":
        lines.append(
            "- next step: continue the same theorem; the assigned declaration still contains `sorry`, "
            "so solve it or report a blocker with a requested route (`decompose` | `negate` | `plan`) and put "
            "retained counterexamples or ruled-out proof shapes under the exact heading `Negative evidence:`."
        )
    elif blocker_kind == "error":
        lines.append(
            "- next step: continue the same theorem; fix the assigned declaration's Lean error(s) "
            "before reporting success again."
        )
    else:
        lines.append(
            "- next step: continue the same theorem; fix the returned manager feedback before reporting success again."
        )
    return "\n".join(lines)


def _manager_feedback_retry_count(
    autonomy_state: Mapping[str, Any],
    *,
    target_symbol: str,
    active_file: str,
    kind: str,
) -> int:
    key = _queue_key(target_symbol, active_file)
    if not key.is_valid():
        return 0
    return _queue_manager_from_state(autonomy_state).retry_count_for(key, kind)


def _increment_manager_feedback_retry(
    autonomy_state: Mapping[str, Any],
    *,
    target_symbol: str,
    active_file: str,
    kind: str,
    signature: str = "",
) -> int:
    if not isinstance(autonomy_state, dict):
        return 0
    key = _queue_key(target_symbol, active_file)
    mgr = _queue_manager_from_state(autonomy_state)
    count = mgr.consume_retry_once_for(key, kind=kind, signature=signature)
    _flush_queue_manager(autonomy_state, mgr)
    return count


def _clear_manager_feedback_retries(
    autonomy_state: Mapping[str, Any],
    *,
    target_symbol: str,
    active_file: str,
) -> None:
    if not isinstance(autonomy_state, dict):
        return
    mgr = _queue_manager_from_state(autonomy_state)
    mgr.clear_retries_for(_queue_key(target_symbol, active_file))
    _flush_queue_manager(autonomy_state, mgr)


def _manager_feedback_retry_signature(
    kind: str,
    manager_check: Mapping[str, Any] | None,
) -> str:
    check = dict(manager_check or {})
    basis = {
        "kind": str(kind or ""),
        "local_cleanup_reason": _single_line(str(check.get("local_cleanup_reason", "") or ""), 300),
        "output": _single_line(str(check.get("output", "") or check.get("error", "") or ""), 500),
        "target": str(check.get("target", "") or ""),
        "command": str(check.get("command", "") or ""),
    }
    return json.dumps(basis, sort_keys=True, ensure_ascii=False)


def _manager_check_for_feedback_kind(
    active_file: str,
    target_symbol: str,
    manager_check: Mapping[str, Any],
) -> ManagerCheck:
    """Classify manager verification output into structured feedback categories (sorry/error/warning/open goals/future evidence). Scans diagnostic items and file output to determine what kind of theorem blocker is present and whether targets exist outside the assigned declaration."""
    entry = _find_declaration_entry(active_file, target_symbol)
    output = str(manager_check.get("output", "") or manager_check.get("error", "") or "")
    parsed = [
        dict(item)
        for item in list(manager_check.get("messages") or [])
        if isinstance(item, Mapping)
    ]
    seen = {
        (
            str(item.get("severity", "") or "").strip().lower(),
            item.get("line") if isinstance(item.get("line"), int) else None,
            str(item.get("message", "") or "").strip(),
        )
        for item in parsed
    }
    for item in diagnostic_items(output):
        signature = (
            str(item.get("severity", "") or "").strip().lower(),
            item.get("line") if isinstance(item.get("line"), int) else None,
            str(item.get("message", "") or "").strip(),
        )
        if signature not in seen:
            seen.add(signature)
            parsed.append(item)
    manager_verification_failed = (
        ("ok" in manager_check or "file_check_ok" in manager_check)
        and not bool(manager_check.get("ok"))
        and not bool(manager_check.get("file_check_ok"))
    )
    has_assigned_sorry = bool((entry and entry.get("has_sorry")) or manager_check.get("has_sorry"))
    has_assigned_error = False
    has_assigned_warning = False
    has_future_evidence = False
    has_assigned_open_goals = _goals_still_open(str(manager_check.get("goals", "") or ""))
    if any(
        str(blocker or "").strip()
        for blocker in list(manager_check.get("axiom_profile_blockers") or [])
    ):
        # A transitive axiom verdict is intrinsically scoped to the exact
        # declaration named by the manager check. It has no source line, so
        # treating it as future-file evidence can silently advance the queue.
        has_assigned_error = True

    local_cleanup = str(manager_check.get("local_cleanup_reason", "") or "").strip()
    lowered_cleanup = local_cleanup.lower()
    if lowered_cleanup:
        if "sorry" in lowered_cleanup:
            has_assigned_sorry = True
        elif any(token in lowered_cleanup for token in ("error", "unsolved", "failed")):
            has_assigned_error = True
        else:
            has_assigned_warning = True

    for item in parsed:
        severity = str(item.get("severity", "") or "").strip().lower()
        message = str(item.get("message", "") or "").strip().lower()
        line = item.get("line")
        if _line_in_declaration(entry, line):
            if severity == "error":
                has_assigned_error = True
            if "sorry" in message:
                has_assigned_sorry = True
            if severity == "warning" and not manager_verification_failed:
                has_assigned_warning = True
        elif entry and (severity in {"error", "warning"} or "sorry" in message):
            has_future_evidence = True

    if not entry and any(
        str(item.get("severity", "") or "").strip().lower() == "error" for item in parsed
    ):
        has_assigned_error = True

    lowered_output = output.lower()
    if (manager_verification_failed or not entry) and any(
        token in lowered_output
        for token in ("error:", "unsolved goals", "type mismatch", "failed to synthesize")
    ):
        has_assigned_error = True

    return ManagerCheck(
        has_assigned_sorry=has_assigned_sorry,
        has_assigned_error=has_assigned_error,
        has_assigned_open_goals=has_assigned_open_goals,
        has_assigned_warning=has_assigned_warning,
        has_future_evidence=has_future_evidence,
        verification_failed=manager_verification_failed,
        raw_messages=(output,),
    )


def _exact_assigned_target_axiom_gate_rejected(
    manager_check: Mapping[str, Any],
    *,
    target_symbol: str,
    active_file: str,
) -> bool:
    """Return whether an exact on-disk target check failed its axiom gate."""
    checked = dict(manager_check or {})
    nested = checked.get("incremental")
    exact = dict(nested) if isinstance(nested, Mapping) else checked
    action = (
        str(checked.get("action", "") or exact.get("action", "") or "")
        .strip()
        .lower()
        .replace("-", "_")
    )
    mode = str(checked.get("mode", "") or exact.get("mode", "") or "").strip().lower()
    scope = (
        str(checked.get("verification_scope", "") or exact.get("verification_scope", "") or "")
        .strip()
        .lower()
    )
    blockers = [
        str(blocker or "").strip()
        for blocker in list(checked.get("axiom_profile_blockers") or [])
        if str(blocker or "").strip()
    ]
    if (
        bool(checked.get("ok"))
        or not blockers
        or checked.get("replacement_matches_target") is True
        or exact.get("replacement_matches_target") is True
        or not (
            action == "check_target"
            or mode == "incremental_target"
            or scope in {"target", "target_exact"}
        )
    ):
        return False
    payload = dict(exact)
    payload.setdefault("target", checked.get("target", ""))
    payload.setdefault("file", checked.get("file", ""))
    return _incremental_result_matches_assignment(
        payload,
        target_symbol=target_symbol,
        active_file=active_file,
    )


def _manager_feedback_kind(
    active_file: str,
    target_symbol: str,
    manager_check: Mapping[str, Any],
) -> str:
    """Legacy string adapter for manager feedback.

    `Classification.FUTURE_ONLY` and `Classification.ACCEPT` both map to
    `""` here for backward compatibility. Consumers that need to distinguish
    those branches must call `_manager_check_for_feedback_kind` and
    `classify_check` directly.
    """
    check = _manager_check_for_feedback_kind(active_file, target_symbol, manager_check)
    classification = classify_check(check)
    if classification is Classification.HARD_BLOCKER:
        if check.has_assigned_sorry:
            return "sorry"
        return "error"
    if classification is Classification.WARNING_ONCE:
        return "warning"
    return ""


def _manager_retry_exhausted_message(
    *,
    target_symbol: str,
    active_file: str,
    kind: str,
    retry_limit: int,
    restore_result: Mapping[str, Any],
    manager_check: Mapping[str, Any],
) -> str:
    output = str(manager_check.get("output", "") or manager_check.get("error", "") or "").strip()
    restore_line = (
        "restored current declaration to the baseline `sorry` slice"
        if restore_result.get("restored")
        else f"baseline restore skipped: {restore_result.get('reason', 'not needed')}"
    )
    lines = [
        "[LEANFLOW-NATIVE LOCAL FEEDBACK WINDOW COMPLETE]",
        "",
        f"- declaration: {target_symbol or '[unknown]'}",
        f"- file: {active_file or '[unknown]'}",
        f"- blocker kind: {kind or 'unknown'}",
        f"- local feedback attempts used: {retry_limit}",
        f"- safe-state action: {restore_line}",
    ]
    if output:
        lines.append(f"- last manager feedback: {_single_line(output, 700)}")
    lines.append(
        "- next action: checkpoint this unresolved assignment and change proof route; "
        "the campaign remains active until manager verification clears it."
    )
    return "\n".join(lines).strip()


def _kernel_verified_helpers(target_symbol: str, active_file: str) -> list[str]:
    """Return the newest campaign-progress graph nodes in the assignment's file.

    Kernel-verified facts remain available to the prover, but the persistence
    coach must not reinforce facts that campaign accounting already classifies
    as circular, saturated finite-branch, or evidence-only. Graph nodes retain
    discovery order, which also lets the finite-branch classifier distinguish
    the first useful coverage cases from later repetitions before applying the
    bounded coach-context cap. Empty when plan-state is off.
    """
    if not plan_state_enabled():
        return []
    try:
        bp = plan_state.load_blueprint()
        assignment_id = plan_state.node_id_for(target_symbol, active_file)
        candidate_nodes = [
            node
            for node in bp.nodes
            if node.status == "proved"
            and node.id != assignment_id
            and node.name
            and _same_active_file(node.file, active_file)
            and assignment_id in mechanism_progress.parent_ids_for_node(bp, node.id)
        ]
        candidate_ids = {node.id for node in candidate_nodes}
        evidence_only_ids = mechanism_progress.evidence_only_node_ids(bp, candidate_ids)
        evidence_only_ids.update(
            conditional_helper_progress.assess_conditional_helpers(bp, candidate_ids)
        )
        previously_proved_ids: set[str] = set()
        for node in bp.nodes:
            if node.status != "proved":
                continue
            if node.id in candidate_ids:
                evidence_only_ids.update(
                    finite_branch_progress.assess_saturated_finite_branch_helpers(
                        bp,
                        {node.id},
                        previously_proved_node_ids=previously_proved_ids,
                    )
                )
            previously_proved_ids.add(node.id)
        return [
            node.name for node in reversed(candidate_nodes) if node.id not in evidence_only_ids
        ][:6]
    except Exception:
        return []


def _kernel_verified_evidence(target_symbol: str, active_file: str) -> list[str]:
    """Return newest proved helpers linked only as evidence to the assignment.

    These facts are safe for a coach to acknowledge, but their evidence edge
    cannot become proof progress or alter the queue manager's target verdict.
    """
    if not plan_state_enabled():
        return []
    try:
        bp = plan_state.load_blueprint()
        assignment_id = plan_state.node_id_for(target_symbol, active_file)
        evidence_node_ids = {
            edge.source
            for edge in bp.edges
            if edge.kind == "evidence" and edge.target == assignment_id
        }
        candidate_nodes = [
            node
            for node in bp.nodes
            if node.status == "proved"
            and node.id != assignment_id
            and node.id in evidence_node_ids
            and node.name
            and _same_active_file(node.file, active_file)
        ]
        evidence_only_ids = mechanism_progress.evidence_only_node_ids(
            bp,
            {node.id for node in candidate_nodes},
        )
        return [node.name for node in reversed(candidate_nodes) if node.id in evidence_only_ids][:6]
    except Exception:
        return []


def _maybe_manager_nudge(
    autonomy_state: Mapping[str, Any] | None,
    manager_check: Mapping[str, Any],
    *,
    target_symbol: str,
    active_file: str,
    result: Mapping[str, Any] | None = None,
) -> str:
    """Return one post-verdict persistence message for every rejected turn.

    The kernel gate has already judged the attempt, and the coach receives a
    copy of its evidence. Model calls are rate-limited per theorem/attempt;
    unusable, disabled, and dark-mode results all fall back to deterministic
    encouragement so rejected turns never end in silence.
    """
    if not isinstance(autonomy_state, dict):
        return ""

    try:
        mode = manager_nudge.nudge_mode()
    except Exception:
        # Mode resolution is only model-call policy. It must never suppress
        # the deterministic coach.
        logger.debug("manager nudge mode resolution failed", exc_info=True)
        mode = "off"

    seen_value = autonomy_state.get("manager_nudge_seen")
    if isinstance(seen_value, list):
        seen = seen_value
    else:
        seen = []
        autonomy_state["manager_nudge_seen"] = seen

    gate_verdict = _single_line(
        str(
            manager_check.get("feedback_kind", "")
            or manager_check.get("reason", "")
            or manager_check.get("output", "")
            or manager_check.get("error", "")
            or "kernel-rejected"
        ),
        160,
    )
    try:
        managed_cycle = max(0, int(autonomy_state.get("current_cycle", 0) or 0))
    except (TypeError, ValueError):
        managed_cycle = 0
    try:
        provider_turn_key = _failed_attempt_turn_key(autonomy_state, managed_cycle)
    except Exception:
        logger.debug("manager nudge provider-turn identity failed", exc_info=True)
        provider_turn_key = f"cycle-{managed_cycle}:turn-unavailable"

    report = struggle_signals.StruggleReport(
        signals=(),
        severity=struggle_signals.Severity.NONE,
    )
    latest_attempt: dict[str, Any] | None = None
    try:
        api_calls = max(0, int((result or {}).get("api_calls", 0) or 0))
    except (TypeError, ValueError):
        api_calls = 0
    packet: dict[str, Any] = {
        "target_symbol": target_symbol,
        "active_file": active_file,
        "attempts": [],
        "feedback_kind": str(manager_check.get("feedback_kind", "") or ""),
        "gate_output": str(manager_check.get("output", "") or manager_check.get("error", "") or ""),
        "api_calls": api_calls,
        "max_iterations": _read_int_env("AGENT_MAX_TURNS", 0, minimum=0),
        "proved_helpers": _kernel_verified_helpers(target_symbol, active_file),
        "verified_evidence": _kernel_verified_evidence(target_symbol, active_file),
        "assigned_route": str(
            autonomy_state.get("orchestrator_current_route", "") or "current route"
        ),
    }

    # State reconstruction enriches the coach but is not required to emit it.
    # A malformed or temporarily unavailable checkpoint therefore degrades to
    # deterministic encouragement instead of creating a silent rejected turn.
    try:
        mgr = _queue_manager_from_state(autonomy_state)
        key = _queue_key(target_symbol, active_file)
        attempt_count = mgr.attempt_count_for(key)
        attempt_entries = [dict(entry) for entry in mgr.attempt_entries_for(key)]
        latest_attempt = attempt_entries[-1] if attempt_entries else None
        latest_attempt_verdict = str((latest_attempt or {}).get("gate_verdict", "") or "").strip()
        if latest_attempt_verdict:
            gate_verdict = latest_attempt_verdict
        # Attempt counts advance only after a meaningful source edit. A later
        # no-edit prover turn can therefore receive the same kernel verdict at
        # the same attempt number. Bind coverage to the durable provider-turn
        # reservation so duplicate tool/final presentations within one turn
        # coalesce, while every subsequent rejected turn is coached once.
        # Repeated-error evidence comes from the failed-attempt REASONS: the
        # retry-signature store is deduplicated (identical repeats stay at 1),
        # so it cannot count occurrences.
        reason_counts: dict[str, int] = {}
        for entry in attempt_entries:
            reason = _single_line(str(entry.get("reason", "") or ""), 200).lower()
            if reason:
                reason_counts[reason] = reason_counts.get(reason, 0) + 1
        repeated = max(reason_counts.values(), default=0)
        final_text = _message_text((result or {}).get("final_response"))
        ctx = struggle_signals.StruggleContext(
            attempt_count=attempt_count,
            hard_retry_count=mgr.retry_count_for(key, "hard"),
            repeated_signature_count=repeated,
            search_progress=dict(autonomy_state.get("search_progress") or {}),
            stable_cycles=int(autonomy_state.get("continuation_stable_cycles", 0) or 0),
            blocked_runs=int(autonomy_state.get("continuation_blocked_runs", 0) or 0),
            api_calls=int((result or {}).get("api_calls", 0) or 0),
            max_iterations=_read_int_env("AGENT_MAX_TURNS", 0, minimum=0),
            blocker_summary=_extract_blocker_summary(final_text) if final_text else "",
        )
        report = struggle_signals.evaluate(ctx)
        packet.update(
            {
                "attempts": attempt_entries,
                "api_calls": ctx.api_calls,
                "max_iterations": ctx.max_iterations,
                "reroute_requested": report.severity is struggle_signals.Severity.REROUTE,
            }
        )
    except Exception:
        logger.debug("manager nudge state enrichment failed", exc_info=True)

    if report.severity is struggle_signals.Severity.REROUTE:
        try:
            event_scope = _orchestrator_event_scope(autonomy_state)
            epoch = int(autonomy_state.get("campaign_epoch", 0) or 0)
            watermark = orchestrator_event_watermark.publish_once(
                autonomy_state,
                scope=event_scope,
                source=f"manager-struggle-reroute:epoch-{epoch}",
                reason=(
                    f"struggle classifier requested a distinct route for {target_symbol}; "
                    "the persistence coach must not continue the exhausted route"
                ),
            )
            _record_activity(
                "manager-struggle-reroute-requested",
                f"Requested orchestration after persistent rejected work on {target_symbol}",
                target_symbol=target_symbol,
                active_file=active_file,
                epoch=epoch,
                severity=report.severity.value,
                signals=report.to_payload()["signals"],
                orchestrator_event_watermark=watermark,
                campaign_progress=False,
            )
        except Exception:
            logger.debug("manager struggle reroute publication failed", exc_info=True)

    # One provider conversation may submit several distinct temporary proof
    # candidates. Bind coverage to the durable failed-attempt identity and its
    # normalized gate verdict, while the provider-turn reservation continues
    # to coalesce checkpoint and final-report presentations of one rejection.
    rejection_identity = _manager_nudge_rejection_identity(latest_attempt, gate_verdict)
    rate_key = (
        f"{_queue_key(target_symbol, active_file).storage_key()}::"
        f"{provider_turn_key}::{rejection_identity}"
    )
    if rate_key in seen:
        return ""

    # The packet is a copy by construction: the LLM path never sees (or
    # mutates) the live manager_check. A model adapter exception is equivalent
    # to an unavailable response and deterministically falls back.
    model_nudge = None
    if mode in {"dark", "live"}:
        try:
            model_nudge = manager_nudge.request_nudge(report, dict(packet))
        except Exception:
            logger.debug("manager nudge model call failed", exc_info=True)
    fallback = manager_nudge.fallback_nudge(packet)
    if mode == "dark":
        selected = fallback
        recorded = model_nudge or fallback
        applied = False
    else:
        selected = model_nudge or fallback
        recorded = selected
        applied = mode == "live" and model_nudge is not None

    guidance = ["", "[PERSISTENCE COACH]", selected.message]
    if selected.progress_acknowledged:
        acknowledged = "; ".join(selected.progress_acknowledged[:3])
        guidance.append(f"Progress acknowledged: {acknowledged}")
    rendered_guidance = "\n".join(guidance)

    try:
        manager_nudge.record_nudge(
            recorded,
            report,
            applied=applied,
            mode=mode,
            target_symbol=target_symbol,
            active_file=active_file,
            coverage_key=rate_key,
            gate_verdict=gate_verdict,
            fallback_used=selected.raw_status == "fallback",
        )
    except Exception:
        # Third-party monkeypatches and future persistence adapters must not
        # defeat coverage even though record_nudge itself is non-raising.
        logger.debug("manager nudge recording failed", exc_info=True)

    # Mark coverage only after a usable message exists and recording has been
    # attempted. This avoids poisoning dedupe with a silent partial path.
    seen.append(rate_key)
    del seen[:-50]
    return rendered_guidance


def _source_revision_sha256(active_file: str) -> str:
    """Return the raw source revision used by exact-check reuse guards."""
    path = _resolve_project_path(active_file)
    return final_report_failure_reuse.source_sha256(path) if path is not None else ""


def _target_declaration_sha256(active_file: str, target_symbol: str) -> str:
    """Return the exact assigned declaration identity, including its proof body."""
    path = _resolve_project_path(active_file)
    if path is None:
        return ""
    try:
        source = path.read_text(encoding="utf-8")
    except OSError:
        return ""
    declaration = decomposition_provenance.declaration_slice(source, target_symbol)
    return declaration.declaration_sha256 if declaration is not None else ""


def _inject_exact_candidate_axiom_profile(
    function_name: str,
    args: Mapping[str, Any] | None,
    autonomy_state: Mapping[str, Any],
) -> None:
    """Require inline axiom evidence for a ready exact assigned-target check.

    Replacement checks elaborate a temporary declaration while the source on
    disk still contains the unresolved assignment.  Profiling the on-disk
    declaration after such a check therefore inspects the wrong proof.  Mutate
    the actual tool-call arguments so LeanProbe profiles the replacement in the
    same temporary environment that checks it.  A sorry-free on-disk target
    receives the same one-shot treatment because private declarations cannot
    reliably be recovered by a later name-based ``#print axioms`` fallback.
    """
    if (
        function_name != "lean_incremental_check"
        or not isinstance(args, dict)
        or not _axiom_profile_check_enabled()
    ):
        return
    action = str(args.get("action", "check_target") or "check_target")
    if action.strip().lower().replace("-", "_") != "check_target":
        return
    assignment = dict(autonomy_state.get("current_queue_assignment") or {})
    target_symbol = str(assignment.get("target_symbol", "") or "").strip()
    active_file = str(assignment.get("active_file", "") or "").strip()
    requested_target = str(
        args.get("theorem_id", "") or args.get("target_symbol", "") or ""
    ).strip()
    requested_file = str(args.get("file_path", "") or args.get("active_file", "") or "").strip()
    if not _incremental_result_matches_assignment(
        {"target": requested_target, "file": requested_file},
        target_symbol=target_symbol,
        active_file=active_file,
    ):
        return
    replacement = str(args.get("replacement", "") or "").strip()
    if not replacement:
        entry = _find_declaration_entry(active_file, target_symbol)
        source = str((entry or {}).get("text", "") or "")
        if not source or _text_has_sorry(source):
            return
    args["include_axiom_profile"] = True


def _capture_operational_exact_candidate(
    autonomy_state: Mapping[str, Any] | None,
    args: Mapping[str, Any] | None,
    manager_check: Mapping[str, Any] | None,
    *,
    target_symbol: str,
    active_file: str,
) -> bool:
    """Retain a kernel-valid exact candidate only when its axiom gate is unavailable."""
    if not isinstance(autonomy_state, dict) or not _axiom_profile_check_enabled():
        return False
    arguments = dict(args or {})
    check = dict(manager_check or {})
    action = str(arguments.get("action", "check_target") or "check_target")
    requested_target = str(
        arguments.get("theorem_id", "") or arguments.get("target_symbol", "") or ""
    ).strip()
    requested_file = str(
        arguments.get("file_path", "") or arguments.get("active_file", "") or ""
    ).strip()
    replacement = str(arguments.get("replacement", "") or "")
    if (
        action.strip().lower().replace("-", "_") != "check_target"
        or requested_target != target_symbol
        or not _same_active_file(requested_file, active_file)
        or not replacement.strip()
        or check.get("success") is not True
        or check.get("ok") is not True
        or check.get("valid_without_sorry") is not True
        or check.get("has_errors") is True
        or check.get("has_sorry") is True
        or check.get("replacement_matches_target") is not True
        or str(check.get("verification_scope", "") or "") != "target_candidate"
        or not _incremental_result_matches_assignment(
            check,
            target_symbol=target_symbol,
            active_file=active_file,
        )
    ):
        return False
    gated = _enforce_manager_axiom_profile(
        active_file,
        target_symbol,
        check,
        required=True,
    )
    blockers = {
        str(value or "").strip().lower()
        for value in list(gated.get("axiom_profile_blockers") or [])
    }
    if gated.get("ok") is not False or blockers != {helper_gate_retry.AXIOM_PROFILE_UNAVAILABLE}:
        return False
    retained = verification_candidate_replay.capture_operational_candidate(
        target_symbol=target_symbol,
        active_file=active_file,
        replacement=replacement,
        campaign_id=str(autonomy_state.get("campaign_id", "") or ""),
        process_id=os.getpid(),
        process_fingerprint=verification_candidate_replay.current_process_fingerprint(),
        backend=str(check.get("backend", "") or ""),
    )
    if retained is None:
        return False
    _record_activity(
        "queue-exact-candidate-retained",
        f"Retained a bounded exact candidate for verifier replay on {target_symbol}",
        target_symbol=target_symbol,
        active_file=active_file,
        candidate_id=str(retained.get("candidate_id", "") or ""),
        replacement_sha256=str(retained.get("replacement_sha256", "") or ""),
        candidate_chars=len(replacement),
        reason="candidate-bound axiom profile unavailable",
        resumable=True,
    )
    return True


def _capture_partial_exact_candidate(
    autonomy_state: Mapping[str, Any] | None,
    args: Mapping[str, Any] | None,
    manager_check: Mapping[str, Any] | None,
    *,
    target_symbol: str,
    active_file: str,
) -> bool:
    """Checkpoint a better placeholder-free target candidate with Lean errors."""
    arguments = dict(args or {})
    replacement = str(arguments.get("replacement", "") or "")
    retained = target_candidate_checkpoint.capture_checked_candidate(
        target_symbol=target_symbol,
        active_file=active_file,
        replacement=replacement,
        check=dict(manager_check or {}),
        campaign_id=(
            str(autonomy_state.get("campaign_id", "") or "")
            if isinstance(autonomy_state, Mapping)
            else ""
        ),
    )
    if retained is None:
        return False
    _record_activity(
        "queue-partial-target-candidate-checkpointed",
        f"Checkpointed the best checked partial candidate for {target_symbol}",
        target_symbol=target_symbol,
        active_file=active_file,
        candidate_id=str(retained.get("candidate_id", "") or ""),
        replacement_sha256=str(retained.get("replacement_sha256", "") or ""),
        candidate_chars=len(replacement),
        error_count=int(retained.get("error_count", 0) or 0),
        first_error_line=int(retained.get("first_error_line", 0) or 0),
        resumable=True,
        authoritative=False,
    )
    return True


def _replay_exact_candidate_if_due(
    autonomy_state: dict[str, Any],
    *,
    target_symbol: str,
    active_file: str,
) -> dict[str, Any] | None:
    """Recheck one retained candidate once per process and verifier contract."""
    candidate = verification_candidate_replay.matching_candidate(
        target_symbol=target_symbol,
        active_file=active_file,
    )
    if candidate is None:
        return None
    mgr = _queue_manager_from_state(autonomy_state)
    outcome = mgr.outcome_for(_queue_key(target_symbol, active_file))
    if outcome is not None and str(outcome.status or "").strip().lower() in {
        "solved",
        "disproved",
    }:
        verification_candidate_replay.retire_candidate(
            target_symbol=target_symbol,
            active_file=active_file,
        )
        return None
    process_fingerprint = verification_candidate_replay.current_process_fingerprint()
    if not verification_candidate_replay.replay_due(
        candidate,
        process_id=os.getpid(),
        process_fingerprint=process_fingerprint,
    ):
        return candidate

    candidate_id = str(candidate.get("candidate_id", "") or "")
    replacement = str(candidate.get("replacement", "") or "")
    check: dict[str, Any]
    try:
        with verification_transaction.parent_lean_verification_transaction(active_file):
            raw = lean_incremental_check(
                action="check_target",
                file_path=active_file,
                theorem_id=target_symbol,
                replacement=replacement,
                cwd=_project_root(),
                include_tactics=False,
                include_axiom_profile=True,
                timeout_s=_manager_incremental_check_timeout_s(),
            )
        check = _enforce_manager_axiom_profile(
            active_file,
            target_symbol,
            dict(raw or {}),
            required=True,
        )
    except Exception as exc:
        detail = _single_line(str(exc), 500)
        verification_candidate_replay.mark_replay(
            candidate_id,
            status="operationally_unavailable",
            process_id=os.getpid(),
            process_fingerprint=process_fingerprint,
            detail=detail,
        )
        _record_activity(
            "queue-exact-candidate-replay-deferred",
            f"Exact candidate replay remained operationally unavailable for {target_symbol}",
            target_symbol=target_symbol,
            active_file=active_file,
            candidate_id=candidate_id,
            reason=detail,
            resumable=True,
        )
        return verification_candidate_replay.matching_candidate(
            target_symbol=target_symbol,
            active_file=active_file,
        )

    blockers = [
        str(value or "").strip()
        for value in list(check.get("axiom_profile_blockers") or [])
        if str(value or "").strip()
    ]
    fully_valid = bool(
        check.get("success") is True
        and check.get("ok") is True
        and check.get("valid_without_sorry") is True
        and check.get("has_errors") is not True
        and check.get("has_sorry") is not True
        and check.get("replacement_matches_target") is True
        and str(check.get("verification_scope", "") or "") == "target_candidate"
        and check.get("axiom_profile_checked") is True
        and "axiom_profile_blockers" in check
        and not blockers
        and _incremental_result_matches_assignment(
            check,
            target_symbol=target_symbol,
            active_file=active_file,
        )
    )
    if fully_valid:
        updated = verification_candidate_replay.mark_replay(
            candidate_id,
            status="ready_to_commit",
            process_id=os.getpid(),
            process_fingerprint=process_fingerprint,
            detail="current exact-target kernel and axiom gates passed",
        )
        _record_activity(
            "queue-exact-candidate-replay-accepted",
            f"Revalidated retained exact candidate for {target_symbol}",
            target_symbol=target_symbol,
            active_file=active_file,
            candidate_id=candidate_id,
            replacement_sha256=str(candidate.get("replacement_sha256", "") or ""),
            candidate_chars=len(replacement),
            authoritative=False,
            commit_required=True,
        )
        return updated

    verification = _verification_record_from_check(
        active_file,
        target_symbol,
        check,
        "lean_incremental_check",
    )
    if not check or helper_gate_retry.gate_temporarily_unavailable(check, verification):
        detail = _single_line(
            str(check.get("output", "") or check.get("error", "") or "gate unavailable"),
            500,
        )
        verification_candidate_replay.mark_replay(
            candidate_id,
            status="operationally_unavailable",
            process_id=os.getpid(),
            process_fingerprint=process_fingerprint,
            detail=detail,
        )
        _record_activity(
            "queue-exact-candidate-replay-deferred",
            f"Exact candidate replay remained operationally unavailable for {target_symbol}",
            target_symbol=target_symbol,
            active_file=active_file,
            candidate_id=candidate_id,
            reason=detail,
            resumable=True,
        )
        return verification_candidate_replay.matching_candidate(
            target_symbol=target_symbol,
            active_file=active_file,
        )

    detail = _single_line(
        str(check.get("output", "") or check.get("error", "") or "current gate rejected"),
        500,
    )
    verification_candidate_replay.mark_replay(
        candidate_id,
        status="mathematically_rejected",
        process_id=os.getpid(),
        process_fingerprint=process_fingerprint,
        detail=detail,
    )
    _record_activity(
        "queue-exact-candidate-replay-retired",
        f"Retired a retained candidate rejected by the current Lean gate for {target_symbol}",
        target_symbol=target_symbol,
        active_file=active_file,
        candidate_id=candidate_id,
        reason=detail,
        axiom_profile_blockers=blockers,
    )
    return None


def _capture_exact_check_source_snapshot(
    agent: Any,
    function_name: str,
    args: Mapping[str, Any] | None,
) -> None:
    """Capture the source before one exact on-disk target check.

    The post-tool hook can reuse a failed check at final-report review only
    when the bytes are unchanged both across the tool and after the provider
    finishes. Replacement checks are deliberately excluded because they do
    not inspect the declaration committed on disk.
    """
    with contextlib.suppress(Exception):
        delattr(agent, _EXACT_CHECK_SOURCE_SNAPSHOT_ATTR)
    if function_name not in {"lean_incremental_check", "lean_verify"}:
        return
    arguments = dict(args or {})
    if function_name == "lean_incremental_check":
        action = str(arguments.get("action", "check_target") or "check_target")
        action = action.strip().lower().replace("-", "_")
        if action != "check_target" or str(arguments.get("replacement", "") or "").strip():
            return
    elif str(arguments.get("mode", "") or "").strip().lower() != "file_exact":
        return
    autonomy_state = getattr(agent, "_managed_autonomy_state", None)
    if not isinstance(autonomy_state, dict):
        return
    assignment = dict(autonomy_state.get("current_queue_assignment") or {})
    target_symbol = str(assignment.get("target_symbol", "") or "").strip()
    active_file = str(assignment.get("active_file", "") or "").strip()
    requested_target = target_symbol
    requested_file = str(arguments.get("target", "") or active_file).strip()
    if function_name == "lean_incremental_check":
        requested_target = str(
            arguments.get("theorem_id", "") or arguments.get("target_symbol", "") or target_symbol
        ).strip()
        requested_file = str(
            arguments.get("file_path", "") or arguments.get("active_file", "") or active_file
        ).strip()
    if requested_target != target_symbol or not _same_active_file(requested_file, active_file):
        return
    snapshot = _exact_check_source_snapshot_for_assignment(
        autonomy_state,
        target_symbol=target_symbol,
        active_file=active_file,
    )
    if not snapshot:
        return
    setattr(agent, _EXACT_CHECK_SOURCE_SNAPSHOT_ATTR, snapshot)


def _exact_check_source_snapshot_for_assignment(
    autonomy_state: Mapping[str, Any],
    *,
    target_symbol: str,
    active_file: str,
) -> dict[str, Any]:
    """Return a source identity for an imminent exact assignment gate."""
    scope = _queue_key(target_symbol, active_file)
    source_sha256 = _source_revision_sha256(active_file)
    if not scope.is_valid() or not source_sha256:
        return {}
    identity = final_report_failure_reuse.PreCheckIdentity(
        assignment_scope=scope.storage_key(),
        source_sha256=source_sha256,
        provider_turn_key=_failed_attempt_turn_key(
            autonomy_state,
            int(autonomy_state.get("current_cycle", 0) or 0),
        ),
    )
    return identity.to_mapping(
        target_symbol=target_symbol,
        active_file=active_file,
    )


def _take_exact_check_source_snapshot(agent: Any, function_name: str) -> dict[str, Any]:
    """Take the matching pre-tool source snapshot exactly once."""
    if function_name not in {"lean_incremental_check", "lean_verify"}:
        return {}
    snapshot = dict(getattr(agent, _EXACT_CHECK_SOURCE_SNAPSHOT_ATTR, None) or {})
    with contextlib.suppress(Exception):
        delattr(agent, _EXACT_CHECK_SOURCE_SNAPSHOT_ATTR)
    return snapshot


def _exact_source_failure_is_reusable(
    active_file: str,
    target_symbol: str,
    manager_check: Mapping[str, Any],
) -> bool:
    """Return whether an exact check is authoritative negative proof evidence."""
    checked = dict(manager_check or {})
    payload = final_report_failure_reuse.completed_on_disk_failure_payload(checked)
    if payload is None or not _incremental_result_matches_assignment(
        payload,
        target_symbol=target_symbol,
        active_file=active_file,
    ):
        return False
    verification = _verification_record_from_check(
        active_file,
        target_symbol,
        checked,
        "lean_incremental_check",
    )
    if helper_gate_retry.gate_temporarily_unavailable(checked, verification):
        return False
    return _manager_feedback_kind(active_file, target_symbol, checked) in {"error", "sorry"}


def _remember_final_report_failure_check(
    autonomy_state: Mapping[str, Any] | None,
    *,
    active_file: str,
    target_symbol: str,
    manager_check: Mapping[str, Any],
    manager_tool: str,
    source_snapshot: Mapping[str, Any] | None,
) -> None:
    """Remember one unchanged exact-target rejection for this provider turn."""
    if not isinstance(autonomy_state, dict):
        return
    if not source_snapshot:
        # Any newer theorem gate supersedes a previously cached rejection.
        # Without its own pre-tool identity it cannot replace that cache.
        autonomy_state.pop(_FINAL_REPORT_FAILURE_CHECK_KEY, None)
        return
    scope = _queue_key(target_symbol, active_file)
    if not scope.is_valid():
        return
    precheck = final_report_failure_reuse.PreCheckIdentity.from_mapping(source_snapshot)
    identity = final_report_failure_reuse.FailureIdentity(
        assignment_scope=scope.storage_key(),
        source_sha256=_source_revision_sha256(active_file),
        declaration_sha256=_failed_attempt_declaration_hash(active_file, target_symbol, None),
        provider_turn_key=_failed_attempt_turn_key(
            autonomy_state,
            int(autonomy_state.get("current_cycle", 0) or 0),
        ),
    )
    final_report_failure_reuse.remember(
        autonomy_state,
        precheck=precheck,
        identity=identity,
        manager_check=manager_check,
        manager_tool=manager_tool,
        reusable=_exact_source_failure_is_reusable(active_file, target_symbol, manager_check),
    )


def _take_final_report_failure_check(
    autonomy_state: Mapping[str, Any],
    *,
    active_file: str,
    target_symbol: str,
) -> tuple[dict[str, Any], str] | None:
    """Take a same-turn rejection only while its exact source identity matches."""
    if not isinstance(autonomy_state, dict):
        return None
    scope = _queue_key(target_symbol, active_file)
    if not scope.is_valid():
        autonomy_state.pop(_FINAL_REPORT_FAILURE_CHECK_KEY, None)
        return None
    reused = final_report_failure_reuse.take(
        autonomy_state,
        identity=final_report_failure_reuse.FailureIdentity(
            assignment_scope=scope.storage_key(),
            source_sha256=_source_revision_sha256(active_file),
            declaration_sha256=_failed_attempt_declaration_hash(active_file, target_symbol, None),
            provider_turn_key=_failed_attempt_turn_key(
                autonomy_state,
                int(autonomy_state.get("current_cycle", 0) or 0),
            ),
        ),
    )
    if reused is None:
        return None
    check, manager_tool = reused
    if not _exact_source_failure_is_reusable(active_file, target_symbol, check):
        return None
    check["verification_reused"] = True
    check["verification_reuse_reason"] = (
        "same provider turn, exact assignment, and unchanged source SHA-256"
    )
    return check, manager_tool


def _verified_counterexample_evidence_for_assignment(
    *,
    target_symbol: str,
    active_file: str,
) -> tuple[Mapping[str, Any], ...]:
    """Load exact-target counterexample helpers backed by parent kernel truth."""
    try:
        context = orchestrator_floor.build_route_context(
            trigger="event",
            autonomy_state={
                "current_queue_assignment": {
                    "target_symbol": target_symbol,
                    "active_file": active_file,
                }
            },
            blueprint=plan_state.load_blueprint(),
            summary=plan_state.load_summary(),
        )
    except Exception:
        logger.debug("counterexample route evidence load failed", exc_info=True)
        return ()
    return context.verified_counterexample_evidence


def _source_placeholder_final_report_check(
    active_file: str,
    target_symbol: str,
) -> tuple[dict[str, Any], str] | None:
    """Reject an open source placeholder without starting a Lean transaction.

    This is rejection-only evidence: a literal ``sorry`` or ``admit`` in the
    assigned declaration proves that the source is unresolved, but its absence
    proves nothing. Comments and strings are stripped before token inspection.
    """
    entry = _find_declaration_entry(active_file, target_symbol)
    if not entry:
        return None
    declaration = _strip_lean_comments_and_strings(str(entry.get("text", "") or ""))
    placeholder_match = re.search(r"\b(?:sorry|admit)\b", declaration)
    if placeholder_match is None:
        return None
    placeholder = placeholder_match.group(0)
    declaration_line = int(entry.get("line", 0) or 0)
    check = {
        "success": True,
        "ok": False,
        "valid_without_sorry": False,
        "has_errors": False,
        "has_sorry": True,
        "sorry": 1,
        "mode": "source_placeholder_gate",
        "target": target_symbol,
        "command": "deterministic assigned-declaration placeholder scan",
        "output": (
            f"Assigned declaration `{target_symbol}` still contains the unresolved "
            f"`{placeholder}` placeholder (declaration starts at line {declaration_line})."
        ),
        "source_placeholder": placeholder,
        "source_declaration_line": declaration_line,
        "source_sha256": _source_revision_sha256(active_file),
        "elapsed_s": 0.0,
    }
    _record_activity(
        "manager-source-placeholder-gate",
        f"Rejected unresolved final report for {target_symbol} from source truth",
        target_symbol=target_symbol,
        active_file=active_file,
        placeholder=placeholder,
        declaration_line=declaration_line,
        source_sha256=check["source_sha256"],
        kernel_transaction_started=False,
    )
    return check, "source_placeholder_gate"


def _review_agent_final_report(
    result: Mapping[str, Any],
    autonomy_state: Mapping[str, Any],
) -> dict[str, Any]:
    """Verify every completed queue turn and continue all unresolved work."""
    updated = dict(result)
    if not _single_queue_item_turn_enabled():
        return updated
    if updated.get("interrupted") or not updated.get("completed"):
        return updated
    assignment = dict(autonomy_state.get("current_queue_assignment") or {})
    target_symbol = str(assignment.get("target_symbol", "") or "").strip()
    active_file = str(assignment.get("active_file", "") or "").strip()
    if not target_symbol or not active_file:
        return updated
    messages = list(updated.get("messages") or [])
    final_text = str(updated.get("final_response", "") or "").strip() or _latest_assistant_content(
        messages
    )
    agent_claimed_success = _final_report_claims_queue_success(final_text, target_symbol)
    requested_route = orchestrator_floor.requested_route_from_text(final_text)
    requested_route_reason = orchestrator_floor.bounded_requested_route_reason(
        final_text,
        requested_route,
    )
    construction_turn_guidance = ""

    reused = _take_final_report_failure_check(
        autonomy_state,
        active_file=active_file,
        target_symbol=target_symbol,
    )
    if reused is None:
        reused = _same_revision_timeout_backpressure_check(
            autonomy_state,
            target_symbol=target_symbol,
            active_file=active_file,
        )
        if reused is not None:
            _record_activity(
                "manager-verification-timeout-backpressured",
                f"Skipped unchanged exact-verification timeout replay for {target_symbol}",
                target_symbol=target_symbol,
                active_file=active_file,
                purpose="target-final-report",
                source_sha256=_source_revision_sha256(active_file),
                campaign_progress=False,
            )
    if reused is None:
        source_placeholder_check = (
            None
            if agent_claimed_success
            else _source_placeholder_final_report_check(active_file, target_symbol)
        )
        if source_placeholder_check is None:
            manager_check, manager_tool = _manager_check_queue_item_transaction(
                active_file,
                target_symbol,
                purpose="target-final-report",
            )
            _remember_same_revision_verification_timeout(
                autonomy_state,
                target_symbol=target_symbol,
                active_file=active_file,
                manager_check=manager_check,
            )
        else:
            manager_check, manager_tool = source_placeholder_check
    else:
        manager_check, manager_tool = reused
        _record_activity(
            "manager-verification-reused",
            f"Reused unchanged exact-target verification result for {target_symbol}",
            target_symbol=target_symbol,
            active_file=active_file,
            purpose="target-final-report",
            source_sha256=_source_revision_sha256(active_file),
            manager_tool=manager_tool,
        )
    file_check_ok = bool(manager_check.get("ok"))
    manager_check = dict(manager_check)
    manager_check["file_check_ok"] = file_check_ok
    manager_check["manager_tool"] = manager_tool
    manager_check["agent_claimed_success"] = agent_claimed_success
    if bool(manager_check.get("ok")):
        # Keep final-report cleanup policy aligned with post-patch checks:
        # only the targeted manager check can grant the focused cleanup turn.
        cleanup_reason = _declaration_diagnostic_feedback_reason(
            active_file,
            target_symbol,
            str(manager_check.get("output", "") or ""),
            str(manager_check.get("error", "") or ""),
            structured_items=manager_check.get("messages") or (),
        )
        if cleanup_reason:
            manager_check["ok"] = False
            manager_check["local_cleanup_reason"] = cleanup_reason
            manager_check["diagnostics"] = _single_line(
                str(manager_check.get("output", "") or manager_check.get("error", "") or ""),
                700,
            )
    # Persist only the final verdict. A preliminary Lean-clean result must not
    # survive when the transitive axiom gate rejects the declaration.
    manager_check = _enforce_manager_axiom_profile(active_file, target_symbol, manager_check)
    axiom_blockers = list(manager_check.get("axiom_violation") or [])
    verification_record = _record_manager_verification(
        autonomy_state,
        active_file,
        target_symbol,
        manager_check,
        manager_tool,
    )
    manager_check["last_verification"] = verification_record
    # Snapshot the pre-gate retry counters and the
    # pre-mutation evidence (the exhausted path restores the file below, which
    # would flip the declaration's sorry state under the evidence's feet).
    # Shadow work never perturbs the gate: failures only disable the shadow.
    shadow_state: dict[str, Any] | None = None
    shadow_evidence: ManagerCheck | None = None
    # The decide() evidence is needed by the shadow AND by the authority flip
    # (which may run without the shadow). Capture it here, before the exhausted
    # path restores the file underneath it. The retry snapshot is shadow-only.
    if (_queue_decide_shadow_enabled() or _queue_decide_authority_enabled()) and isinstance(
        autonomy_state, dict
    ):
        try:
            shadow_evidence = _manager_check_for_feedback_kind(
                active_file, target_symbol, dict(manager_check)
            )
            if _queue_decide_shadow_enabled():
                shadow_state = {
                    key: copy.deepcopy(autonomy_state[key])
                    for key in TheoremQueueManager.OWNED_AUTONOMY_KEYS
                    if key in autonomy_state
                }
        except Exception:
            logger.debug("queue-decide evidence snapshot failed", exc_info=True)
            shadow_state = None
            shadow_evidence = None
    feedback_kind = _manager_feedback_kind(active_file, target_symbol, manager_check)
    if axiom_blockers and not feedback_kind:
        # A disallowed axiom dependency is a hard blocker even when the file has no error/sorry.
        feedback_kind = "error"
    if feedback_kind:
        manager_check["feedback_kind"] = feedback_kind
    retry_count = 0
    retry_limit = 0
    authority_decision = None
    if _queue_decide_authority_enabled() and shadow_evidence is not None:
        # Authority flip: decide() owns the FINAL_REPORT verdict. decide() is
        # pure, so a failure here falls back to the legacy engine below with
        # no half-applied mutation.
        try:
            authority_ctx = DecisionContext(
                source=DecisionSource.FINAL_REPORT,
                check=shadow_evidence,
                signature=_manager_feedback_retry_signature(feedback_kind, manager_check),
                axiom_blockers=tuple(axiom_blockers),
            )
            authority_mgr = _queue_manager_from_state(autonomy_state)
            authority_decision = authority_mgr.decide(authority_ctx)
        except Exception:
            logger.debug(
                "queue-decide authority (final-report) failed; using legacy", exc_info=True
            )
            authority_decision = None
    if authority_decision is not None:
        # Drive the SAME locals + manager_check keys the shared render block
        # reads, but from the Decision. The retry count is read PRE-consume
        # (matching the legacy read-before-increment) so rendering is identical;
        # the shared render block below performs the actual consume/clear.
        retry_limit = authority_decision.retry_limit
        if retry_limit:
            retry_count = _manager_feedback_retry_count(
                autonomy_state,
                target_symbol=target_symbol,
                active_file=active_file,
                kind=feedback_kind,
            )
            manager_check["feedback_retry_count"] = retry_count
            manager_check["feedback_retry_limit"] = retry_limit
        manager_check["ok"] = authority_decision.action == "advance_queue"
        if authority_decision.accepted_after_warning_limit:
            manager_check["accepted_after_warning_retry_limit"] = True
            manager_check["acceptance_note"] = (
                "accepted after one warning-only cleanup opportunity; remaining warnings are not allowed to stall the queue"
            )
        elif authority_decision.restore_baseline:
            restore_result = _restore_queue_assignment_to_baseline_sorry(autonomy_state, {})
            _clear_manager_feedback_retries(
                autonomy_state,
                target_symbol=target_symbol,
                active_file=active_file,
            )
            manager_check["feedback_retry_window_reset"] = True
            if restore_result.get("restored"):
                restore_result = dict(restore_result)
                restore_result["reason"] = (
                    "reverted current declaration to its baseline `sorry` slice after the local feedback window completed"
                )
            manager_check["retry_exhausted"] = True
            manager_check["restore"] = restore_result
            exhausted_text = _manager_retry_exhausted_message(
                target_symbol=target_symbol,
                active_file=active_file,
                kind=feedback_kind,
                retry_limit=retry_limit,
                restore_result=restore_result,
                manager_check=manager_check,
            )
            exhausted_guidance = _maybe_manager_nudge(
                autonomy_state,
                manager_check,
                target_symbol=target_symbol,
                active_file=active_file,
                result=updated,
            )
            if exhausted_guidance:
                exhausted_text = f"{exhausted_text}\n{exhausted_guidance}"
            messages.append({"role": "user", "content": exhausted_text})
            updated["messages"] = messages
            updated["completed"] = False
            updated["exit_reason"] = "manager_retry_exhausted"
            updated["error"] = (
                "Local feedback window complete for unresolved theorem; "
                "safe state checkpointed for a route change"
            )
        # NOTE: the retry side effects stay on the proven legacy helpers keyed
        # by explicit target/file — the shared render block below consumes via
        # _increment on the reject path and clears via _clear when ok. decide()
        # is the VERDICT oracle only; apply_decision (which keys off the
        # manager's _current and clears on every advance) is intentionally not
        # used, so the counters advance exactly as legacy.
    elif not bool(manager_check.get("ok")):
        if feedback_kind == "warning":
            retry_limit = MANAGER_WARNING_RETRY_LIMIT
        elif feedback_kind in {"error", "sorry"}:
            retry_limit = MANAGER_HARD_RETRY_LIMIT
        if retry_limit:
            retry_count = _manager_feedback_retry_count(
                autonomy_state,
                target_symbol=target_symbol,
                active_file=active_file,
                kind=feedback_kind,
            )
            manager_check["feedback_retry_count"] = retry_count
            manager_check["feedback_retry_limit"] = retry_limit
            if feedback_kind == "warning" and retry_count >= retry_limit:
                manager_check["ok"] = True
                manager_check["accepted_after_warning_retry_limit"] = True
                manager_check["acceptance_note"] = (
                    "accepted after one warning-only cleanup opportunity; remaining warnings are not allowed to stall the queue"
                )
            elif feedback_kind in {"error", "sorry"} and retry_count >= retry_limit:
                restore_result = _restore_queue_assignment_to_baseline_sorry(autonomy_state, {})
                _clear_manager_feedback_retries(
                    autonomy_state,
                    target_symbol=target_symbol,
                    active_file=active_file,
                )
                manager_check["feedback_retry_window_reset"] = True
                if restore_result.get("restored"):
                    restore_result = dict(restore_result)
                    restore_result["reason"] = (
                        "reverted current declaration to its baseline `sorry` slice after the local feedback window completed"
                    )
                manager_check["retry_exhausted"] = True
                manager_check["restore"] = restore_result
                exhausted_text = _manager_retry_exhausted_message(
                    target_symbol=target_symbol,
                    active_file=active_file,
                    kind=feedback_kind,
                    retry_limit=retry_limit,
                    restore_result=restore_result,
                    manager_check=manager_check,
                )
                exhausted_guidance = _maybe_manager_nudge(
                    autonomy_state,
                    manager_check,
                    target_symbol=target_symbol,
                    active_file=active_file,
                    result=updated,
                )
                if exhausted_guidance:
                    exhausted_text = f"{exhausted_text}\n{exhausted_guidance}"
                messages.append({"role": "user", "content": exhausted_text})
                updated["messages"] = messages
                updated["completed"] = False
                updated["exit_reason"] = "manager_retry_exhausted"
                updated["error"] = (
                    "Local feedback window complete for unresolved theorem; "
                    "safe state checkpointed for a route change"
                )
    ok = bool(manager_check.get("ok"))
    if not ok and not requested_route:
        counterexample_evidence = _verified_counterexample_evidence_for_assignment(
            target_symbol=target_symbol,
            active_file=active_file,
        )
        requested_route = orchestrator_floor.evidence_supported_negate_request_from_text(
            final_text,
            counterexample_evidence,
        )
        if requested_route:
            # Do not persist the model's free-form blocker as route authority.
            # The reason names only independently verified graph evidence.
            requested_route_reason = orchestrator_floor.verified_counterexample_route_reason(
                counterexample_evidence
            )
    if isinstance(autonomy_state, dict):
        if ok:
            autonomy_state.pop(
                search_synthesis_admission.CONSTRUCTION_DEBT_STATE_KEY,
                None,
            )
        else:
            try:
                construction_serial = int(
                    autonomy_state.get(
                        search_synthesis_admission.CONSTRUCTION_ATTEMPT_SERIAL_KEY,
                        0,
                    )
                    or 0
                )
            except (TypeError, ValueError):
                construction_serial = 0
            debt_tracker, construction_decision = (
                search_synthesis_admission.observe_unresolved_construction_turn(
                    autonomy_state.get(search_synthesis_admission.CONSTRUCTION_DEBT_STATE_KEY),
                    target_symbol=target_symbol,
                    active_file=active_file,
                    source_revision_sha256=_source_revision_sha256(active_file),
                    construction_attempt_serial=construction_serial,
                    requested_route=requested_route,
                    limit=_construction_no_progress_turn_limit(),
                )
            )
            autonomy_state[search_synthesis_admission.CONSTRUCTION_DEBT_STATE_KEY] = debt_tracker
            manager_check["construction_no_progress_turns"] = construction_decision.count
            manager_check["construction_required"] = construction_decision.require_construction
            if construction_decision.reset_reason:
                _record_activity(
                    "construction-turn-debt-reset",
                    f"Reset construction debt for {target_symbol}: {construction_decision.reset_reason}",
                    target_symbol=target_symbol,
                    active_file=active_file,
                    reason=construction_decision.reset_reason,
                    construction_attempt_serial=construction_serial,
                    source_sha256=str(debt_tracker.get("source_revision_sha256", "") or ""),
                    campaign_progress=construction_decision.reset_reason
                    in {"source-changed", "construction-attempted"},
                )
            if construction_decision.require_construction:
                suppressed_route = requested_route
                requested_route = ""
                requested_route_reason = ""
                construction_turn_guidance = _construction_turn_debt_handoff_block(
                    {"target_symbol": target_symbol, "active_file": active_file},
                    autonomy_state,
                )
                _record_activity(
                    "construction-turn-debt-activated",
                    f"Required a concrete Lean attempt for unchanged target {target_symbol}",
                    target_symbol=target_symbol,
                    active_file=active_file,
                    no_progress_turns=construction_decision.count,
                    suppressed_route=suppressed_route,
                    routes=list(debt_tracker.get("routes") or []),
                    source_sha256=str(debt_tracker.get("source_revision_sha256", "") or ""),
                    campaign_progress=False,
                )
    if isinstance(autonomy_state, dict):
        target_signature = research_helper_candidate_priority.target_signature_sha256(
            active_file,
            target_symbol,
        )
        target_declaration = _target_declaration_sha256(active_file, target_symbol)
        prior_planner_obstacle = dict(
            autonomy_state.get(route_execution.PLANNER_TERMINAL_OBSTACLE_STATE_KEY) or {}
        )
        planner_obstacle_cleared = (
            route_execution.clear_planner_terminal_obstacle_after_target_change(
                autonomy_state,
                target_symbol=target_symbol,
                active_file=active_file,
                target_signature_sha256=target_signature,
                target_declaration_sha256=target_declaration,
            )
        )
        if planner_obstacle_cleared:
            campaign_epoch.clear_planner_terminal_obstacle(
                autonomy_state,
                prior_planner_obstacle,
            )
        if requested_route == "plan" and route_execution.planner_terminal_obstacle_blocks_request(
            autonomy_state,
            target_symbol=target_symbol,
            active_file=active_file,
            target_signature_sha256=target_signature,
            target_declaration_sha256=target_declaration,
        ):
            obstacle = dict(
                autonomy_state.get(route_execution.PLANNER_TERMINAL_OBSTACLE_STATE_KEY) or {}
            )
            _record_activity(
                "prover-plan-request-suppressed",
                (f"Suppressed repeated planner request for unchanged target " f"{target_symbol}"),
                target_symbol=target_symbol,
                active_file=active_file,
                target_signature_sha256=target_signature,
                outcome=str(obstacle.get("outcome", "") or ""),
                reason=str(obstacle.get("reason", "") or ""),
            )
            requested_route = ""
            requested_route_reason = ""
        if ok:
            _clear_pending_plan_capacity(autonomy_state)
        elif requested_route:
            _set_prover_requested_route(
                autonomy_state,
                route=requested_route,
                target_symbol=target_symbol,
                active_file=active_file,
                reason=requested_route_reason,
            )
            _record_activity(
                "prover-route-requested",
                f"Unresolved prover turn requested route {requested_route}",
                target_symbol=target_symbol,
                active_file=active_file,
                route=requested_route,
                reason=requested_route_reason,
            )
    if ok:
        _clear_manager_feedback_retries(
            autonomy_state,
            target_symbol=target_symbol,
            active_file=active_file,
        )
    file_label = _relative_file_label(active_file) or active_file
    _record_activity(
        "manager-final-report-review",
        f"Manager reviewed agent final report for {target_symbol}: {'accepted' if ok else 'rejected'}",
        target_symbol=target_symbol,
        active_file=active_file,
        active_file_label=file_label,
        manager_verification=manager_check,
        accepted=ok,
    )
    print("")
    print(
        f"🔎 Manager review of agent final report for {target_symbol}: {'accepted' if ok else 'needs work'}"
    )
    if manager_check.get("command"):
        print(f"   check: {manager_check.get('command')}")
    detail = str(manager_check.get("output", "") or manager_check.get("error", "") or "").strip()
    if detail:
        print(f"   result: {_single_line(detail, 520)}")
    if feedback_kind:
        print(f"   blocker kind: {feedback_kind}")
    if manager_check.get("local_cleanup_reason"):
        print(f"   cleanup: {_single_line(manager_check.get('local_cleanup_reason'), 520)}")
    if ok:
        if manager_check.get("accepted_after_warning_retry_limit"):
            print(
                "   note: warning-only cleanup opportunity already used; allowing the queue to advance."
            )
        print(
            f"✅ Workflow step verified for {target_symbol}; refreshing Lean state and selecting the next target..."
        )
        _print_queue_step_separator(target_symbol)
    elif manager_check.get("retry_exhausted"):
        print(
            f"↻ Local feedback window complete for {target_symbol}; "
            "safe state checkpointed and the campaign continues on a new route."
        )
        _print_queue_step_separator(target_symbol, accepted=False)
    else:
        if retry_limit:
            _increment_manager_feedback_retry(
                autonomy_state,
                target_symbol=target_symbol,
                active_file=active_file,
                kind=feedback_kind,
                signature=_manager_feedback_retry_signature(feedback_kind, manager_check),
            )
        if agent_claimed_success:
            print(
                f"↻ Agent claimed {target_symbol} was solved, but manager verification "
                "still failed; continuing this queue item."
            )
        else:
            print(
                f"↻ Agent ended an unresolved turn for {target_symbol}; manager verification "
                "confirmed it remains open, so the queue item continues."
            )
        _print_queue_step_separator(target_symbol, accepted=False)
        feedback_text = _manager_final_report_feedback(target_symbol, active_file, manager_check)
        nudge_guidance = _maybe_manager_nudge(
            autonomy_state,
            manager_check,
            target_symbol=target_symbol,
            active_file=active_file,
            result=updated,
        )
        if nudge_guidance:
            feedback_text = f"{feedback_text}\n{nudge_guidance}"
        messages.append({"role": "user", "content": feedback_text})
        updated["messages"] = messages
    if construction_turn_guidance and not ok:
        guided_messages = list(updated.get("messages") or messages)
        if guided_messages and str(guided_messages[-1].get("role", "") or "") == "user":
            prior_content = str(guided_messages[-1].get("content", "") or "").rstrip()
            guided_messages[-1] = {
                **guided_messages[-1],
                "content": f"{prior_content}\n\n{construction_turn_guidance}".strip(),
            }
        else:
            guided_messages.append({"role": "user", "content": construction_turn_guidance})
        updated["messages"] = guided_messages
    if shadow_state is not None and shadow_evidence is not None:
        try:
            retry_exhausted = bool(manager_check.get("retry_exhausted"))
            mismatch = _shadow_compare(
                autonomy_state=shadow_state,
                source=DecisionSource.FINAL_REPORT,
                check=shadow_evidence,
                axiom_blockers=tuple(axiom_blockers),
                legacy=_shadow_legacy_outcome(
                    action=(
                        "restore_baseline"
                        if retry_exhausted
                        else "advance_queue" if ok else "continue_same_theorem"
                    ),
                    feedback_kind="" if ok else feedback_kind,
                    retry_limit=retry_limit,
                    restore_baseline=retry_exhausted,
                ),
            )
            if mismatch is not None:
                _record_activity(
                    "queue-decide-shadow-mismatch",
                    f"decide() diverged from the final-report gate for {target_symbol}",
                    target_symbol=target_symbol,
                    active_file=active_file,
                    **mismatch,
                )
        except Exception:
            logger.debug("queue-decide shadow compare failed", exc_info=True)
    updated["manager_final_report_review"] = manager_check
    return updated


def _managed_tool_result_succeeded(result: str) -> bool:
    text = str(result or "").strip()
    if not text:
        return True
    try:
        payload = json.loads(text)
    except Exception:
        return True
    if not isinstance(payload, Mapping):
        return True
    if "success" in payload:
        return bool(payload.get("success"))
    if "error" in payload and payload.get("error"):
        return False
    if "ok" in payload:
        return bool(payload.get("ok"))
    return True


def _verified_patch_result_passed(result: str) -> bool:
    """Return whether apply_verified_patch completed its broad verification gate."""
    payload = _json_tool_result_payload(result)
    status = str(payload.get("status", "") or "").strip().lower()
    return bool(
        payload.get("success") is not False
        and payload.get("check_passed") is True
        and status in {"patch_elaborated", "verified"}
    )


def _verified_patch_batch_checks(
    result: str,
    *,
    active_file: str,
    assignment_target: str,
    declaration_targets: Sequence[str],
) -> dict[str, Mapping[str, Any]]:
    """Return source-bound checks from one post-patch axiom-profile batch.

    The leaf classifier owns all evidence validation. This wrapper deliberately
    resolves ``lean_axioms_many`` from ``native_runner`` so existing test and
    deployment monkeypatch surfaces remain effective.
    """
    targets = tuple(
        dict.fromkeys(
            str(target or "").strip() for target in declaration_targets if str(target or "").strip()
        )
    )
    if not targets:
        return {}
    started = time.monotonic()
    decision = verified_patch_batch_reuse.build_reusable_checks(
        _json_tool_result_payload(result),
        active_file=active_file,
        assignment_target=assignment_target,
        declaration_targets=targets,
        allowed_axioms=_allowed_axioms(),
        inspect_axioms_many=lambda names, path: lean_axioms_many(
            names,
            file_path=path,
        ),
    )
    elapsed_s = max(0.0, time.monotonic() - started)
    _record_activity(
        (
            "verified-patch-batch-reused"
            if decision.reusable
            else "verified-patch-batch-reuse-rejected"
        ),
        (
            f"Reused one post-patch axiom batch for {len(targets)} declaration(s)"
            if decision.reusable
            else "Fresh per-declaration verification remains required after verified patch"
        ),
        target_symbol=assignment_target,
        active_file=active_file,
        declaration_targets=list(targets),
        reason=decision.reason,
        source_sha256=decision.source_sha256,
        elapsed_s=round(elapsed_s, 3),
        verification_reused=decision.reusable,
        lean_started=decision.axiom_batch_started,
        campaign_progress=False,
    )
    return {name: dict(check) for name, check in decision.checks.items()}


def _search_progress_assignment(agent: Any) -> tuple[str, str]:
    autonomy_state = getattr(agent, "_managed_autonomy_state", {}) or {}
    assignment = dict(dict(autonomy_state or {}).get("current_queue_assignment") or {})
    target_symbol = str(assignment.get("target_symbol", "") or "").strip()
    active_file = str(assignment.get("active_file", "") or "").strip()
    return target_symbol, active_file


def _normalized_search_query(value: Any) -> str:
    return " ".join(str(value or "").strip().lower().split())


def _append_post_tool_result_message(agent: Any, message: str) -> None:
    with contextlib.suppress(Exception):
        agent.stage_tool_result_appendix(message)


FORMALIZATION_HANDOFF_FEEDBACK_TOOLS = {
    "patch",
    "write_file",
    "apply_verified_patch",
    "lean_verify",
}


def _formalization_lean_edit_paths(
    function_name: str, args: Mapping[str, Any] | None
) -> list[Path]:
    if _workflow_kind() != "formalize" or not _document_formalization_requested():
        return []
    root = Path(_project_root()).expanduser().resolve()
    target_path = _document_formalization_target_path()
    target_dir = None
    if target_path is not None:
        try:
            target_dir = target_path.resolve().parent
        except Exception:
            target_dir = None
    paths: list[Path] = []
    for path in _tool_edit_paths(function_name, args):
        try:
            resolved = path.resolve()
            resolved.relative_to(root)
        except Exception:
            continue
        if resolved.suffix != ".lean":
            continue
        if target_path is not None:
            try:
                if resolved == target_path.resolve():
                    if resolved not in paths:
                        paths.append(resolved)
                    continue
            except Exception:
                pass
        if target_dir is not None:
            try:
                resolved.relative_to(target_dir)
                if resolved not in paths:
                    paths.append(resolved)
                continue
            except Exception:
                pass
        generated_paths = {
            item.resolve() for item in _formalization_generated_lean_paths(str(target_path or ""))
        }
        if resolved in generated_paths:
            if resolved not in paths:
                paths.append(resolved)
    return paths


def _formalization_raw_lean_check_paths(edit_paths: Sequence[Path]) -> list[Path]:
    target_path = _document_formalization_target_path()
    paths: list[Path] = []

    def _add(path: Path | None) -> None:
        if path is None:
            return
        try:
            resolved = path.resolve()
        except Exception:
            return
        if resolved.suffix == ".lean" and resolved.is_file() and resolved not in paths:
            paths.append(resolved)

    _add(target_path)
    for path in edit_paths:
        _add(path)
    return paths


def _check_formalization_raw_lean_edit_result(
    agent: Any,
    function_name: str,
    args: Mapping[str, Any] | None,
) -> bool:
    """Verify generated Lean edits immediately after patch/write_file in formalization mode. Returns True and records activity; feeds Lean diagnostics back to agent on failure, or prints success confirmation and continues."""
    if function_name not in {"patch", "write_file"}:
        return False
    edit_paths = _formalization_lean_edit_paths(function_name, args)
    if not edit_paths:
        return False
    autonomy_state = getattr(agent, "_managed_autonomy_state", None)
    checked: list[dict[str, Any]] = []
    failed: tuple[Path, dict[str, Any], dict[str, Any]] | None = None
    for path in _formalization_raw_lean_check_paths(edit_paths):
        manager_check = _manager_verify_queue_file(str(path))
        record = _record_manager_verification(
            autonomy_state if isinstance(autonomy_state, dict) else None,
            str(path),
            "",
            manager_check,
            "lean_verify",
        )
        label = _relative_file_label(str(path)) or str(path)
        checked.append(
            {
                "path": label,
                "ok": bool(record.get("ok", False)),
                "summary": record.get("summary", ""),
            }
        )
        if not bool(record.get("ok", False)) and failed is None:
            failed = (path, manager_check, record)
            break

    _record_activity(
        "formalization-lean-edit-checked",
        (
            "Generated Lean edit passed immediate verification"
            if failed is None
            else "Generated Lean edit failed immediate verification"
        ),
        tool=function_name,
        checked=checked,
    )
    if failed is None:
        if not bool(getattr(agent, "quiet_mode", False)):
            labels = ", ".join(str(item.get("path", "")) for item in checked if item.get("path"))
            print(f"\n✅ Formalization Lean edit verified{f' ({labels})' if labels else ''}.")
        return True

    path, manager_check, record = failed
    output = str(manager_check.get("output", "") or manager_check.get("error", "") or "").strip()
    lines = [
        "[LEANFLOW FORMALIZATION LEAN CHECK FAILED]",
        "- status: a raw generated Lean edit failed immediate file verification",
        f"- file: {_relative_file_label(str(path)) or str(path)}",
        f"- verification: {_verification_status_text(record) or 'failed'}",
        "- next action: fix the generated Lean elaboration before updating blueprint status, requesting review, or reporting completion",
    ]
    if output:
        lines.append(f"- feedback: {_single_line(output, 700)}")
    _append_post_tool_result_message(agent, "\n".join(lines))
    if not bool(getattr(agent, "quiet_mode", False)):
        print(
            "\n↻ Formalization Lean edit failed immediate verification; "
            "feeding Lean diagnostics back into the drafting turn."
        )
    return True


def _formalization_handoff_feedback_text(live_state: Mapping[str, Any] | None) -> str:
    if not _document_formalization_handoff_blocked_state(live_state):
        return ""
    handoff = dict((live_state or {}).get("document_formalization_handoff", {}) or {})
    issues = [
        _single_line(issue, 360)
        for issue in handoff.get("issues", []) or []
        if str(issue or "").strip()
    ]
    if not issues:
        summary = _single_line(str(handoff.get("summary", "") or ""), 360)
        issues = [summary] if summary else []
    if not issues:
        return ""
    lines = [
        "[LEANFLOW FORMALIZATION VERIFIER BLOCK]",
        "The formalization verifier blocked handoff. Treat these findings as the next required correction task, not as advisory log text.",
        "- do not mark the blueprint proof-ready",
        "- do not report formalization as ready",
        "- do not start theorem proving or fill theorem/lemma/example proofs",
        "- edit the Lean statements, blueprint coverage/scope fields, or source-aware doc comments to address the findings",
        "- if the only remaining blocker is independent source/statement approval, stop and report that instead of self-approving it",
        "",
        "Verifier findings to address now:",
    ]
    lines.extend(f"- {issue}" for issue in issues[:8])
    if len(issues) > 8:
        lines.append(f"- plus {len(issues) - 8} more verifier finding(s) in workflow status")
    return "\n".join(lines)


def _maybe_append_formalization_handoff_feedback(
    agent: Any,
    *,
    function_name: str,
    live_state: Mapping[str, Any] | None = None,
) -> None:
    if function_name not in FORMALIZATION_HANDOFF_FEEDBACK_TOOLS:
        return
    if _workflow_kind() != "formalize" or not _document_formalization_requested():
        return
    current = dict(live_state or {})
    if not current:
        autonomy_state = getattr(agent, "_managed_autonomy_state", {}) or {}
        try:
            current = _build_live_proof_state_compat(
                list(getattr(agent, "_session_messages", []) or []),
                autonomy_state=autonomy_state if isinstance(autonomy_state, dict) else None,
            )
        except Exception:
            current = {}
    message = _formalization_handoff_feedback_text(current)
    if not message:
        return
    _append_post_tool_result_message(agent, message)
    handoff = dict(current.get("document_formalization_handoff", {}) or {})
    _record_activity(
        "formalization-verifier-feedback-injected",
        "Injected formalization verifier BLOCK findings into the next model turn",
        tool=function_name,
        active_file=str(
            current.get("active_file_label", "") or current.get("active_file", "") or ""
        ),
        issues=[_single_line(issue, 240) for issue in handoff.get("issues", []) or []][:8],
    )
    if not bool(getattr(agent, "quiet_mode", False)):
        print("\n↻ Formalization verifier BLOCK; feeding findings back into the drafting turn.")


def _reset_search_progress(agent: Any) -> None:
    autonomy_state = getattr(agent, "_managed_autonomy_state", None)
    if isinstance(autonomy_state, dict):
        autonomy_state.pop("search_progress", None)


def _search_synthesis_debt_active(
    autonomy_state: Mapping[str, Any] | None,
    *,
    target_symbol: str = "",
    active_file: str = "",
) -> bool:
    """Return whether the exact queue assignment owes construction after search."""
    state = dict(autonomy_state or {})
    progress = dict(state.get("search_progress") or {})
    if not progress or not (
        bool(progress.get("hard_route_requested")) or bool(progress.get("synthesis_grace_pending"))
    ):
        return False
    assignment = dict(state.get("current_queue_assignment") or {})
    resolved_target = str(target_symbol or assignment.get("target_symbol", "") or "").strip()
    resolved_file = str(active_file or assignment.get("active_file", "") or "").strip()
    progress_target = str(progress.get("target_symbol", "") or "").strip()
    progress_file = str(progress.get("active_file", "") or "").strip()
    return bool(
        resolved_target
        and resolved_file
        and progress_target == resolved_target
        and _same_active_file(progress_file, resolved_file)
    )


def _construction_only_handoff_block(
    live_state: Mapping[str, Any],
    autonomy_state: Mapping[str, Any] | None,
) -> str:
    """Build the generic construction directive after bounded discovery is spent."""
    target_symbol = str(live_state.get("target_symbol", "") or "").strip()
    active_file = str(live_state.get("active_file", "") or "").strip()
    if not _search_synthesis_debt_active(
        autonomy_state,
        target_symbol=target_symbol,
        active_file=active_file,
    ):
        return ""
    progress = dict(dict(autonomy_state or {}).get("search_progress") or {})
    search_count = int(progress.get("search_count", 0) or 0)
    return "\n".join(
        [
            "[LEANFLOW CONSTRUCTION-ONLY HANDOFF]",
            f"- bounded discovery is complete ({search_count} calls); its evidence is preserved below",
            "- do not restart with skill loading, capability inspection, queue/sorry inventory, outline, search, or broad source reads",
            "- synthesize from the supplied goal, declarations, findings, graph, and dead branches",
            "- the first substantive action must be a concrete Lean candidate check, a verified proof edit, or a cohesive top-level helper decomposition",
            "- use one exact local source read only when a missing declaration signature or patch anchor makes construction impossible",
            "- construction debt clears only after kernel-verified proof progress or assignment change",
        ]
    )


def _construction_turn_debt_handoff_block(
    live_state: Mapping[str, Any],
    autonomy_state: Mapping[str, Any] | None,
) -> str:
    """Build the mandatory construction directive after route-only oscillation."""
    state = dict(autonomy_state or {})
    target_symbol = str(live_state.get("target_symbol", "") or "").strip()
    active_file = str(live_state.get("active_file", "") or "").strip()
    tracker = dict(state.get(search_synthesis_admission.CONSTRUCTION_DEBT_STATE_KEY) or {})
    if (
        not target_symbol
        or not active_file
        or not search_synthesis_admission.construction_required_for_assignment(
            tracker,
            target_symbol=target_symbol,
            active_file=active_file,
            source_revision_sha256=_source_revision_sha256(active_file),
            construction_attempt_serial=int(
                state.get(search_synthesis_admission.CONSTRUCTION_ATTEMPT_SERIAL_KEY, 0) or 0
            ),
        )
    ):
        return ""
    routes = [str(route) for route in (tracker.get("routes") or []) if str(route)]
    return "\n".join(
        [
            "[LEANFLOW CONCRETE CONSTRUCTION REQUIRED]",
            (
                f"- {int(tracker.get('count', 0) or 0)} unresolved turns reached the "
                "same assigned declaration and source without a material Lean candidate"
            ),
            *([f"- advisory routes already tried: {', '.join(routes)}"] if routes else []),
            "- advisory route changes, research, source rereads, and planner calls are temporarily closed",
            "- the next action must construct or screen a concrete declaration: make a scoped proof edit, check a complete replacement/helper, run concrete tactic attempts, or mechanically decompose a local proof",
            "- preserve every named obligation and dead branch, but do not end the turn with another plan or route request",
            "- this fence clears after a material assigned-source change or a substantive Lean candidate attempt",
        ]
    )


def _construction_turn_debt_pre_tool_guard(
    agent: Any,
    function_name: str,
    args: Mapping[str, Any] | None,
    autonomy_state: Mapping[str, Any],
) -> str | None:
    """Fence advisory tools until an oscillating route makes a concrete attempt."""
    assignment = dict(autonomy_state.get("current_queue_assignment") or {})
    target_symbol = str(assignment.get("target_symbol", "") or "").strip()
    active_file = str(assignment.get("active_file", "") or "").strip()
    tracker = dict(autonomy_state.get(search_synthesis_admission.CONSTRUCTION_DEBT_STATE_KEY) or {})
    if (
        not target_symbol
        or not active_file
        or not search_synthesis_admission.construction_required_for_assignment(
            tracker,
            target_symbol=target_symbol,
            active_file=active_file,
            source_revision_sha256=_source_revision_sha256(active_file),
            construction_attempt_serial=int(
                autonomy_state.get(
                    search_synthesis_admission.CONSTRUCTION_ATTEMPT_SERIAL_KEY,
                    0,
                )
                or 0
            ),
        )
    ):
        return None
    if search_synthesis_admission.construction_attempt_request(function_name, args):
        return None
    if function_name in {"acquire_file_lock", "release_file_lock", "list_file_locks", "terminal"}:
        return None
    with contextlib.suppress(Exception):
        _record_agent_activity(
            agent,
            "construction-turn-debt-tool-blocked",
            f"Blocked advisory tool {function_name} until {target_symbol} receives a concrete attempt",
            target_symbol=target_symbol,
            active_file=active_file,
            blocked_tool=function_name,
            no_progress_turns=int(tracker.get("count", 0) or 0),
            provider_called=False,
            lean_started=False,
            campaign_progress=False,
        )
    return json.dumps(
        {
            "success": False,
            "status": "concrete_construction_required",
            "blocked_tool": function_name,
            "target_symbol": target_symbol,
            "active_file": active_file,
            "no_progress_turns": int(tracker.get("count", 0) or 0),
            "provider_called": False,
            "lean_started": False,
            "required_action": (
                "Use a scoped proof edit, a complete Lean replacement/helper check, concrete "
                "tactic attempts, or mechanical local decomposition before more advice or inspection."
            ),
            "reason": (
                "This unchanged assignment already cycled through multiple advisory routes "
                "without constructing a material Lean candidate."
            ),
        },
        ensure_ascii=False,
    )


ROLLBACK_REFRESH_READ_STATE_KEY = "rollback_refresh_read_required"


def _remember_rollback_refresh_read(
    autonomy_state: dict[str, Any],
    *,
    target_symbol: str,
    active_file: str,
    source_revision_sha256: str,
    reason: str = "rollback",
) -> None:
    """Reserve one exact source reread after an edit loses its source anchor."""
    pending = {
        "target_symbol": target_symbol,
        "active_file": active_file,
        "source_revision_sha256": source_revision_sha256,
    }
    if reason != "rollback":
        pending["reason"] = reason
    autonomy_state[ROLLBACK_REFRESH_READ_STATE_KEY] = pending


def _rollback_refresh_read_matches(
    autonomy_state: Mapping[str, Any],
    function_name: str,
    args: Mapping[str, Any] | None,
) -> bool:
    """Return whether this read satisfies the manager's rollback refresh requirement."""
    if function_name != "read_file":
        return False
    if not _rollback_refresh_required_for_assignment(autonomy_state):
        return False
    pending = dict(autonomy_state.get(ROLLBACK_REFRESH_READ_STATE_KEY) or {})
    assignment = dict(autonomy_state.get("current_queue_assignment") or {})
    target_symbol = str(assignment.get("target_symbol", "") or "").strip()
    active_file = str(assignment.get("active_file", "") or "").strip()
    if (
        not target_symbol
        or not active_file
        or target_symbol != str(pending.get("target_symbol", "") or "").strip()
        or not _same_active_file(active_file, str(pending.get("active_file", "") or ""))
        or _source_revision_sha256(active_file)
        != str(pending.get("source_revision_sha256", "") or "")
    ):
        return False
    requested_file = str(
        dict(args or {}).get("path", "") or dict(args or {}).get("file_path", "") or ""
    ).strip()
    if not requested_file or not _same_active_file(requested_file, active_file):
        return False
    if source_refresh_admission.bounded_patch_anchor_read_matches(
        pending,
        function_name=function_name,
        args=args,
        active_file=active_file,
    ):
        return True
    try:
        requested_start = int(dict(args or {}).get("offset", 0) or 0)
        requested_limit = int(dict(args or {}).get("limit", 0) or 0)
    except (TypeError, ValueError):
        return False
    entry = _find_declaration_entry(active_file, target_symbol)
    if entry is None:
        return False
    try:
        target_start = int(entry.get("line", 0) or 0)
        target_end = int(entry.get("end_line", 0) or 0)
    except (TypeError, ValueError):
        return False
    return bool(
        requested_start > 0
        and requested_limit > 0
        and requested_start <= target_start
        and requested_start + requested_limit - 1 >= target_end
    )


def _normalize_rollback_refresh_read_args(
    agent: Any,
    autonomy_state: Mapping[str, Any],
    function_name: str,
    args: Mapping[str, Any] | None,
) -> None:
    """Expand a rollback reread to the complete restored declaration in place."""
    if function_name != "read_file" or not isinstance(args, dict):
        return
    if not _rollback_refresh_required_for_assignment(autonomy_state):
        return
    pending = dict(autonomy_state.get(ROLLBACK_REFRESH_READ_STATE_KEY) or {})
    if source_refresh_admission.is_patch_anchor_miss(pending):
        return
    assignment = dict(autonomy_state.get("current_queue_assignment") or {})
    target_symbol = str(assignment.get("target_symbol", "") or "").strip()
    active_file = str(assignment.get("active_file", "") or "").strip()
    requested_file = str(args.get("path", "") or args.get("file_path", "") or "").strip()
    if (
        not target_symbol
        or not active_file
        or not requested_file
        or not _same_active_file(requested_file, active_file)
        or _rollback_refresh_read_matches(
            autonomy_state,
            function_name,
            args,
        )
    ):
        return
    entry = _find_declaration_entry(active_file, target_symbol)
    if entry is None:
        return
    try:
        target_start = int(entry.get("line", 0) or 0)
        target_end = int(entry.get("end_line", 0) or 0)
    except (TypeError, ValueError):
        return
    if target_start <= 0 or target_end < target_start:
        return
    prior_offset = args.get("offset")
    prior_limit = args.get("limit")
    args["offset"] = target_start
    args["limit"] = target_end - target_start + 1
    with contextlib.suppress(Exception):
        _record_agent_activity(
            agent,
            "rollback-refresh-read-range-expanded",
            f"Expanded rollback refresh read to the complete {target_symbol} declaration",
            target_symbol=target_symbol,
            active_file=active_file,
            requested_offset=prior_offset,
            requested_limit=prior_limit,
            admitted_offset=target_start,
            admitted_limit=target_end - target_start + 1,
            blocked_by_construction_budget=False,
            campaign_progress=False,
        )


def _rollback_refresh_required_for_assignment(autonomy_state: Mapping[str, Any]) -> bool:
    """Return whether the current restored assignment still requires an exact source reread."""
    pending = dict(autonomy_state.get(ROLLBACK_REFRESH_READ_STATE_KEY) or {})
    if not pending:
        return False
    assignment = dict(autonomy_state.get("current_queue_assignment") or {})
    target_symbol = str(assignment.get("target_symbol", "") or "").strip()
    active_file = str(assignment.get("active_file", "") or "").strip()
    return bool(
        target_symbol
        and active_file
        and target_symbol == str(pending.get("target_symbol", "") or "").strip()
        and _same_active_file(active_file, str(pending.get("active_file", "") or ""))
        and _source_revision_sha256(active_file)
        == str(pending.get("source_revision_sha256", "") or "")
    )


def _rollback_refresh_edit_guard(
    agent: Any,
    function_name: str,
    args: Mapping[str, Any] | None,
    autonomy_state: Mapping[str, Any],
) -> str | None:
    """Require the restored declaration reread before accepting another managed edit."""
    if function_name not in {"patch", "write_file", "apply_verified_patch"}:
        return None
    if not _rollback_refresh_required_for_assignment(autonomy_state):
        return None
    assignment = dict(autonomy_state.get("current_queue_assignment") or {})
    pending = dict(autonomy_state.get(ROLLBACK_REFRESH_READ_STATE_KEY) or {})
    anchor_miss = source_refresh_admission.is_patch_anchor_miss(pending)
    target_symbol = str(assignment.get("target_symbol", "") or "").strip()
    active_file = str(assignment.get("active_file", "") or "").strip()
    if not _managed_edit_targets_assignment(args, active_file, function_name=function_name):
        return None
    with contextlib.suppress(Exception):
        _record_agent_activity(
            agent,
            (
                "patch-anchor-refresh-edit-blocked"
                if anchor_miss
                else "rollback-refresh-edit-blocked"
            ),
            (
                f"Blocked stale follow-up edit after a patch anchor miss for {target_symbol}"
                if anchor_miss
                else f"Blocked stale follow-up edit for restored declaration {target_symbol}"
            ),
            target_symbol=target_symbol,
            active_file=active_file,
            blocked_tool=function_name,
            provider_called=False,
            lean_started=False,
            campaign_progress=False,
        )
    return json.dumps(
        {
            "success": False,
            "status": "rollback_refresh_read_required",
            "blocked_tool": function_name,
            "target_symbol": target_symbol,
            "active_file": active_file,
            "patch_applied": False,
            "provider_called": False,
            "lean_started": False,
            "required_action": (
                (
                    "The previous patch missed its source anchor. Re-read one bounded current-source "
                    "range covering the failed insertion or replacement anchor, then submit the same "
                    "verified construction against that current source."
                )
                if anchor_miss
                else (
                    "The previous candidate was rolled back. Re-read one source range covering the "
                    "complete restored assigned declaration, then submit the complete corrected edit "
                    "against that restored source rather than a delta against the discarded candidate."
                )
            ),
        },
        ensure_ascii=False,
    )


def _advisor_circuit_handoff_block(
    live_state: Mapping[str, Any],
    autonomy_state: Mapping[str, Any] | None,
) -> str:
    """Surface exhausted advisor tools before the model chooses its next action."""
    target_symbol = str(live_state.get("target_symbol", "") or "").strip()
    active_file = str(live_state.get("active_file", "") or "").strip()
    if not target_symbol or not active_file:
        return ""
    source_revision = _source_revision_sha256(active_file)
    target_revision = _target_declaration_sha256(active_file, target_symbol)
    evidence_revision = _advisor_semantic_evidence_sha256(
        dict(autonomy_state or {}),
        target_symbol=target_symbol,
        active_file=active_file,
    )
    campaign_id = str(dict(autonomy_state or {}).get("campaign_id", "") or "")
    blocked = [
        tool
        for tool in sorted(advisor_failure_circuit.ADVISOR_TOOL_NAMES)
        if advisor_failure_circuit.preflight_blocked(
            function_name=tool,
            target_symbol=target_symbol,
            active_file=active_file,
            source_revision_sha256=source_revision,
            target_revision_sha256=target_revision,
            evidence_revision_sha256=evidence_revision,
            campaign_id=campaign_id,
        )
    ]
    if not blocked:
        return ""
    return "\n".join(
        [
            "[LEANFLOW ADVISOR CIRCUIT HANDOFF]",
            f"- exhausted for this unchanged declaration: {', '.join(blocked)}",
            "- do not call these advisor tools again until kernel-verified progress changes the declaration",
            "- use the preserved diagnostics, plan, graph, findings, and dead branches for a concrete local construction step",
        ]
    )


def _search_synthesis_pre_tool_guard(
    agent: Any,
    function_name: str,
    args: Mapping[str, Any] | None,
    autonomy_state: dict[str, Any],
) -> str | None:
    """Reject broad search before execution once this assignment owes synthesis."""
    assignment = dict(autonomy_state.get("current_queue_assignment") or {})
    target_symbol = str(assignment.get("target_symbol", "") or "").strip()
    active_file = str(assignment.get("active_file", "") or "").strip()
    tracker = dict(autonomy_state.get("search_progress") or {})
    if not target_symbol or not active_file or not tracker:
        return None
    discovery_name = search_synthesis_admission.discovery_tool_name(function_name, args)
    if discovery_name is None:
        return None
    if discovery_name == "lean_lemma_suggest":
        duplicate_payload = search_synthesis_admission.duplicate_lemma_suggest_result(
            tracker,
            args=args,
            current_cycle=int(autonomy_state.get("current_cycle", 0) or 0),
            target_symbol=target_symbol,
            active_file=active_file,
        )
        if duplicate_payload is not None:
            with contextlib.suppress(Exception):
                _record_agent_activity(
                    agent,
                    "duplicate-lemma-suggest-blocked",
                    f"Blocked repeated lemma suggestions for {target_symbol}",
                    target_symbol=target_symbol,
                    active_file=active_file,
                    provider_called=False,
                    campaign_progress=False,
                )
            return json.dumps(duplicate_payload, ensure_ascii=False)
    construction_payload = search_synthesis_admission.blocked_construction_source_result(
        function_name=discovery_name,
        tracker=tracker,
        target_symbol=target_symbol,
        active_file=active_file,
        current_cycle=int(autonomy_state.get("current_cycle", 0) or 0),
    )
    if construction_payload is not None:
        rejection_limit = _search_synthesis_rejection_limit()
        rejection_count = min(
            rejection_limit,
            int(tracker.get("construction_synthesis_rejection_count", 0) or 0) + 1,
        )
        tracker["construction_synthesis_rejection_count"] = rejection_count
        autonomy_state["search_progress"] = tracker
        construction_payload["blocked_tool"] = function_name
        if discovery_name != function_name:
            construction_payload["discovery_kind"] = discovery_name
        construction_payload["construction_synthesis_rejection_count"] = rejection_count
        construction_payload["construction_synthesis_rejection_limit"] = rejection_limit
        if rejection_count >= rejection_limit:
            construction_payload["required_action"] = (
                "The bounded construction correction window is exhausted. Preserve the "
                "source evidence and yield so the outer orchestrator can change routes."
            )
        with contextlib.suppress(Exception):
            _record_agent_activity(
                agent,
                "construction-source-tool-blocked",
                f"Blocked {function_name} after {target_symbol} exhausted local source inspection",
                target_symbol=target_symbol,
                active_file=active_file,
                blocked_tool=function_name,
                construction_source_inspection_count=int(
                    tracker.get("construction_source_inspection_count", 0) or 0
                ),
                construction_synthesis_rejection_count=rejection_count,
                construction_synthesis_rejection_limit=rejection_limit,
                provider_called=False,
                campaign_progress=False,
            )
        return json.dumps(construction_payload, ensure_ascii=False)
    payload = search_synthesis_admission.blocked_search_result(
        function_name=discovery_name,
        tracker=tracker,
        target_symbol=target_symbol,
        active_file=active_file,
        current_cycle=int(autonomy_state.get("current_cycle", 0) or 0),
    )
    if payload is None:
        return None
    payload["blocked_tool"] = function_name
    if discovery_name != function_name:
        payload["discovery_kind"] = discovery_name
    # Older checkpoints may have spent the one-turn grace immediately before
    # an interruption while retaining the authoritative hard-route marker.
    # Normalize that shape so the deterministic blocked result follows the
    # same durable-debt path below.
    tracker["synthesis_grace_pending"] = True
    rejection_limit = _search_synthesis_rejection_limit()
    rejection_count = min(
        rejection_limit,
        int(tracker.get("synthesis_rejection_count", 0) or 0) + 1,
    )
    tracker["synthesis_rejection_count"] = rejection_count
    autonomy_state["search_progress"] = tracker
    payload["synthesis_rejection_count"] = rejection_count
    payload["synthesis_rejection_limit"] = rejection_limit
    if rejection_count >= rejection_limit:
        payload["required_action"] = (
            "The bounded correction window is exhausted. Preserve the search evidence and "
            "yield now so the outer orchestrator can start the requested construction route."
        )
    with contextlib.suppress(Exception):
        _record_agent_activity(
            agent,
            "search-synthesis-tool-blocked",
            f"Blocked {function_name} before execution while {target_symbol} owes synthesis",
            target_symbol=target_symbol,
            active_file=active_file,
            blocked_tool=function_name,
            search_count=int(tracker.get("search_count", 0) or 0),
            synthesis_rejection_count=rejection_count,
            synthesis_rejection_limit=rejection_limit,
            provider_called=False,
            campaign_progress=False,
        )
    return json.dumps(payload, ensure_ascii=False)


def _search_progress_hard_limit() -> int:
    """Return the search-only call limit before yielding to orchestration.

    Zero disables the hard handoff for debugging while preserving the advisory
    nudge. The production default is deliberately above the existing nudge
    threshold so a prover gets one clear opportunity to change course itself.
    """
    return _read_int_env(
        "LEANFLOW_SEARCH_PROGRESS_HARD_LIMIT",
        SEARCH_PROGRESS_HARD_LIMIT_DEFAULT,
        minimum=0,
    )


def _search_synthesis_rejection_limit() -> int:
    """Return the blocked-search corrections allowed before a route boundary."""
    return _read_int_env(
        "LEANFLOW_SEARCH_SYNTHESIS_REJECTION_LIMIT",
        SEARCH_SYNTHESIS_REJECTION_LIMIT_DEFAULT,
        minimum=1,
    )


def _construction_source_inspection_hard_limit() -> int:
    """Return the local-read limit for one construction orchestration cycle."""
    return _read_int_env(
        "LEANFLOW_CONSTRUCTION_SOURCE_INSPECTION_HARD_LIMIT",
        CONSTRUCTION_SOURCE_INSPECTION_HARD_LIMIT_DEFAULT,
        minimum=0,
    )


def _construction_source_inspection_repeat_hard_limit() -> int:
    """Return the identical local-lookup limit for one construction cycle."""
    return _read_int_env(
        "LEANFLOW_CONSTRUCTION_SOURCE_INSPECTION_REPEAT_HARD_LIMIT",
        CONSTRUCTION_SOURCE_INSPECTION_REPEAT_HARD_LIMIT_DEFAULT,
        minimum=0,
    )


def _construction_no_progress_turn_limit() -> int:
    """Return unresolved unchanged turns allowed before construction is mandatory."""
    return _read_int_env(
        "LEANFLOW_CONSTRUCTION_NO_PROGRESS_TURN_LIMIT",
        CONSTRUCTION_NO_PROGRESS_TURN_LIMIT_DEFAULT,
        minimum=1,
    )


def _terminal_result_made_concrete_progress(
    args: Mapping[str, Any] | None,
    result: str,
) -> bool:
    """Return whether a terminal result is a successful edit or Lean check."""
    payload = _json_tool_result_payload(result)
    if payload:
        if payload.get("error"):
            return False
        status = str(payload.get("status", "") or "").strip().lower()
        if status in {"approval_required", "blocked", "disabled", "error"}:
            return False
        if "exit_code" in payload:
            try:
                if int(payload.get("exit_code", -1)) != 0:
                    return False
            except (TypeError, ValueError):
                return False
        elif not _managed_tool_result_succeeded(result):
            return False
    elif not _managed_tool_result_succeeded(result):
        return False
    command = str(dict(args or {}).get("command", "") or dict(args or {}).get("cmd", "") or "")
    if _terminal_command_may_edit(command):
        return True
    if not _tool_result_counts_as_theorem_feedback("terminal", args):
        return False
    output = str(payload.get("output", "") or "")
    return not bool(re.search(r"\b(?:sorry|admit)\b", output, flags=re.IGNORECASE))


def _note_non_search_tool_progress(
    agent: Any,
    function_name: str,
    args: Mapping[str, Any] | None,
    result: str,
    *,
    queue_edit_accepted: bool | None = None,
) -> None:
    """Reset a search streak only after concrete tool progress.

    Rejected edits and terminal commands remain part of the same search-only
    streak. Read-only support tools are recorded for nudge context without
    pretending that they advanced the proof.
    """
    file_progress_tools = {
        "patch",
        "write_file",
        "apply_verified_patch",
    }
    verified_check_tools = {
        "lean_incremental_check",
        "lean_verify",
    }
    if function_name in file_progress_tools:
        # The post-edit queue gate resets this only after a changed assignment
        # or a kernel-verified helper. A successful plan/support-file write is
        # orchestration state, not proof progress.
        return
    if function_name in verified_check_tools:
        payload = _json_tool_result_payload(result)
        if _managed_tool_result_succeeded(result) and bool(payload.get("ok")):
            _reset_search_progress(agent)
        return
    if function_name == "terminal":
        if _terminal_result_made_concrete_progress(args, result):
            _reset_search_progress(agent)
        return
    if function_name not in {
        "lean_proof_context",
        "lean_auto_search",
        "lean_reasoning_help",
        "lean_inspect",
    }:
        return
    autonomy_state = getattr(agent, "_managed_autonomy_state", None)
    if not isinstance(autonomy_state, dict):
        return
    tracker = dict(autonomy_state.get("search_progress") or {})
    if not tracker:
        return
    used_tools = dict(tracker.get("used_tools") or {})
    used_tools[function_name] = int(used_tools.get(function_name, 0) or 0) + 1
    tracker["used_tools"] = used_tools
    autonomy_state["search_progress"] = tracker


def _record_turn_prompt_fingerprint(
    autonomy_state: Mapping[str, Any] | None,
    user_message: str,
    *,
    phase: str,
    cycle: int,
) -> None:
    """Record a fingerprint of the ACTUAL per-turn user message sent to the model.

    The activity log's ``effective_prompt`` is the original CLI goal (empty for a bare
    ``/prove <file>``), so it cannot reconstruct what the model was told each cycle. This emits a
    ``turn-prompt`` event with a hash, size, preview, and a changed/unchanged + delta vs the
    previous turn, making the loop auditable and prompt-size optimizations measurable.
    """
    text = str(user_message or "")
    fingerprint = hashlib.sha1(text.encode("utf-8", "replace")).hexdigest()[:12]
    char_count = len(text)
    approx_tokens = char_count // 4
    previous = {}
    if isinstance(autonomy_state, dict):
        previous = dict(autonomy_state.get("last_turn_prompt_fingerprint") or {})
    prev_fingerprint = str(previous.get("fingerprint", "") or "")
    changed = bool(prev_fingerprint) and prev_fingerprint != fingerprint or not prev_fingerprint
    delta_chars = char_count - int(previous.get("char_count", 0) or 0)
    preview = " ".join(text.split())[:200]
    if isinstance(autonomy_state, dict):
        autonomy_state["last_turn_prompt_fingerprint"] = {
            "fingerprint": fingerprint,
            "char_count": char_count,
        }
    _record_activity(
        "turn-prompt",
        f"{phase} turn prompt: {char_count} chars (~{approx_tokens} tok), "
        f"{'changed' if changed else 'unchanged'} vs previous",
        phase=phase,
        cycle=cycle,
        prompt_fingerprint=fingerprint,
        prompt_char_count=char_count,
        prompt_approx_tokens=approx_tokens,
        prompt_changed=changed,
        prompt_delta_chars=delta_chars,
        prompt_preview=preview,
    )


def _delegated_no_tool_synthesis_handoff(
    agent: Any,
    *,
    target_symbol: str,
    active_file: str,
    reason: str,
) -> bool:
    """Keep a delegated evidence lane alive for one final no-tool report."""
    try:
        delegated = int(getattr(agent, "_delegate_depth", 0) or 0) > 0
    except (TypeError, ValueError):
        delegated = False
    if not delegated:
        return False
    _temporarily_disable_agent_tool_schemas(
        agent,
        set(search_synthesis_admission.DISCOVERY_TOOL_NAMES),
    )
    _append_post_tool_result_message(
        agent,
        "\n".join(
            [
                "[LEANFLOW DELEGATED SYNTHESIS HANDOFF]",
                f"- declaration: {target_symbol}",
                f"- reason: {reason}",
                "- discovery is now closed for this lane",
                "- produce the required final response without another tool call",
                "- preserve concrete findings, source references, dead branches, and next proof steps",
            ]
        ),
    )
    with contextlib.suppress(Exception):
        _record_agent_activity(
            agent,
            "delegated-no-tool-synthesis-handoff",
            f"Preserved delegated evidence for final synthesis on {target_symbol}",
            target_symbol=target_symbol,
            active_file=active_file,
            reason=reason,
            hidden_tools=sorted(search_synthesis_admission.DISCOVERY_TOOL_NAMES),
            campaign_progress=False,
        )
    return True


def _track_search_progress(
    agent: Any,
    function_name: str,
    args: Mapping[str, Any] | None,
    result: str,
) -> bool:
    """Track assignment-local research calls and bound a search-only model turn.

    The lower thresholds remain advisory. At the higher hard threshold this
    records a non-terminal route request and closes only the current model
    turn, allowing the deterministic outer orchestrator to refresh strategy.
    Return whether that boundary was requested.
    """
    autonomy_state = getattr(agent, "_managed_autonomy_state", None)
    if not isinstance(autonomy_state, dict):
        return False
    target_symbol, active_file = _search_progress_assignment(agent)
    if not target_symbol or not active_file:
        return False
    payload = _json_tool_result_payload(result)
    query = search_synthesis_admission.request_description(
        function_name,
        args,
        payload,
    )
    normalized_query = _normalized_search_query(query) or "[unspecified request]"
    request_fingerprint = f"{function_name}:{normalized_query}"
    tracker = dict(autonomy_state.get("search_progress") or {})
    if (
        str(tracker.get("target_symbol", "") or "") != target_symbol
        or str(tracker.get("active_file", "") or "") != active_file
    ):
        tracker = {
            "target_symbol": target_symbol,
            "active_file": active_file,
            "search_count": 0,
            "same_query_streak": 0,
            "last_query": "",
            "unique_queries": [],
            "used_tools": {},
        }
    preflight_rejected = (
        str(payload.get("status", "") or "") == "search_synthesis_required"
        and payload.get("provider_called") is False
    )
    construction_rejected = (
        str(payload.get("status", "") or "") == "construction_synthesis_required"
        and payload.get("provider_called") is False
    )
    if construction_rejected:
        rejection_count = int(tracker.get("construction_synthesis_rejection_count", 0) or 0)
        rejection_limit = _search_synthesis_rejection_limit()
        autonomy_state["search_progress"] = tracker
        if rejection_count < rejection_limit:
            _record_agent_activity(
                agent,
                "construction-synthesis-debt-enforced",
                f"Kept {target_symbol} in construction mode after blocking another source read",
                target_symbol=target_symbol,
                active_file=active_file,
                blocked_tool=function_name,
                construction_source_inspection_count=int(
                    tracker.get("construction_source_inspection_count", 0) or 0
                ),
                construction_synthesis_rejection_count=rejection_count,
                construction_synthesis_rejection_limit=rejection_limit,
                provider_called=False,
                campaign_progress=False,
            )
            return False
        route = "plan"
        tracker = search_synthesis_admission.schedule_fresh_construction_window(tracker)
        autonomy_state["search_progress"] = tracker
        _set_prover_requested_route(
            autonomy_state,
            route=route,
            target_symbol=target_symbol,
            active_file=active_file,
        )
        _record_agent_activity(
            agent,
            "construction-synthesis-rejection-boundary",
            f"Repeated source requests for {target_symbol} exhausted the construction correction window",
            target_symbol=target_symbol,
            active_file=active_file,
            blocked_tool=function_name,
            construction_source_inspection_count=int(
                tracker.get("construction_source_inspection_count", 0) or 0
            ),
            construction_synthesis_rejection_count=rejection_count,
            construction_synthesis_rejection_limit=rejection_limit,
            provider_called=False,
            route=route,
            campaign_progress=False,
        )
        if _delegated_no_tool_synthesis_handoff(
            agent,
            target_symbol=target_symbol,
            active_file=active_file,
            reason="construction source-inspection boundary reached",
        ):
            return False
        with contextlib.suppress(Exception):
            agent._managed_pending_theorem_feedback = None
            agent._managed_step_boundary_closed = True
        if not bool(getattr(agent, "quiet_mode", False)):
            print(
                f"\n↻ {target_symbol} repeated source inspection after its construction "
                "window; yielding to a distinct route."
            )
        _request_step_boundary_interrupt(agent)
        return True
    if bool(tracker.get("synthesis_grace_pending")) and preflight_rejected:
        tracker["synthesis_grace_pending"] = True
        autonomy_state["search_progress"] = tracker
        rejection_count = int(tracker.get("synthesis_rejection_count", 0) or 0)
        rejection_limit = _search_synthesis_rejection_limit()
        if rejection_count >= rejection_limit:
            tracker = search_synthesis_admission.schedule_fresh_construction_window(tracker)
            autonomy_state["search_progress"] = tracker
            _record_agent_activity(
                agent,
                "search-synthesis-rejection-boundary",
                (
                    f"Repeated blocked searches for {target_symbol} exhausted "
                    "the synthesis correction window"
                ),
                target_symbol=target_symbol,
                active_file=active_file,
                blocked_tool=function_name,
                search_count=int(tracker.get("search_count", 0) or 0),
                synthesis_rejection_count=rejection_count,
                synthesis_rejection_limit=rejection_limit,
                provider_called=False,
                route=str(tracker.get("hard_route", "") or "plan"),
                campaign_progress=False,
            )
            if _delegated_no_tool_synthesis_handoff(
                agent,
                target_symbol=target_symbol,
                active_file=active_file,
                reason="search synthesis correction boundary reached",
            ):
                return False
            with contextlib.suppress(Exception):
                agent._managed_pending_theorem_feedback = None
                agent._managed_step_boundary_closed = True
            if not bool(getattr(agent, "quiet_mode", False)):
                print(
                    f"\n↻ {target_symbol} repeated a blocked search "
                    f"{rejection_count} times; yielding to the preserved "
                    "construction route."
                )
            _request_step_boundary_interrupt(agent)
            return True
        _record_agent_activity(
            agent,
            "search-synthesis-debt-enforced",
            f"Kept {target_symbol} in construction mode after blocking another search",
            target_symbol=target_symbol,
            active_file=active_file,
            blocked_tool=function_name,
            search_count=int(tracker.get("search_count", 0) or 0),
            synthesis_rejection_count=rejection_count,
            synthesis_rejection_limit=rejection_limit,
            provider_called=False,
            campaign_progress=False,
        )
        return False
    if function_name in search_synthesis_admission.SOURCE_INSPECTION_TOOL_NAMES and (
        bool(tracker.get("synthesis_grace_pending")) or bool(tracker.get("hard_route_requested"))
    ):
        # A construction route still needs exact local source context. Keep the
        # broad-search debt durable, but do not turn required reads into more
        # search debt or immediately close the fresh worker that inherited it.
        hard_limit = _construction_source_inspection_hard_limit()
        repeat_hard_limit = _construction_source_inspection_repeat_hard_limit()
        tracker, inspection = search_synthesis_admission.observe_source_inspection(
            tracker,
            function_name=function_name,
            args=args,
            cycle=int(autonomy_state.get("current_cycle", 0) or 0),
            hard_limit=hard_limit,
            repeat_hard_limit=repeat_hard_limit,
        )
        used_tools = dict(tracker.get("used_tools") or {})
        used_tools[function_name] = int(used_tools.get(function_name, 0) or 0) + 1
        tracker["used_tools"] = used_tools
        autonomy_state["search_progress"] = tracker
        _record_agent_activity(
            agent,
            "search-synthesis-source-inspection",
            f"Allowed local source inspection while {target_symbol} owes synthesis",
            target_symbol=target_symbol,
            active_file=active_file,
            inspection_tool=function_name,
            search_count=int(tracker.get("search_count", 0) or 0),
            construction_source_inspection_count=inspection.count,
            campaign_progress=False,
        )
        if inspection.close_turn:
            _append_post_tool_result_message(
                agent,
                "\n".join(
                    [
                        "[LEANFLOW-NATIVE CONSTRUCTION SOURCE BOUNDARY]",
                        f"- declaration: {target_symbol}",
                        (
                            f"- observed: {inspection.count} local source reads/searches "
                            "without a successful proof edit or check"
                        ),
                        "- this threshold-producing read completed and is available now",
                        "- further source inspection is fenced for this construction cycle",
                        "- use the declarations already read to make or check a concrete proof edit",
                        "- proof edits, helper decomposition, and LeanProbe checks remain available",
                    ]
                ),
            )
            _record_agent_activity(
                agent,
                "construction-source-inspection-boundary",
                f"Construction source window for {target_symbol} now requires synthesis",
                target_symbol=target_symbol,
                active_file=active_file,
                construction_source_inspection_count=inspection.count,
                same_request_streak=inspection.same_request_streak,
                hard_limit=hard_limit,
                repeat_hard_limit=repeat_hard_limit,
                campaign_progress=False,
            )
            return False
        if inspection.nudge:
            _append_post_tool_result_message(
                agent,
                "\n".join(
                    [
                        "[LEANFLOW-NATIVE CONSTRUCTION SOURCE NUDGE]",
                        f"- declaration: {target_symbol}",
                        f"- local source inspections this construction cycle: {inspection.count}",
                        "- use the declarations already read to make or check a concrete proof edit",
                        "- do not repeat equivalent symbol lookups",
                    ]
                ),
            )
        return False
    elif bool(tracker.get("synthesis_grace_pending")):
        # Reserve one provider turn after the cap for a no-tool synthesis so
        # the final successful fetch can enter the lane's durable report. A
        # preflight-rejected search keeps that debt active and returns control
        # to the same worker; closing the turn here would let orchestration
        # grant the unchanged theorem another full search window.
        # A search result that bypassed preflight (for example from a legacy
        # delegated lane) still closes the inner turn fail-safe.
        tracker["synthesis_grace_pending"] = False
        autonomy_state["search_progress"] = tracker
        _record_agent_activity(
            agent,
            "search-synthesis-grace-exhausted",
            f"Search synthesis grace for {target_symbol} was spent on another search request",
            target_symbol=target_symbol,
            active_file=active_file,
            latest_tool=function_name,
            latest_query=query,
        )
        if _delegated_no_tool_synthesis_handoff(
            agent,
            target_symbol=target_symbol,
            active_file=active_file,
            reason="reserved synthesis turn attempted another discovery call",
        ):
            return False
        with contextlib.suppress(Exception):
            agent._managed_pending_theorem_feedback = None
            agent._managed_step_boundary_closed = True
        _request_step_boundary_interrupt(agent)
        return True
    search_count = int(tracker.get("search_count", 0) or 0) + 1
    same_query_streak = (
        int(tracker.get("same_query_streak", 0) or 0) + 1
        if str(tracker.get("last_request_fingerprint", "") or "") == request_fingerprint
        else 1
    )
    unique_queries = [str(item) for item in list(tracker.get("unique_queries") or []) if str(item)]
    if normalized_query not in unique_queries:
        unique_queries.append(normalized_query)
    results = payload.get("results")
    if not isinstance(results, list):
        results = dict(payload.get("data") or {}).get("web")
    result_count = len(results) if isinstance(results, list) else 0
    used_tools = dict(tracker.get("used_tools") or {})
    used_tools[function_name] = int(used_tools.get(function_name, 0) or 0) + 1
    tracker.update(
        {
            "search_count": search_count,
            "same_query_streak": same_query_streak,
            "last_query": normalized_query,
            "last_request_fingerprint": request_fingerprint,
            "last_query_display": query[:240],
            "unique_queries": unique_queries[-8:],
            "last_result_count": result_count,
            "used_tools": used_tools,
        }
    )
    autonomy_state["search_progress"] = tracker

    hard_limit = _search_progress_hard_limit()
    if hard_limit and search_count >= hard_limit:
        if bool(tracker.get("hard_route_requested")):
            return False
        route = "plan"
        tracker["hard_route_requested"] = True
        tracker["hard_route"] = route
        tracker["synthesis_grace_pending"] = True
        tracker["synthesis_boundary_cycle"] = int(autonomy_state.get("current_cycle", 0) or 0)
        tracker["synthesis_rejection_count"] = 0
        autonomy_state["search_progress"] = tracker
        _set_prover_requested_route(
            autonomy_state,
            route=route,
            target_symbol=target_symbol,
            active_file=active_file,
        )
        _append_post_tool_result_message(
            agent,
            "\n".join(
                [
                    "[LEANFLOW-NATIVE SEARCH ROUTE BOUNDARY]",
                    f"- declaration: {target_symbol}",
                    f"- observed: {search_count} research/search calls without a successful edit or check",
                    f"- route requested: {route}",
                    "- this is a strategy handoff, not a mathematical failure or success",
                    "- do not call another tool; use the next response to synthesize the",
                    "  strongest concrete findings, fetched sources, dead branches, and next helpers",
                    "- after that final report, the outer orchestrator will preserve the evidence",
                    "  and start the distinct route",
                ]
            ),
        )
        _record_agent_activity(
            agent,
            "search-route-change",
            f"Search-only turn for {target_symbol} reached {search_count} calls; requested {route}",
            target_symbol=target_symbol,
            active_file=active_file,
            route=route,
            search_count=search_count,
            hard_limit=hard_limit,
            latest_tool=function_name,
            latest_query=query,
            used_tools=used_tools,
        )
        if not bool(getattr(agent, "quiet_mode", False)):
            print(
                f"\n↻ Search-only turn reached {search_count} calls for {target_symbol}; "
                "reserving one no-tool synthesis response before the route handoff."
            )
        return False

    nudge_reason = ""
    if same_query_streak >= SEARCH_PROGRESS_REPEAT_NUDGE_LIMIT:
        nudge_reason = f"same {function_name} query repeated {same_query_streak} times"
    elif search_count >= SEARCH_PROGRESS_TOTAL_NUDGE_LIMIT:
        nudge_reason = (
            f"{search_count} research/search calls on this declaration since the last edit/check"
        )
    if not nudge_reason:
        return False
    if int(tracker.get("last_nudged_search_count", 0) or 0) == search_count:
        return False
    tracker["last_nudged_search_count"] = search_count
    autonomy_state["search_progress"] = tracker
    used_tools = dict(tracker.get("used_tools") or {})
    context_hint = (
        "- `lean_proof_context` has already been used; prefer a concrete proof draft/check, `lean_decompose_helpers` for a sublemma split, or `lean_reasoning_help`."
        if int(used_tools.get("lean_proof_context", 0) or 0) > 0
        else "- if you still need context, call `lean_proof_context` once; if the proof needs intermediate invariants, use `lean_decompose_helpers`; otherwise draft and check a proof."
    )
    # Be honest about search health: if the providers report degraded state (e.g. local Loogle
    # disabled on a toolchain mismatch, or a malformed LeanExplore DB), telling the model "search
    # providers are responding" sends it back into a useless lean_search spiral. Steer the worker
    # off search instead. NOTE: lean_search seeds degraded_reasons from the FULL capability report
    # (proof-context MCP, incremental verifier, etc.), so we require BOTH a search-provider term and
    # a failure term — otherwise an unrelated capability outage would wrongly suppress search.
    _SEARCH_TERMS = ("loogle", "leanexplore", "lean explore", "search", "semantic provider")
    _FAILURE_TERMS = (
        "disabled",
        "malformed",
        "unavailable",
        "corrupt",
        "failed",
        "outage",
        "error",
    )
    degraded_reasons = [
        str(reason) for reason in (payload.get("degraded_reasons") or []) if str(reason).strip()
    ]
    degraded_hits = [
        reason
        for reason in degraded_reasons
        if any(s in reason.lower() for s in _SEARCH_TERMS)
        and any(f in reason.lower() for f in _FAILURE_TERMS)
    ]
    if degraded_hits:
        health_line = (
            f"- search is DEGRADED ({degraded_hits[0][:160]}); the local search backend is unhealthy, "
            "so more `lean_search` calls will not help — switch now to `lean_proof_context`, "
            "`lean_decompose_helpers`, or `lean_reasoning_help`, or draft and check a proof directly."
        )
    else:
        health_line = "- search providers are responding; this is a route-progress nudge, not a search outage."
    _append_post_tool_result_message(
        agent,
        "\n".join(
            [
                "[LEANFLOW-NATIVE SEARCH PROGRESS NUDGE]",
                f"- declaration: {target_symbol}",
                f"- file: {_relative_file_label(active_file) or active_file}",
                f"- observed: {nudge_reason}",
                f"- latest query: {query[:240] or '[unknown]'}",
                f"- latest result count: {result_count}",
                health_line,
                "- do not call `lean_search` again in this turn unless the query strategy materially changes.",
                context_hint,
                "- next useful action should be a concrete proof edit, `lean_incremental_check(check_target)` on a draft, `lean_multi_attempt`, `lean_decompose_helpers` for a helper-lemma split, or `lean_reasoning_help`.",
            ]
        ),
    )
    _record_agent_activity(
        agent,
        "search-progress-nudge",
        f"Repeated search-only progress nudge for {target_symbol}",
        target_symbol=target_symbol,
        active_file=active_file,
        search_count=search_count,
        same_query_streak=same_query_streak,
        latest_query=query,
        result_count=result_count,
    )
    return False


def _should_emit_failed_attempt_escalation_nudge(attempt_number: int) -> bool:
    if attempt_number < FAILED_ATTEMPT_ESCALATION_NUDGE_LIMIT:
        return False
    interval = max(1, FAILED_ATTEMPT_ESCALATION_NUDGE_INTERVAL)
    return (attempt_number - FAILED_ATTEMPT_ESCALATION_NUDGE_LIMIT) % interval == 0


def _shell_arithmetic_end(line: str, start: int) -> int:
    """Return the end of a shell arithmetic region that starts with ``((``."""

    cursor = start + (3 if line.startswith("$((", start) else 2)
    depth = 1
    quote = ""
    while cursor < len(line):
        char = line[cursor]
        if quote:
            if char == "\\" and quote == '"':
                cursor += 2
                continue
            if char == quote:
                quote = ""
            cursor += 1
            continue
        if char in {"'", '"'}:
            quote = char
            cursor += 1
            continue
        if char == "\\":
            cursor += 2
            continue
        if line.startswith("$((", cursor):
            depth += 1
            cursor += 3
            continue
        if line.startswith("((", cursor):
            depth += 1
            cursor += 2
            continue
        if line.startswith("))", cursor):
            depth -= 1
            cursor += 2
            if depth == 0:
                return cursor
            continue
        cursor += 1
    return len(line)


def _shell_heredoc_delimiters(line: str) -> list[tuple[str, bool]]:
    """Return heredoc delimiters declared by one shell command line.

    Ignore operators inside shell quotes and comments, then apply the shell's
    quote removal to each delimiter.  The boolean records ``<<-`` tab stripping.
    """

    delimiters: list[tuple[str, bool]] = []
    index = 0
    line_length = len(line)
    while index < line_length:
        char = line[index]
        if line.startswith("$((", index) or line.startswith("((", index):
            index = _shell_arithmetic_end(line, index)
            continue
        if char == "\\":
            index += 2
            continue
        if char in {"'", '"'}:
            quote = char
            index += 1
            while index < line_length:
                if line[index] == "\\" and quote == '"':
                    index += 2
                    continue
                if line[index] == quote:
                    index += 1
                    break
                index += 1
            continue
        if char == "#" and (index == 0 or line[index - 1].isspace()):
            break
        if not line.startswith("<<", index) or line.startswith("<<<", index):
            index += 1
            continue

        cursor = index + 2
        strip_tabs = cursor < line_length and line[cursor] == "-"
        if strip_tabs:
            cursor += 1
        while cursor < line_length and line[cursor] in {" ", "\t"}:
            cursor += 1

        delimiter_parts: list[str] = []
        delimiter_started = False
        while cursor < line_length:
            delimiter_char = line[cursor]
            if delimiter_char.isspace() or delimiter_char in ";&|()<>":
                break
            delimiter_started = True
            if delimiter_char == "\\":
                cursor += 1
                if cursor < line_length:
                    delimiter_parts.append(line[cursor])
                    cursor += 1
                continue
            if delimiter_char in {"'", '"'}:
                quote = delimiter_char
                cursor += 1
                while cursor < line_length and line[cursor] != quote:
                    if line[cursor] == "\\" and quote == '"' and cursor + 1 < line_length:
                        cursor += 1
                    delimiter_parts.append(line[cursor])
                    cursor += 1
                if cursor < line_length and line[cursor] == quote:
                    cursor += 1
                continue
            delimiter_parts.append(delimiter_char)
            cursor += 1

        delimiter = "".join(delimiter_parts)
        if delimiter_started and delimiter:
            delimiters.append((delimiter, strip_tabs))
            index = cursor
        else:
            index += 2
    return delimiters


def _mask_shell_heredoc_bodies(command: str) -> str:
    """Mask heredoc payloads while preserving shell command syntax and line breaks."""

    pending: list[tuple[str, bool]] = []
    masked_lines: list[str] = []
    for line in command.splitlines(keepends=True):
        if not pending:
            masked_lines.append(line)
            pending.extend(_shell_heredoc_delimiters(line))
            continue

        delimiter, strip_tabs = pending[0]
        content = line.rstrip("\r\n")
        candidate = content.lstrip("\t") if strip_tabs else content
        # Payload and terminator text are not shell commands.  Keep newlines so
        # patterns cannot accidentally join tokens from the surrounding shell.
        newline = line[len(content) :]
        masked_lines.append((" " * len(content)) + newline)
        if candidate == delimiter:
            pending.pop(0)
    return "".join(masked_lines)


def _terminal_command_may_edit(command: str) -> bool:
    text = _mask_shell_heredoc_bodies(str(command or ""))
    if not text.strip():
        return False
    patterns = (
        r"\bsed\s+(?:-[A-Za-z]*i|[^;&|]*\s-i\b)",
        r"\bperl\s+-[A-Za-z]*i\b",
        r"\bpython(?:3)?\b.*\b(?:write_text|open\s*\(|Path\s*\().*(?:write|append|unlink)",
        r"\b(?:rm|mv|cp|touch|chmod|chown|truncate)\b",
        r"\btee\b",
        r"\bgit\s+(?:reset|clean|checkout|restore|switch|revert|merge|rebase|cherry-pick|apply|am)\b",
        r"\bgit\s+stash\s+(?:apply|pop|drop|clear)\b",
        r"(?:^|\s)(?:\d)?>>?(?!&)",
    )
    return any(re.search(pattern, text, flags=re.DOTALL) for pattern in patterns)


def _queue_edit_snapshot_required(function_name: str, args: Mapping[str, Any] | None) -> bool:
    if function_name == "lean_extract_have" and _lean_extract_have_is_read_only(args):
        return False
    if function_name in _MANAGED_SOURCE_EDIT_TOOLS:
        return True
    if function_name == "terminal":
        return _terminal_command_may_edit(str(dict(args or {}).get("command", "") or ""))
    return False


def _lean_extract_have_is_read_only(args: Mapping[str, Any] | None) -> bool:
    """Return whether a local-have request only inventories source structure."""
    action = str(dict(args or {}).get("action", "extract") or "extract")
    return action.strip().lower().replace("-", "_") in {
        "inventory",
        "inspect",
        "list",
        "plan",
    }


def _queue_edit_snapshot_has_identity(snapshot: Mapping[str, Any]) -> bool:
    """Return whether a snapshot can authoritatively identify one source edit."""
    return bool(
        str(snapshot.get("target_symbol", "") or "").strip()
        and str(snapshot.get("active_file", "") or "").strip()
        and str(snapshot.get("before_text", "") or "")
    )


def _queue_edit_finalization_required(
    agent: Any,
    function_name: str,
    args: Mapping[str, Any] | None,
) -> bool:
    """Return whether this exact source-edit result owns the pending snapshot."""
    if function_name not in _MANAGED_SOURCE_EDIT_TOOLS or (
        function_name == "lean_extract_have" and _lean_extract_have_is_read_only(args)
    ):
        return False
    snapshot = dict(getattr(agent, "_managed_queue_edit_snapshot", {}) or {})
    if not _queue_edit_snapshot_has_identity(snapshot):
        return False
    return _managed_edit_targets_assignment(
        args,
        str(snapshot.get("active_file", "") or ""),
        function_name=function_name,
    )


def _resolve_project_path(raw_path: str) -> Path | None:
    path_text = str(raw_path or "").strip()
    if not path_text:
        return None
    try:
        path = Path(path_text).expanduser()
        if not path.is_absolute():
            path = Path(_project_root()) / path
        return path.resolve()
    except Exception:
        return None


def _document_formalization_target_path() -> Path | None:
    if not _document_formalization_requested():
        return None
    return _resolve_project_path(_read_text_env("LEANFLOW_FORMALIZATION_TARGET_FILE", ""))


def _tool_edit_paths(function_name: str, args: Mapping[str, Any] | None) -> list[Path]:
    data = dict(args or {})
    raw_paths: list[str] = []
    if function_name in {"write_file", "apply_verified_patch", "lean_extract_have"}:
        raw_paths.append(str(data.get("path", "") or data.get("file_path", "") or ""))
    elif function_name == "patch":
        mode = str(data.get("mode", "replace") or "replace")
        if mode == "replace":
            raw_paths.append(str(data.get("path", "") or ""))
        elif mode == "patch":
            patch_text = str(data.get("patch", "") or "")
            raw_paths.extend(
                match.group(1).strip()
                for match in re.finditer(
                    r"^\*\*\* (?:Add|Update|Delete) File: (.+)$",
                    patch_text,
                    flags=re.MULTILINE,
                )
            )
    resolved = [_resolve_project_path(raw) for raw in raw_paths if raw]
    return [path for path in resolved if path is not None]


def _tool_proposed_edit_text(function_name: str, args: Mapping[str, Any] | None) -> str:
    data = dict(args or {})
    if function_name == "write_file":
        return str(data.get("content", "") or "")
    if function_name == "patch":
        mode = str(data.get("mode", "replace") or "replace")
        if mode == "replace":
            return str(data.get("new_string", "") or "")
        if mode == "patch":
            return str(data.get("patch", "") or "")
    if function_name == "apply_verified_patch":
        return str(data.get("patch", "") or "")
    return ""


def _assigned_candidate_declaration_raw(source: str, target_symbol: str) -> str:
    """Return one exact assigned declaration from an in-memory source image."""
    entry = next(
        (
            item
            for item in _declaration_line_index_from_text(source)
            if _declaration_matches_target(item, target_symbol)
        ),
        None,
    )
    return str((entry or {}).get("text", "") or "")


def _assigned_candidate_declaration(source: str, target_symbol: str) -> str:
    """Return one normalized assigned declaration from an in-memory source image."""
    return _normalize_failed_attempt_candidate_declaration(
        _assigned_candidate_declaration_raw(source, target_symbol)
    )


def _preview_managed_candidate_declaration(
    function_name: str,
    args: Mapping[str, Any] | None,
    *,
    before_text: str,
    target_symbol: str,
) -> str:
    """Return the exact proposed assigned declaration without writing source."""
    after_text = managed_edit_rollback.preview_candidate_source(
        function_name,
        args,
        before_text,
    )
    if not after_text:
        return ""
    candidate = _assigned_candidate_declaration(after_text, target_symbol)
    before = _assigned_candidate_declaration(before_text, target_symbol)
    return candidate if candidate and candidate != before else ""


def _pending_managed_candidate_declaration(
    agent: Any,
    function_name: str,
    args: Mapping[str, Any] | None,
) -> str:
    """Capture the assigned candidate before a tool or queue guard rolls it back."""
    snapshot = dict(getattr(agent, "_managed_queue_edit_snapshot", {}) or {})
    if not _queue_edit_snapshot_has_identity(snapshot):
        return ""
    target_symbol = str(snapshot.get("target_symbol", "") or "").strip()
    active_file = str(snapshot.get("active_file", "") or "").strip()
    before_text = str(snapshot.get("before_text", "") or "")
    if not target_symbol or not active_file or not before_text:
        return ""
    try:
        current_text = Path(active_file).read_text(encoding="utf-8")
    except OSError:
        current_text = ""
    if current_text and current_text != before_text:
        candidate = _assigned_candidate_declaration(current_text, target_symbol)
        before = _assigned_candidate_declaration(before_text, target_symbol)
        if candidate and candidate != before:
            return candidate
    return _preview_managed_candidate_declaration(
        function_name,
        args,
        before_text=before_text,
        target_symbol=target_symbol,
    )


def _pending_helper_refreshes_rejected_candidate_context(
    autonomy_state: Mapping[str, Any],
    *,
    target_symbol: str,
    active_file: str,
    candidate: str,
    previous: Mapping[str, Any],
) -> tuple[str, ...]:
    """Return newly banked helpers that make an older rejection context stale."""
    if not isinstance(autonomy_state, dict):
        return ()
    pending = helper_integration_pending.load(autonomy_state)
    if pending is None or pending.exhausted or not pending.matches(target_symbol, active_file):
        return ()
    referenced = tuple(
        name
        for name in pending.helper_names
        if re.search(
            rf"(?<![A-Za-z0-9_']){re.escape(name)}(?![A-Za-z0-9_'])",
            candidate,
        )
    )
    if not referenced:
        return ()
    prior_revision = str(previous.get("source_revision_sha256", "") or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{64}", prior_revision):
        detail = " ".join(str(previous.get(key, "") or "") for key in ("reason", "gate_verdict"))
        match = re.search(
            r"\brestored at revision\s+([0-9a-f]{64})\b",
            detail,
            flags=re.IGNORECASE,
        )
        prior_revision = match.group(1).lower() if match is not None else ""
    current_revision = _source_revision_sha256(active_file).lower()
    if not prior_revision or not current_revision or prior_revision == current_revision:
        return ()
    return referenced


def _rejected_candidate_replay_pre_tool_guard(
    agent: Any,
    function_name: str,
    args: Mapping[str, Any] | None,
    autonomy_state: Mapping[str, Any],
) -> str | None:
    """Reject an assigned candidate or renamed helper already rejected by Lean."""
    if function_name not in {"patch", "write_file", "apply_verified_patch"}:
        return None
    assignment = dict(autonomy_state.get("current_queue_assignment") or {})
    target_symbol = str(assignment.get("target_symbol", "") or "").strip()
    active_file = str(assignment.get("active_file", "") or "").strip()
    if (
        not target_symbol
        or not active_file
        or not _managed_edit_targets_assignment(
            args,
            active_file,
            function_name=function_name,
        )
    ):
        return None
    try:
        before_text = Path(active_file).read_text(encoding="utf-8")
    except OSError:
        return None
    after_text = managed_edit_rollback.preview_candidate_source(
        function_name,
        args,
        before_text,
    )
    rejected_helper = managed_edit_rollback.matching_new_rejected_helper(
        autonomy_state,
        before_source=before_text,
        after_source=after_text,
        target_symbol=target_symbol,
        active_file=active_file,
        source_revision_sha256=_source_revision_sha256(active_file),
    )
    if rejected_helper is not None:
        with contextlib.suppress(Exception):
            _record_agent_activity(
                agent,
                "rejected-helper-replay-blocked",
                (
                    "Blocked renamed replay of rejected helper "
                    f"{rejected_helper.get('replayed_name', '')}"
                ),
                target_symbol=target_symbol,
                active_file=active_file,
                blocked_tool=function_name,
                rejected_helper_name=str(rejected_helper.get("name", "") or ""),
                replayed_helper_name=str(rejected_helper.get("replayed_name", "") or ""),
                provider_called=False,
                lean_started=False,
                campaign_progress=False,
            )
        return json.dumps(
            {
                "success": False,
                "status": "rejected_helper_replay",
                "blocked_tool": function_name,
                "target_symbol": target_symbol,
                "active_file": active_file,
                "patch_applied": False,
                "check_passed": False,
                "provider_called": False,
                "lean_started": False,
                "rejected_helper_name": rejected_helper.get("name", ""),
                "replayed_helper_name": rejected_helper.get("replayed_name", ""),
                "prior_rejection": rejected_helper.get("reason", ""),
                "required_action": (
                    "This helper has the same statement and proof as a concrete failed "
                    "check_helper candidate; renaming it does not change the rejection. "
                    "Use the retained diagnostic and make a materially different helper."
                ),
            },
            ensure_ascii=False,
        )
    candidate = _preview_managed_candidate_declaration(
        function_name,
        args,
        before_text=before_text,
        target_symbol=target_symbol,
    )
    if not candidate:
        return None
    previous = managed_edit_rollback.matching_rejected_candidate(
        _scoped_failed_attempt_entries(
            autonomy_state,
            target_symbol=target_symbol,
            active_file=active_file,
        ),
        candidate,
    )
    if previous is None:
        return None
    refreshed_helpers = _pending_helper_refreshes_rejected_candidate_context(
        autonomy_state,
        target_symbol=target_symbol,
        active_file=active_file,
        candidate=candidate,
        previous=previous,
    )
    if refreshed_helpers:
        with contextlib.suppress(Exception):
            _record_agent_activity(
                agent,
                "rejected-candidate-replay-context-refreshed",
                (
                    f"Admitted one previously rejected candidate for {target_symbol} "
                    "after authenticated helper insertion changed its elaboration context"
                ),
                target_symbol=target_symbol,
                active_file=active_file,
                admitted_tool=function_name,
                prior_attempt=previous.get("attempt"),
                referenced_helpers=list(refreshed_helpers),
                source_revision_sha256=_source_revision_sha256(active_file),
                provider_called=False,
                lean_started=False,
                campaign_progress=False,
            )
        return None
    with contextlib.suppress(Exception):
        _record_agent_activity(
            agent,
            "rejected-candidate-replay-blocked",
            f"Blocked exact replay of rejected candidate for {target_symbol}",
            target_symbol=target_symbol,
            active_file=active_file,
            blocked_tool=function_name,
            prior_attempt=previous.get("attempt"),
            prior_proof_shape=str(previous.get("proof_shape", "") or ""),
            provider_called=False,
            lean_started=False,
            campaign_progress=False,
        )
    return json.dumps(
        {
            "success": False,
            "status": "rejected_candidate_replay",
            "blocked_tool": function_name,
            "target_symbol": target_symbol,
            "active_file": active_file,
            "patch_applied": False,
            "check_passed": False,
            "provider_called": False,
            "lean_started": False,
            "prior_attempt": previous.get("attempt"),
            "prior_proof_shape": previous.get("proof_shape", ""),
            "prior_rejection": previous.get("reason", ""),
            "required_action": (
                "Do not rerun this exact rejected declaration. Preserve its diagnostics and "
                "make a materially different candidate, isolate a named helper, or change routes."
            ),
        },
        ensure_ascii=False,
    )


def _suggestion_only_source_patch_guard(
    agent: Any,
    function_name: str,
    args: Mapping[str, Any] | None,
    autonomy_state: Mapping[str, Any],
) -> str | None:
    """Redirect newly introduced tactic suggestions away from production source."""
    if function_name not in {"patch", "write_file", "apply_verified_patch"}:
        return None
    assignment = dict(autonomy_state.get("current_queue_assignment") or {})
    target_symbol = str(assignment.get("target_symbol", "") or "").strip()
    active_file = str(assignment.get("active_file", "") or "").strip()
    if (
        not target_symbol
        or not active_file
        or not _managed_edit_targets_assignment(
            args,
            active_file,
            function_name=function_name,
        )
    ):
        return None
    try:
        before_text = Path(active_file).read_text(encoding="utf-8")
    except OSError:
        return None
    after_text = managed_edit_rollback.preview_candidate_source(
        function_name,
        args,
        before_text,
    )
    if not after_text:
        return None
    suggestions = managed_edit_rollback.introduced_suggestion_tactics(
        before_text,
        after_text,
    )
    if not suggestions:
        return None
    with contextlib.suppress(Exception):
        _record_agent_activity(
            agent,
            "suggestion-only-source-patch-blocked",
            f"Redirected tactic-suggestion probe for {target_symbol} away from source mutation",
            target_symbol=target_symbol,
            active_file=active_file,
            blocked_tool=function_name,
            suggestion_tactics=list(suggestions),
            provider_called=False,
            lean_started=False,
            campaign_progress=False,
        )
    return json.dumps(
        {
            "success": False,
            "status": "isolated_suggestion_probe_required",
            "blocked_tool": function_name,
            "target_symbol": target_symbol,
            "active_file": active_file,
            "suggestion_tactics": list(suggestions),
            "patch_applied": False,
            "check_passed": False,
            "provider_called": False,
            "lean_started": False,
            "required_action": (
                "Do not write `exact?`, `apply?`, or another suggestion tactic into managed "
                "source. Run the probe through LeanProbe (`lean_multi_attempt` or a temporary "
                "`lean_incremental_check` candidate), then submit the resulting concrete term "
                "or tactic script. The current proof source was not mutated. If a suggestion "
                "tactic already exists, remove it in the next edit. This probe does not count "
                "as proof construction."
            ),
        },
        ensure_ascii=False,
    )


